extension StoryVariants {
    static let variantsC: [CaseTemplate] = [marketScaleV1, driveThruDashV1, rareBookLiftV1, churchBellPaintV1, plowMailboxV1, yardSignTheftV1, halloweenEggsV1, pumpkinPatchTheftV1, cemeteryFlowersV1, firewoodLotV1, baitShopTillV1, cartInPondV1, bowlingAlleyScuffleV1, barTabSkipV1, tireSwapScamV1, mowCrewNoShowV1, formulaShopliftV1, perfumeShopliftV1, pizzaOrderScamV1, utilityShutoffCallV1, lockedPhoneSaleV1, towTruckOverchargeV1, stereoNoiseV1, leafBlowerDawnV1, cartParkingFightV1, roadRageGestureV1, shedSprayPaintV1, pepperSprayPartyV1, schoolLotMarijuanaV1, borrowedBikeV1, landfillSalvageV1, cellTowerClimbV1, schoolAfterHoursV1, tailgatingTruckV1, expiredLicenseStopV1, taserCarryV1, voicemailThreatBossV1, stolenTrailerHitchV1, fakeParkingTicketV1, schoolPermitForgeV1, carBreakinGymV1, chaseOnBikeV1, cardSwapGasV1, passwordBorrowV1, ghostKitchenFeeV1, stolenChargerV1, lostPackageLockerV1, rentalTrailerNotReturnedV1, campgroundHookupsV1, hayBaleTheftV1, catchBasinCoverV1, streetSignTheftV1, houseSitterV1, nannyPettyV1, coachFeesV1, campusBikeV1, phoneWaitressV1, glovesShopliftV1, bakerySkipV1, liquorTheftV1, noiseGeneratorV1, paintballStreetV1, snowballCarV1, sprinklerFightV1, bikeLaneShoveV1, fakeCashMarketV1, badCheckTiresV1, stolenCheckbookV1, transitFareV1, radioStationFakeV1, bingoCheatV1, craigslistHorseV1, rentalDepositKeepV1, gardenGrowV1]

    static let marketScaleV1 = SmallCases.make(
        key: "story.marketScale",
        category: .whiteCollar,
        headlines: ["Mulch Delivery Truck Shows Two Yards on Ticket, One in Bed", "Customer Measures Pile After Driver Leaves"],
        law: "falsePretenses",
        spec: "Obtained $140 from {V}, a customer, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} paid {D} $280 for two cubic yards of mulch delivered on {DATE}. After {D} left, {V} measured the pile and found about one cubic yard. A landscape supplier's measure of the truck bed showed it holds a little over one yard. {V} was overcharged $140. {D} says the pile settled and the ticket was right.",
        state: [E(.document, 3, "Delivery Ticket", "A ticket for two cubic yards at $140 each signed by {D}."), E(.physical, 3, "Pile Measurement", "About one cubic yard measured at the delivery site."), E(.document, 2, "Bed Specification", "The truck bed holds about 1.2 cubic yards."), E(.statement, 2, "{V}", "Paid $280 and measured the pile after {D} left.")],
        defense: [E(.statement, 1, "Pile Settled", "{DL} says the pile settled and the ticket was right."), E(.document, 1, "Supplier Note", "A note that mulch can compress by 15 percent after loading.")],
        role: "Customer",
        exam: [.direct("What did you pay {D} for?", "\"$280 for two cubic yards of mulch delivered to my yard. The delivery ticket says two yards at $140 each, signed by {D}.\""), .direct("What did you do after the defendant left?", "\"I measured the pile and found about one cubic yard. That is half of what I paid for.\""), .direct("What did the truck bed specification show?", "\"A bed that holds about 1.2 cubic yards, so it could never have carried two yards in a single load.\""), .direct("How did you order the mulch?", "\"I called {D.his} yard and asked for two cubic yards of hardwood mulch for my front beds. I was quoted $140 per yard and told it would arrive that afternoon.\""), .direct("How did the delivery go?", "\"{D.He} backed a pickup-style dump truck into the driveway, tipped the bed, and handed me a ticket saying two cubic yards. I signed and paid $280 on the spot.\""), .direct("What made you measure the pile?", "\"It looked small for what I had ordered. I laid a tape across it, measured length, width, and height, and worked out about one cubic yard.\""), .cross("{D} says the pile settled and the ticket was right, doesn't {D.he}?", "\"Yes. Mulch does settle some. But it does not drop from two yards to one.\""), .cross("Did you measure the pile right away?", "\"Soon after {D.he} left. I used a tape and did the math twice.\""), .cross("Did the defendant refuse to correct the delivery?", "\"I did not ask right away. I measured first and then I called.\""), .cross("Mulch settles when it sits, doesn't it?", "\"It can, and I allowed for that. A fifteen percent settle would still leave far more than one yard.\""), .cross("You signed the ticket without counting the pile, didn't you?", "\"Yes, I signed when {D.he} handed it over. I had no reason to doubt it until I measured.\"")],
        defenseRole: "Landscape supplier",
        defenseExam: [.direct("How is a cubic yard of mulch measured at your yard?", "\"By bed volume, heaped. We measure the truck bed and count a heaped load as the volume.\""), .direct("How much does this truck hold when loaded?", "\"A little over one yard, about 1.2, even heaped. I have measured that bed myself.\""), .direct("Did the truck leave your yard full that day?", "\"I think so. I do not recall loading it, but it is usually full when it leaves.\""), .direct("What is your role at the supply yard?", "\"I run the landscape supply business that sells mulch to {D} and other haulers. I load and measure trucks every day.\""), .direct("How did you measure this truck?", "\"With a tape and a level, I measured the bed and worked out the volume. It holds about 1.2 cubic yards at the rails.\""), .direct("What did you note about compression?", "\"Fresh mulch can compress about fifteen percent in transit and as it sits. That would make a delivered pile smaller than it looked in the bed.\""), .cross("Does the ticket say two yards?", "\"Yes, the ticket says two. That is what the customer was charged for.\""), .cross("Can a truck that holds 1.2 yards deliver two yards in one trip?", "\"No. It would take two trips, or the ticket would be wrong. I cannot explain it.\""), .cross("Do other drivers deliver half loads?", "\"Not as a rule. I have heard it happens, but not from our yard.\""), .cross("A truck that holds 1.2 yards cannot carry two, can it?", "\"No. Not in one trip, heaped or not.\""), .cross("Compression of fifteen percent would not turn two yards into one, would it?", "\"No. It would take a yard and a half down to about 1.3.\"")],
        theory: ("{D} delivered one yard and billed for two.", "The pile settled and the ticket was right."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} delivered half loads to several customers that week.", "The mulch had settled and compressed in transit."),
        defendant: [.direct("Did you deliver two cubic yards of mulch to {V}?", "\"I delivered a full load, which I believed was two yards. The ticket says two, and I signed it in good faith.\""), .direct("Why is the pile smaller than the ticket says?", "\"Mulch settles and compresses in transit. A heaped load looks bigger on the truck than it does in a pile.\""), .direct("How do you measure a load?", "\"By eye and by the bed. I fill it and heap it, and I count that as two yards.\""), .direct("How do you load the truck for a two-yard order?", "\"I fill the bed heaped, with the mulch piled above the rails. From the yard it always looks like a full two yards.\""), .direct("What did you say when {V} called?", "\"I said the mulch settles in transit and that a heaped load looks bigger when it is fresh. I offered to come out and look at it.\""), .direct("What other deliveries did you make that week?", "\"Several, including one other two-yard order. I loaded each one the same way, and I did not measure the piles afterward.\""), .cross("You delivered half loads to several customers that week, didn't you?", "\"I delivered full loads of what the truck holds. I did not know it was short of two yards.\""), .cross("{V} was overcharged $140. Will you refund it?", "\"If I owe it, I will. I did not mean to cheat anyone.\""), .cross("The bed holds about 1.2 cubic yards, doesn't it?", "\"That is what the supplier measured. I thought it held closer to two when heaped, and I was wrong about that.\""), .cross("You billed $280 for a load that measured a yard, didn't you?", "\"Yes. If the pile is a yard, then I overcharged {V}, and I will make it right.\""), .cross("The truck bed holds about 1.2 yards, so you could not have carried two, could you?", "\"I did not think about the bed size when I wrote the ticket. I should have checked before I quoted two yards.\"")],
        openings: ("{V} paid {D} $280 for two cubic yards of mulch, but measured about one yard in the pile after {D} left. The truck bed holds only about 1.2 cubic yards, and the ticket {D} signed says two.", "The defense will present evidence that mulch settles in transit, that a heaped load looks larger on the truck, and that {D} honestly believed the ticket was right."),
        closings: ("A ticket for two yards, a bed that holds 1.2, and a pile that measures one. {V} paid $140 more than the mulch was worth.", "Mulch that settles and a heaped load that looks bigger than it is. The State must prove {D} knew the ticket was false, and a mistaken estimate is not a fraud."),
        timeline: [(0, "{D} delivers the mulch."), (0, "{V} measures the pile."), (1, "{V} calls {D}."), (3, "{V} reports the overcharge.")],
        identified: "The delivery ticket is signed by {D}.",
        notDone: ["The supplier's loading scale was never read.", "The pile's settling after rain was never measured."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let driveThruDashV1 = SmallCases.make(
        key: "story.driveThruDash",
        category: .property,
        headlines: ["Customer Fills Tank, Walks Inside for Snacks and Leaves With $85 Order", "Pump Camera Shows Plate and Receipt Never Paid"],
        law: "misdLarceny",
        spec: "Stole fuel and goods valued at $85 belonging to {V}, a gas station, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 7:10 p.m. on {DATE}, {D} pumped $60 in gas and then picked up $25 in snacks inside and left without paying for either. The clerk was helping another customer. The pump camera shows {D} filling the tank and the plate. {D} says the register line was too long and {D.he} meant to come back.",
        state: [E(.video, 3, "Pump Camera", "{D} fills the tank, goes inside, and drives off at 7:18 p.m."), E(.document, 3, "Pump Record", "$60 pumped and never paid."), E(.document, 2, "Register Tape", "No sale to {D} that evening."), E(.statement, 2, "Clerk", "Was helping another customer and saw {D} leave.")],
        defense: [E(.statement, 1, "Long Line", "{DL} says the line was long and {D.he} meant to come back."), E(.document, 1, "Card Statement", "A $90 charge at another store ten minutes later.")],
        role: "Gas station clerk",
        exam: [.direct("What is your job at the gas station?", "\"I work the register at the station on the state road. On {DATE} I was on the evening shift, and it was busy for a weeknight.\""), .direct("What do you know about {D}'s visit at about 7:10?", "\"The pump system showed pump four started around 7:10 and ran a little over sixty dollars. I had a line at the register and did not see who was pumping.\""), .direct("What did the camera show about the defendant?", "\"It shows {D} filling the tank, coming inside to pick up some snacks, then walking back out and driving off at 7:18 without paying at the counter.\""), .direct("What did you see at the register?", "\"I was ringing up another customer and saw {DL} go past with a bag of snacks. I called out to the next person in line, and when I looked up {DL} was gone.\""), .direct("What did the register tape show?", "\"No sale to {D.him} that evening. The pump record showed $60 pumped and never paid. The snacks add up to $25, so $85 total.\""), .direct("Did you try to stop the defendant?", "\"I couldn't leave the register with a line, and the pump is across the lot. I saw the plate on the camera afterward and gave it to the deputy.\""), .cross("How long was the line at the register?", "\"Four or five people. Two of them had large orders and a lottery ticket problem, so it moved slowly.\""), .cross("Did the defendant say anything to you on the way out?", "\"No. {D.He} did not say a word to me, and I did not say a word to {D.him}. I was occupied with a customer.\""), .cross("Did the pump show an unpaid order on your screen?", "\"I did not check the pump screen during the rush. I only found out after the fact when I reconciled the pumps.\""), .cross("Is it possible the defendant intended to come back?", "\"I don't know what {D.he} intended. I can only say that {D.he} drove off and did not return that night.\""), .cross("Did anyone else leave without paying that night?", "\"Not that I noticed. The night was busy, and I can't say with certainty, but nothing else came up in the pump reconcile.\"")],
        defenseRole: "Store clerk",
        defenseExam: [.direct("What do you do at the store?", "\"I'm a clerk at the same station, the day shift usually, but I sometimes cover evenings. I was there when the line backed up that night.\""), .direct("How busy was the line that evening?", "\"Packed. A few customers had big orders, and someone was fighting over a lottery ticket. It took a while to clear.\""), .direct("Do customers sometimes pump first and pay inside?", "\"Yes, that is how the pumps work after six. People go in, grab things, and then pay for everything at the counter.\""), .direct("Did you see {D} in line?", "\"I saw {D} standing near the snacks for a while, glancing at the clock. {D.He} didn't seem to be in a rush to leave.\""), .direct("What happens when a customer cannot pay?", "\"They can leave a license or call back, and we tell them to come back with payment. It is not common but it happens.\""), .direct("Does the pump record show unpaid fuel?", "\"Yes, the system flags it for review at the end of the shift. That is how the unpaid sixty dollars was found.\""), .cross("Did you see the defendant leave without paying?", "\"I was helping another customer at the other end of the counter. I only know it from the camera and what the clerk said.\""), .cross("Did the defendant say anything to you about having no card?", "\"No. I did not talk to {D.him} that night. I only know what I saw in line.\""), .cross("Did you ever see the defendant at the station before?", "\"I have seen {DF} before, but I cannot say how often. It was not enough that I would claim to know {DF} well.\""), .cross("Did the defendant return the next day?", "\"Not on my shifts. I was not there when {D.he} came back, if {D.he} did.\""), .cross("Is it station policy to report unpaid fuel?", "\"Yes. It is reported to the manager, and the manager decides whether to call the Sheriff.\"")],
        theory: ("{D} took fuel and snacks and left.", "{D} planned to return after a long line."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had left without paying at the same station twice.", "{DL} had no card with {D.him} and gave up on the line."),
        defendant: [.direct("Why did you go into the store that evening?", "\"I filled up the tank, then went inside to grab snacks and pay. I figured I'd get everything on one bill at the counter.\""), .direct("What happened at the register?", "\"The line was long, and the clerk was dealing with a customer with a lottery problem. I stood there a few minutes, and no one moved forward.\""), .direct("What did you do then?", "\"I realized I didn't have my card on me. I'd left my wallet in the glovebox and was only carrying cash for an earlier errand. I decided to come back.\""), .direct("Why did you leave with the snacks?", "\"I was flustered. I didn't want to hold up the line, and I just walked out, planning to run to the car and return. That was dumb.\""), .direct("Where did you go after you left?", "\"I went to another store ten minutes down the road and put $90 on my card. I was trying to get money for the gas station.\""), .direct("Did you go back?", "\"I meant to, but things came up. I understand how that looks, and I wish I had gone back that night.\""), .cross("You drove away with sixty dollars of gas you hadn't paid for, didn't you?", "\"Yes. I drove away with the gas and the snacks, and I did not pay at the station. I'm not denying that.\""), .cross("You looked right at the clerk as you walked out, didn't you?", "\"Maybe. I saw the clerk was busy and did not interrupt. I should have waited, or told the clerk I'd be back.\""), .cross("You didn't call the station that night to explain, did you?", "\"No. I did not call. I should have, and I did not do it.\""), .cross("You've left that station without paying before, haven't you?", "\"I'm not going to talk about other nights. I'm here about this one, and I did not plan to cheat the station.\""), .cross("The other charge was at a store that doesn't sell gas, isn't it?", "\"Right. It was a $90 purchase at a different store. It was for something else I needed, which is why it was not used for the station.\"")],
        openings: ("{D} pumped sixty dollars in gas, picked up twenty-five dollars in snacks, and drove off at 7:18 without paying at the register. The pump camera shows the plate and the departure, and the register tape shows no sale. You will hear from the clerk who was working that night.", "{D} stood in a long line, realized there was no card in the pocket, and walked out flustered, planning to come back. A charge at another store ten minutes later shows {D} was trying to find money. You will hear from another clerk about how busy that night was."),
        closings: ("Sixty dollars in gas and twenty-five dollars in snacks, taken without a single dollar on the register tape. {D}'s plate is on the camera, and {D} admits driving away. Intending to pay later does not change what {D} did.", "The long line, the missing card, and a purchase at another store ten minutes later point to a flustered person, not a thief. {D} did not run from the plate camera. The State must prove {D} meant to take the goods without paying."),
        timeline: [(0, "7:10 p.m.: {D} starts pumping."), (0, "7:15 p.m.: {D} takes snacks."), (0, "7:18 p.m.: {D} drives off."), (1, "The station sends the pump video.")],
        identified: "The pump camera shows {D}'s plate.",
        notDone: ["The pump's error log was never pulled.", "The cashier was never asked whether the screen showed an unpaid order."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let rareBookLiftV1 = SmallCases.make(
        key: "story.rareBookLift",
        category: .property,
        headlines: ["Visitor Slips Three Antique Maps Into Portfolio at Historical Society Archive", "Sign-In Log and Camera Place Researcher at Map Cabinet"],
        law: "misdLarceny",
        spec: "Stole maps valued at $780 belonging to {V}, a historical society, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} signed in at a historical society archive on {DATE} as a researcher and asked to see the map cabinet. After {D} left, the archivist found three antique county maps missing. The reading room camera shows {D} place folders into a large portfolio at 3:40 p.m. A dealer listed matching maps online a week later. {D} says the maps were mistakenly packed with {D.his} own papers.",
        state: [E(.video, 3, "Reading Room Camera", "{D} places three folders into a large portfolio at 3:40 p.m."), E(.document, 3, "Sign-In Log", "{D}'s name and address on the researcher sheet for the day."), E(.digital, 2, "Dealer Listing", "Three maps matching the society's catalog listed by a dealer a week later."), E(.statement, 2, "Archivist", "Counted the map cabinet after {D} left.")],
        defense: [E(.statement, 1, "Mistake", "{DL} says the maps were mistakenly packed with {D.his} own papers."), E(.document, 1, "Papers List", "A list of {DL}'s research papers showing fourteen folders.")],
        role: "Archivist",
        exam: [.direct("What did {D} ask to see at the archive?", "\"The map cabinet. {D} signed in as a researcher and asked to see it. The sign-in log has {D.his} name and address.\""), .direct("What did you find after the defendant left?", "\"Three antique county maps missing from the cabinet. I counted the cabinet right after {D.he} left.\""), .direct("What does the reading room camera show?", "\"It shows {DL} placing three folders into a large portfolio at 3:40 p.m.\""), .direct("What is your job at the archive?", "\"I am the archivist for a county historical society. I care for the maps, deeds, and photographs, and I supervise the reading room.\""), .direct("What are the missing maps?", "\"Three antique county maps from the 1800s, hand-colored and framed on foam board. They are listed in our catalog with insurance values.\""), .direct("How did the dealer listing come to light?", "\"A colleague sent me a link a week later. It showed three maps with the same borders and annotations as ours, listed by a dealer in another state.\""), .cross("{D} says the maps were mistakenly packed with {D.his} own papers, doesn't {D.he}?", "\"That is what {D.he} says. Researchers bring portfolios, and papers get mixed up.\""), .cross("Who else opened the cabinet that week?", "\"Four people did. That is accurate.\""), .cross("Did you watch the defendant the whole time?", "\"No. I watched part of the time. I was helping other visitors.\""), .cross("Four people opened the cabinet that week, didn't they?", "\"Yes, including two other researchers and a volunteer. Only one of them carried a large portfolio.\""), .cross("You did not count the cabinet between visits, did you?", "\"We count once a year. I counted that afternoon only because {D.his} visit seemed unusual.\"")],
        defenseRole: "Archive volunteer",
        defenseExam: [.direct("Who else opened the map cabinet that week?", "\"Four people did, including two other researchers and a staff member. The cabinet is not locked.\""), .direct("Did you watch {D} during the visit?", "\"Part of the time. I was at the front desk and could see the reading room only some of the time.\""), .direct("Does the archive take an inventory of the maps?", "\"Yearly. We count them once a year. We do not count after every visit.\""), .direct("What is your role at the archive?", "\"I am a volunteer who helps in the reading room two afternoons a week. I pull items for researchers and refile them.\""), .direct("What did you see of the defendant's visit?", "\"{D} looked through the cabinet for a long time and had a large portfolio on the table. I was at the front desk part of the time.\""), .direct("Did others open the cabinet?", "\"Yes, a few researchers over the week. We do not always log who touches which drawer.\""), .cross("Did the defendant carry a portfolio into the reading room?", "\"Yes. {D.He} carried a large portfolio. Many researchers do, to hold notes and papers.\""), .cross("Could the maps have been taken by someone else?", "\"It is possible, because four others opened the cabinet. I cannot say who.\""), .cross("Did you see the defendant put maps in the portfolio?", "\"No. I did not see that. I only saw {D.him} with the portfolio.\""), .cross("You cannot account for every map, can you?", "\"No. We do not inventory daily.\""), .cross("You cannot say whether the defendant took the maps, can you?", "\"No. I was at the desk part of the time. I saw {D.him} at the cabinet and with folders, and I do not know what left the building.\"")],
        theory: ("{D} took maps from the archive and sold them.", "{D} packed the maps by mistake."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had sold maps to the dealer before.", "{DL} had packed in a hurry and the maps were in the folders."),
        defendant: [.direct("Did you take the three maps?", "\"No. I packed in a hurry, and the maps ended up in my folders by mistake. I did not mean to take them.\""), .direct("Why did you pack in a hurry?", "\"I was running late for another appointment, and I swept papers into my portfolio. I did not check each folder.\""), .direct("Do you know the dealer who listed the maps?", "\"I have sold maps to that dealer before. I did not sell these ones.\""), .direct("What was your research that day?", "\"I was studying county boundary changes for a book and asked to see the map cabinet. I was there from about two until four.\""), .direct("Why were you in a hurry?", "\"I had another appointment across town and had to pack quickly. I scooped my folders into the portfolio and left.\""), .direct("What do you do with maps you collect?", "\"I sometimes sell duplicates and spares to a dealer I have known for years. That is how I know the dealer.\""), .cross("A dealer listed maps matching the society's catalog a week later, didn't the dealer?", "\"Yes. I know that looks bad. I did not take them to the dealer.\""), .cross("You put three folders into a large portfolio on camera, didn't you?", "\"I put my own folders in. The maps were in the folders. I did not know.\""), .cross("Why did you not call the archive when you found the maps?", "\"I did not find them until later, and I was ashamed. I should have called.\""), .cross("You had sold maps to this dealer before, hadn't you?", "\"Yes, my own maps and reprints. I never sold anything from the archive.\""), .cross("Three folders went into the portfolio at 3:40, didn't they?", "\"Yes, on camera. I believed they were mine.\"")],
        openings: ("{D} signed in as a researcher at a historical society archive and asked for the map cabinet. After {D} left, three antique county maps were missing, a camera showed {D} placing folders into a portfolio, and a dealer listed matching maps a week later.", "Listen for the defense evidence, which will show that four others opened the cabinet that week, that {D} packed in a hurry, and that the maps ended up in {D}'s folders by mistake."),
        closings: ("A researcher, a map cabinet, three missing maps, a portfolio on camera, and a dealer's listing a week later. {D} had sold maps to that dealer before.", "Four people opened that cabinet, and papers got mixed in a hurried pack. The State must prove {D} took the maps on purpose and sold them."),
        timeline: [(0, "3 p.m.: {D} asks for the map cabinet."), (0, "3:40 p.m.: {D} packs the portfolio."), (0, "4 p.m.: the archivist counts the maps."), (7, "The dealer lists the maps.")],
        identified: "The sign-in log and camera place {D} at the cabinet.",
        notDone: ["The cabinet's earlier access log was never pulled.", "The map inventory's last check was never confirmed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let churchBellPaintV1 = SmallCases.make(
        key: "story.churchBellPaint",
        category: .property,
        headlines: ["Spray Paint Covers Chapel Door and Sign Overnight", "Doorbell Camera Across Street Records Figure With Cans"],
        law: "injuryRealProperty",
        spec: "Willfully and wantonly injured the real property of {V}, a church, causing damage of $1,800, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A small chapel's front door, sign and stone wall were covered in spray-painted slogans between midnight and 3 a.m. on {DATE}. A doorbell camera across the street shows {D} walking to the chapel with a duffel at 12:20 a.m. and returning with an empty bag. Cleanup and repainting cost $1,800. {D} says {D.he} was walking home from a late shift.",
        state: [E(.video, 3, "Doorbell Camera", "{D} walks to the chapel with a duffel at 12:20 a.m. and leaves at 12:50 a.m."), E(.physical, 3, "Spray Cans", "Four cans in {D}'s garage with paint matching the chapel slogans."), E(.document, 2, "Cleanup Estimate", "$1,800 to clean the door and wall and repaint the sign."), E(.statement, 2, "Deacon", "Found the paint at 6 a.m.")],
        defense: [E(.statement, 1, "Walking Home", "{DL} says {D.he} was walking home from a late shift."), E(.document, 1, "Time Sheet", "A shift ending at 11:50 p.m. at a warehouse a mile away.")],
        role: "Church deacon",
        exam: [.direct("What is your role at the chapel?", "\"I'm a deacon, and I look after the building. I unlock the doors, check the grounds, and open on Sunday mornings.\""), .direct("What did you find at six o'clock on the morning of {DATE}?", "\"Spray-painted slogans across the front door, the stone wall beside it, and the welcome sign by the road. The paint was dry, so it had been there a while.\""), .direct("How extensive was the damage?", "\"The door, the sign, and about twelve feet of the stone wall. Some of the slogans were large, in black and red. Cleaning stone is not easy.\""), .direct("What did your neighbor's camera show?", "\"The doorbell camera across the street shows {D} walking up toward the chapel at 12:20 carrying a duffel bag, and walking back at 12:50 with the bag empty.\""), .direct("What happened with the spray cans?", "\"Deputies searched {D.his} garage and found four cans of paint matching the colors on our door and wall. I did not see them myself, but I saw the photographs.\""), .direct("What did the cleanup cost?", "\"$1,800 for cleaning the door and wall and repainting the sign. The estimate came from a restoration company the congregation hired.\""), .cross("Did you see {D} anywhere near the chapel that night?", "\"No. I was home asleep. Everything I know is from the neighbor's camera and the deputies.\""), .cross("Does the camera show the defendant painting anything?", "\"No. It shows {DL} walking up and walking away, but the chapel's front is out of view of the camera. The camera does not see the wall.\""), .cross("Did you and the defendant have any disagreement in the past?", "\"{DL} had a falling out with the pastor some weeks before. I was not involved, and I never heard {DL} threaten the chapel.\""), .cross("Was the paint ever tested to match the cans?", "\"Not in a lab. The deputies compared colors by eye. As far as I know, no chemical analysis was done.\""), .cross("Is the chapel visible from the main road at night?", "\"Partly. A streetlight covers the sign. The door and wall are in shadow, so anyone with a can could work there for a while without being seen.\"")],
        defenseRole: "Warehouse coworker",
        defenseExam: [.direct("How do you know {D}?", "\"We work the same warehouse shift. I have been on the line next to {D} for about two years, and we often talk during breaks.\""), .direct("What time did the shift end on {DATE}?", "\"About 11:50 p.m. We clock out at the door, and I remember {D.he} was one of the last to leave because of a late pallet.\""), .direct("How did the defendant get home?", "\"On foot. {D.He} had mentioned that morning that the car was in the shop, and said the walk home was about a mile.\""), .direct("How did the defendant seem at work?", "\"Tired, but normal. {D.He} was joking with the crew about the late pallet. I saw nothing odd in how {D.he} behaved.\""), .direct("Did you see the defendant carry a bag?", "\"Yes. {D.He} carries a duffel with gloves, a thermos, and lunch containers. It was the same bag every day.\""), .direct("Did the defendant ever mention the chapel?", "\"Once, weeks before, {D.he} said there was some trouble with a pastor. {D.He} was hurt, not angry in a violent way.\""), .cross("Did you walk home with {D}?", "\"No. I live in the other direction. After the shift, I did not see where {D.he} went.\""), .cross("How do you know the shift ended at 11:50?", "\"From the time sheet and the badge-in system. I remember it because I clocked out at the same minute.\""), .cross("Do you know what is in the defendant's garage?", "\"No. I've never been to {D.his} house, and I could not tell you what {D.he} keeps there.\""), .cross("Did the defendant ever speak badly of the chapel?", "\"Not the building. {DF} spoke about one person, the pastor. I never heard {DF} say anything about harming property.\""), .cross("Could the defendant have stopped on the way home?", "\"Of course. I can't speak to what {D.he} did after leaving. I only know when {D.he} left.\"")],
        theory: ("{D} painted the chapel overnight.", "{D} was walking home from work."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} had a falling out with the pastor weeks before.", "{DL} did leave work at 11:50 and walked past the chapel."),
        defendant: [.direct("Where were you the night of {DATE}?", "\"I worked a late shift at the warehouse a mile from the chapel. It ended at 11:50 p.m., and I walked home since my car was in the shop.\""), .direct("Which way did you walk?", "\"The shortest route passes the chapel, so I walked by it. I had a duffel with my work gear and a thermos, and I stopped nearby to rest.\""), .direct("Why does the camera show an empty bag when you leave?", "\"I took a break by the chapel steps and pulled out my gloves and a sandwich. The bag was lighter after I ate and dumped trash.\""), .direct("Do you own spray cans?", "\"Yes, four cans in my garage for a fence project. I bought them months ago. They are the ordinary brand every hardware store sells.\""), .direct("What was your history with the chapel?", "\"I had a falling out with the pastor weeks earlier. I was upset, but I never did anything to the building.\""), .direct("What did you do when deputies came to your door?", "\"I told them I had walked past the chapel that night and had nothing to hide. I let them look in my garage.\""), .cross("You were at the chapel at 12:20 a.m., weren't you?", "\"Yes. I walked past and stopped for a few minutes. I'm not denying I was there.\""), .cross("You stayed about thirty minutes, didn't you?", "\"The camera says so. I rested. I don't recall watching the clock, but I will not dispute the time.\""), .cross("Your garage cans match the colors on the door, don't they?", "\"I'm told the colors are similar. Black and red are common, and I didn't use them on the chapel.\""), .cross("You were angry at the pastor, weren't you?", "\"I was hurt and I was angry. I said some things to people. I did not take it out on a building.\""), .cross("You carried a bag in and carried it out lighter, didn't you?", "\"I had trash and a thermos in it, and I put the trash in a bin. That is the lighter bag.\"")],
        openings: ("Between midnight and three, someone covered the chapel's door, sign and stone wall with spray-painted slogans, and the cleanup cost $1,800. A camera across the street shows {D} walking to the chapel with a duffel at 12:20 and leaving with an empty bag. Four matching cans were in {D}'s garage.", "{D} was walking home from a late warehouse shift and stopped to rest by the chapel. The camera shows a person and a bag, not a person with a can. You will hear a coworker confirm when the shift ended and how {D} got home."),
        closings: ("The camera shows {D} arriving with a full bag and leaving with an empty one, thirty minutes later. Four cans of matching paint were in {D}'s garage, and {D} was angry at the pastor. The deacon found the damage at six.", "No camera shows {D} holding a can, the cans were never tested in a lab, and the badge log was never checked against the time sheet. A person walking home past a chapel is not a vandal. The State has to prove it, and it has not."),
        timeline: [(0, "12:20 a.m.: {D} walks to the chapel."), (0, "12:50 a.m.: {D} leaves with an empty bag."), (0, "6 a.m.: the deacon finds the paint."), (1, "The neighbor sends the camera video.")],
        identified: "The doorbell camera identifies {D}.",
        notDone: ["The paint on the cans was never compared in a lab.", "The warehouse badge log was never checked against the time sheet."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let plowMailboxV1 = SmallCases.make(
        key: "story.plowMailbox",
        category: .property,
        headlines: ["Lawn Tractor Plows Through Row of Neighborhood Mailboxes After HOA Dispute", "Cut Posts and Clippings Show Where the Lawn Tractor Went"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a mailbox, causing damage of $140, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 7 a.m. on {DATE}, {D} drove a lawn tractor along a neighborhood street and mowed through a row of five mailbox posts. {V}'s mailbox was one of the five and cost $140 to replace, with the total damage $680. The HOA camera recorded the tractor. {D} had argued with the HOA board over the mailboxes the week before. {D} says the tractor slipped on wet grass.",
        state: [E(.video, 3, "HOA Camera", "{D}'s tractor mows through five mailbox posts at 7:02 a.m."), E(.physical, 2, "Cut Posts", "Five posts cut at the base with grass clippings on the street."), E(.document, 2, "Replacement Estimates", "$680 for five mailboxes and posts."), E(.statement, 2, "{V}", "Found the mailbox on the ground at 7:15 a.m.")],
        defense: [E(.statement, 1, "Wet Grass", "{DL} says the tractor slipped on wet grass."), E(.document, 1, "Weather Record", "Heavy dew and light fog at 7 a.m.")],
        role: "Resident",
        exam: [.direct("What happened on your street at 7 a.m.?", "\"{D} drove a lawn tractor along the street and mowed through a row of five mailbox posts. My mailbox was one of them.\""), .direct("What does the HOA camera show?", "\"{D.his} tractor mowing through five posts at 7:02 a.m. The posts were cut at the base.\""), .direct("What did the damage cost?", "\"$680 for five mailboxes and posts, $140 for mine. I found mine on the ground at 7:15.\""), .direct("What do you remember about that morning?", "\"I was making coffee when I heard a loud crash and a mower engine. I looked out and saw the tractor going down the street through our mailboxes.\""), .direct("What did you find afterward?", "\"My mailbox post was cut at the base and the box lay in the grass with a few envelopes scattered. The next three posts were down too.\""), .direct("How did the HOA know who did it?", "\"The camera on the entrance shows {D.his} tractor and the mowing tracks lead straight to {D.his} yard. A board member brought me the video.\""), .cross("{D} says the tractor slipped on wet grass, doesn't {D.he}?", "\"The grass was wet that morning. I cannot argue.\""), .cross("Had the defendant argued with the HOA board about mailboxes?", "\"Yes, the week before, over mailbox rules.\""), .cross("Did the defendant threaten anyone?", "\"I heard {DL} threatened the board. I did not hear it myself.\""), .cross("You cannot say how wet the grass was at the road edge, can you?", "\"There was dew on my lawn. I did not check the shoulder.\""), .cross("The tractor kept going straight after the first post, didn't it?", "\"Yes. It cut through all five before turning into {D.his} driveway.\"")],
        defenseRole: "HOA board member",
        defenseExam: [.direct("Was there a dispute between {D} and the HOA?", "\"Over mailbox rules. The board sent a notice about the posts, and {D} did not like it.\""), .direct("Did the dispute escalate?", "\"Some. {D.He} said things at a board meeting that were sharp. But {D.he} did not scream or lunge.\""), .direct("Did the defendant threaten anyone on the board?", "\"No. Not that I heard. {D.He} was angry, but I did not hear a threat.\""), .direct("How do you serve on the HOA board?", "\"I am a board member, and I sit through the monthly meetings. I helped draft the mailbox notice.\""), .direct("What happened at the board meeting?", "\"{D.He} complained loudly about the mailbox rules and said the board should stay out of it. It got heated but stayed verbal.\""), .direct("What did you see that morning?", "\"I saw the tractor on the street from my porch and heard the posts break. I did not see the start.\""), .cross("Did you see the tractor on the street that morning?", "\"Yes, on the street. I saw it from my window just before the posts came down.\""), .cross("Did the tractor appear to be out of control?", "\"Not clearly. It kept going straight through all five posts.\""), .cross("Was the grass wet that morning?", "\"Yes. There was dew on everything, and the street was damp.\""), .cross("{D} said something about dealing with the mailboxes, didn't {D.he}?", "\"Something like that, in anger. I did not hear a specific plan.\""), .cross("The tractor did not seem to swerve, did it?", "\"No. It went straight through all five.\"")],
        theory: ("{D} drove through mailboxes after a dispute.", "The tractor slipped on wet grass."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had threatened the board about the mailboxes.", "The grass was wet and the tractor's brakes were poor."),
        defendant: [.direct("Did you mow through the mailbox posts on purpose?", "\"No. The tractor slipped on wet grass, and it slid through the posts. I did not steer into them.\""), .direct("Why were you out on the tractor at 7 a.m.?", "\"I was mowing before the heat. It was a routine morning, and I did not plan to cause any damage.\""), .direct("What about the argument with the HOA board?", "\"We disagreed about mailbox rules. It was heated, but I did not plan to retaliate.\""), .direct("What were the road conditions?", "\"Heavy dew and light fog at seven. The grass along the shoulder was slick and the street was damp.\""), .direct("What happened with the tractor?", "\"I took the edge to avoid the center of the road, and the rear wheels slid sideways. I hit the first post and could not stop.\""), .direct("How did you feel about the board?", "\"Angry. I had gotten a notice about my own mailbox and thought the board was picking on me.\""), .cross("You told the board you would 'deal with' the mailboxes, didn't you?", "\"I said something sharp in anger.\""), .cross("The tractor's brakes were poor, weren't they?", "\"Yes. They were not good. I should have fixed them.\""), .cross("Five posts in a row and cut at the base. Is that a slip?", "\"It is how it happened. I know it looks deliberate.\""), .cross("Five posts in a row is a long slide, isn't it?", "\"It is, and I know it looks odd. The brakes were worn and I could not steer out of it.\""), .cross("You argued with the board the week before, didn't you?", "\"Yes. I said something sharp, and I regret it deeply.\"")],
        openings: ("At 7 a.m., {D} drove a lawn tractor along a neighborhood street and mowed through a row of five mailbox posts, including {V}'s. {D} had argued with the HOA board over the mailboxes the week before, and the HOA camera recorded it.", "Weigh the defense proof, which will show that the grass was wet, that the tractor's brakes were poor, and that {D} slid into the posts without intending harm."),
        closings: ("Five posts cut at the base, a tractor on camera, and a dispute with the HOA a week earlier. A tractor does not slide straight through five posts by accident.", "Wet grass, poor brakes, and a heated dispute that never became a threat. The State must prove {D} drove into the posts on purpose."),
        timeline: [(-7, "{D} argues with the HOA board."), (0, "7:02 a.m.: the tractor mows the mailboxes."), (0, "7:15 a.m.: {V} finds the damage."), (1, "The HOA sends the camera video.")],
        identified: "The tractor's mowing tracks lead to {D}'s yard.",
        notDone: ["The HOA's complaint file was never read.", "The tractor's blade was never matched to the cut posts."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let yardSignTheftV1 = SmallCases.make(
        key: "story.yardSignTheft",
        category: .property,
        headlines: ["Bicycle With Trailer Hauls Off Thirty Campaign Signs Before Dawn", "Neighbor Camera Shows Signs Stacked on Cargo Trailer"],
        law: "misdLarceny",
        spec: "Stole campaign signs valued at $330 belonging to {V}, a campaign, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Thirty campaign yard signs worth $330 were pulled from lawns and road shoulders on {DATE} between 4 and 5 a.m. A neighbor's camera shows {D} riding a bicycle towing a cargo trailer stacked with signs. {V}, a campaign volunteer, found the empty stakes at 7 a.m. and the signs turned up in {D}'s garage. {D} says the signs violated a town ordinance and {D.he} was cleaning up.",
        state: [E(.video, 3, "Neighbor Camera", "{D} tows a cargo trailer stacked with signs at 4:30 a.m."), E(.physical, 3, "Signs", "Thirty campaign signs found in {D}'s garage with campaign stakes still attached."), E(.document, 2, "Sign Order", "A campaign order for thirty-five signs for $330."), E(.statement, 2, "{V}", "Placed the signs with the homeowners' permission.")],
        defense: [E(.statement, 1, "Ordinance", "{DL} says the signs violated a town ordinance and {D.he} was cleaning them up."), E(.document, 1, "Town Ordinance", "An ordinance limiting signs in the road right-of-way.")],
        role: "Campaign volunteer",
        exam: [.direct("What happened to your campaign signs?", "\"Thirty signs worth $330 were pulled from lawns and road shoulders between 4 and 5 a.m. I found empty stakes at 7.\""), .direct("What does the neighbor's camera show?", "\"It shows {D} riding a bicycle towing a cargo trailer stacked with signs at about 4:30 a.m.\""), .direct("Where did the signs turn up?", "\"In {D.his} garage, with the campaign stakes still attached. The campaign had ordered thirty-five signs.\""), .direct("How did you place the signs?", "\"I put about thirty on lawns with the owners' permission and a few along the road edge near intersections. Each was staked with our campaign's yellow stakes.\""), .direct("What did you find at 7 a.m.?", "\"Bare stakes and empty holes along three streets. Some stakes were bent, and a couple lay in the grass.\""), .direct("How was {D} identified?", "\"A neighbor's camera shows a bicycle towing a cargo trailer stacked with signs at 4:30. Deputies traced the plate to {D.him} and found the signs in the garage.\""), .cross("{D} says the signs violated a town ordinance, doesn't {D.he}?", "\"Some were on the road shoulder, where the ordinance does not allow signs. I will agree to that.\""), .cross("Did you place the signs with the homeowners' permission?", "\"Yes, on lawns. The road shoulder ones I am not sure about.\""), .cross("Did {D} work for a rival campaign?", "\"I do not know. I have no evidence of that.\""), .cross("Some signs were on the road shoulder, weren't they?", "\"A few, yes. I knew about the town ordinance but did not think those would bother anyone.\""), .cross("You do not know whether the defendant supports another candidate, do you?", "\"No. I have no evidence of that.\"")],
        defenseRole: "Campaign volunteer",
        defenseExam: [.direct("How many signs did the campaign place?", "\"Thirty-four, I believe. I helped place most of them on lawns and along a few roads.\""), .direct("Were they all on private property?", "\"Some were not. A few were on the road shoulder, where the ordinance does not allow them.\""), .direct("Do people remove old campaign signs often?", "\"Often. After elections, volunteers and neighbors take them down. Sometimes before, too.\""), .direct("What was your role in the campaign?", "\"I volunteered for several months, putting up signs and knocking on doors. I helped place about thirty-four signs.\""), .direct("Were all the signs placed legally?", "\"Most were on lawns with permission. A few were on the shoulder, and we had been told about the ordinance.\""), .direct("What did you learn about {D}?", "\"That {D} had posted online about the campaign. I do not know why {D.he} was angry.\""), .cross("Did you hear about the defendant posting online?", "\"Yes. I heard {DF} posted that the campaign 'had it coming.' That bothered me.\""), .cross("Did the defendant work for a rival campaign?", "\"I do not know. I never saw {D.him} with any campaign.\""), .cross("Were the signs on private lawns removed too?", "\"Yes. Many were on lawns with the owners' permission.\""), .cross("You do not know of any link between the defendant and a rival campaign, do you?", "\"No. I never saw {D.him} with a rival.\""), .cross("You do not know what the defendant said online before the signs came down, do you?", "\"Only what I was told afterward. I did not see the post myself, and I cannot say what {D.he} meant by it.\"")],
        theory: ("{D} took campaign signs at night.", "{D} was cleaning up ordinance violations."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had posted online that the campaign 'had it coming.'", "Some signs were on the road shoulder in violation of the ordinance."),
        defendant: [.direct("Did you take the campaign signs?", "\"Yes, I took them. Some were on the road shoulder in violation of the ordinance, and I thought I was cleaning up.\""), .direct("Why did you go out at 4:30 a.m.?", "\"It was quiet. I did not want to be bothered, and I figured I could clear the signs without any fuss.\""), .direct("Why were the signs in your garage?", "\"I kept them there to give to the town office. I had not gotten around to it.\""), .direct("What led you to take the signs?", "\"I had seen signs on the shoulder and read the ordinance. I decided to clear the ones that broke it.\""), .direct("Why did you take signs from lawns too?", "\"I was tired and took the whole row without checking. I should have left the ones on private land.\""), .direct("What did you do with them?", "\"I took them to my garage and planned to bring them to the town clerk. I was angry and I did not call first.\""), .cross("Signs on private lawns were taken too, weren't they?", "\"Yes. I should not have taken those. I got carried away.\""), .cross("You posted online that the campaign 'had it coming,' didn't you?", "\"I did. I was angry about the signs.\""), .cross("The stakes were still attached. Wasn't that a hint they were the campaign's?", "\"Yes. I knew whose they were.\""), .cross("You posted that the campaign had it coming, didn't you?", "\"Yes, the night before, in anger. It did not help my case.\""), .cross("The stakes were still on the signs, weren't they?", "\"Yes. I knew whose they were.\"")],
        openings: ("Thirty campaign yard signs worth $330 were pulled from lawns and road shoulders between 4 and 5 a.m. A neighbor's camera shows {D} towing a trailer stacked with signs, and the signs were found in {D}'s garage.", "Jurors will hear that some signs violated a town ordinance on the road shoulder and that {D} believed {D.he} was cleaning up."),
        closings: ("Thirty signs, a trailer on camera at 4:30 a.m., stakes still attached, and the signs in {D}'s garage. {D} had posted that the campaign had it coming.", "A resident who thought the signs broke a town ordinance and cleared them out. The State must prove {D} meant to steal rather than clean up."),
        timeline: [(0, "4 a.m.: the signs are pulled."), (0, "4:30 a.m.: {D}'s trailer passes the camera."), (0, "7 a.m.: {V} finds the empty stakes."), (1, "Deputies find the signs in {D}'s garage.")],
        identified: "The neighbor's camera identifies {D}.",
        notDone: ["The campaign's sign count was never reconciled.", "The trailer was never searched for the signs."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let halloweenEggsV1 = SmallCases.make(
        key: "story.halloweenEggs",
        category: .property,
        headlines: ["Cars on One Block Pelted With Eggs From Passing Pickup", "Door Camera Shows Egg Throwing From Truck Bed"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, a car, causing damage of $540, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 9:05 p.m. on {DATE}, a pickup drove slowly down a residential street while {D} threw eggs from the truck bed at parked cars. {V}'s car was hit seven times and the eggs etched the clear coat. A door camera recorded the pickup and {D}. The detailing and repainting cost $540. {D} says it was a Halloween prank.",
        state: [E(.video, 3, "Door Camera", "{D} throws eggs from the bed of a slow pickup at 9:05 p.m."), E(.physical, 2, "Egg Residue", "Eggshell and etched clear coat across the hood and roof."), E(.document, 2, "Detailing Estimate", "$540 to compound and repaint the hood and roof."), E(.statement, 2, "Neighbor", "Saw the pickup crawl along the block.")],
        defense: [E(.statement, 1, "Halloween Prank", "{DL} says it was a Halloween prank."), E(.document, 1, "Egg Receipt", "A receipt for three dozen eggs at 6 p.m.")],
        role: "Car owner",
        exam: [.direct("Where were you the evening of {DATE}?", "\"At home on my street. It was Halloween night, and I had parked my car at the curb in front of my house about an hour earlier.\""), .direct("How did you learn something had happened to your car?", "\"A neighbor knocked and told me a pickup had been going down the block and someone in the bed had been throwing eggs. I went outside around 9:15.\""), .direct("What did you find on your car?", "\"Eggshell and dried yolk all over the hood and roof and down the windshield. I counted seven hits. The paint looked dull and cloudy under the flashlight.\""), .direct("What did the camera show?", "\"A neighbor's door camera shows a pickup crawling down the block at 9:05, and {D} standing in the bed, throwing eggs at parked cars on both sides.\""), .direct("What happened to the clear coat?", "\"The eggs etched it. The shop said the acid in the egg had eaten into the finish, so it needed compounding on the hood and roof.\""), .direct("What did the repair cost?", "\"$540 for the detailing and repainting of the hood and roof. I have the estimate and it matches what the shop told me.\""), .cross("Did you see {D} throw an egg?", "\"No. I was inside. I saw it on the camera later, and a neighbor saw the pickup go by.\""), .cross("Were there other people in the truck?", "\"The camera shows more than one person in the cab, but I could not make out faces. I only recognized {D.him} in the bed.\""), .cross("Was it Halloween night?", "\"Yes. Kids were out earlier in the evening, and trick-or-treating ended around eight. It was after that when the pickup came.\""), .cross("Did the eggs look fresh?", "\"They looked fresh when I found them, runny and wet. I did not smell anything unusual.\""), .cross("Did anyone else's car get hit?", "\"Yes, at least two other cars on the block. I didn't count them, but my neighbor told me about the car next to mine.\"")],
        defenseRole: "Neighbor on the block",
        defenseExam: [.direct("Where do you live in relation to the street?", "\"I'm on the same block as the car owner, three houses down. I was on my porch handing out candy that night.\""), .direct("What did you see around nine?", "\"A pickup crawled down the street with people in the bed. There was shouting and laughing, and I heard a thump or two.\""), .direct("Did you see anyone throw something?", "\"I saw arms moving and something small flying. I thought it was candy until I heard splats on a parked car.\""), .direct("Was it a typical Halloween night on your street?", "\"Mostly. There were kids and parents earlier, then it quieted down. People pull little pranks, but this was the first time I saw something thrown from a truck.\""), .direct("What did you do after the truck passed?", "\"I looked at my own car and found it clean. I walked down to check on the neighbors and found egg on a few cars.\""), .direct("Did you speak to any of the neighbors?", "\"Yes, the owner of the car was one of them. We stood in the street looking at the shells and the hood.\""), .cross("Did you recognize anyone in the truck?", "\"No. It was dark and moving. I could not make out faces.\""), .cross("How many eggs did you see thrown?", "\"I could not count. It was a handful, quick. I did not watch the whole run.\""), .cross("Did you see the damage to the paint?", "\"I saw eggshell and yolk. I'm no expert, and I did not see any etching that night.\""), .cross("Did you call the Sheriff's Office?", "\"No. I figured the owner would. I did not see a reason to get involved beyond helping clean up.\""), .cross("Do you think it was a prank?", "\"It looked like one. But I'm not in a position to say what anyone intended.\"")],
        theory: ("{D} egged cars from a truck bed.", "{D} played a Halloween prank."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had left eggs out in the sun for a week to etch paint.", "The eggs were fresh and {DL} did not mean damage."),
        defendant: [.direct("What were you doing on the night of {DATE}?", "\"It was Halloween and a few of us rode around in a friend's pickup for fun. I stood in the bed with a carton of eggs.\""), .direct("Where did you get the eggs?", "\"I bought three dozen earlier that evening at about six. It was cheap, and we thought it would be a harmless prank.\""), .direct("What did you throw the eggs at?", "\"Parked cars, and a few signs. I know it sounds dumb, but it felt like a harmless Halloween thing at the time.\""), .direct("Did you think it would damage paint?", "\"No. I thought it would wash off with a hose. I've never been told eggs can eat into a clear coat.\""), .direct("What happened when you realized you'd hit someone's car?", "\"I did not know whose car it was. When we heard about the damage the next day, I felt sick.\""), .direct("What would you say to the owner?", "\"That I'm sorry and I will pay to fix it. I'd never meant to cost anyone $540.\""), .cross("You threw eggs at seven cars, didn't you?", "\"If that's what the owner counted. I don't remember the number. I was tossing them as we went down the block.\""), .cross("You bought three dozen eggs for this, didn't you?", "\"I bought them for the night. I did not buy them with a plan to hurt anyone's car.\""), .cross("The truck moved slowly so you could aim, didn't it?", "\"Yes, it was slow. That made it easier to hit cars. It was bad judgment.\""), .cross("You never asked anyone whether eggs could damage a finish, did you?", "\"No. It never crossed my mind that a kitchen staple could ruin a finish. I realize that is the problem.\""), .cross("The other riders were friends of yours, weren't they?", "\"Yes. I don't want to name them. They were with me and I take responsibility for my own throws.\"")],
        openings: ("At 9:05 on Halloween night, a pickup crawled down the street while {D} stood in the bed and threw eggs at parked cars. {V} counted seven hits, the eggs etched the clear coat, and the repair is $540. The door camera recorded all of it.", "Halloween has always had its pranks, and {D} thought a few eggs at parked cars would wash off with a hose. {D} never meant to etch anyone's paint and has said so. You will hear a neighbor describe the night."),
        closings: ("Seven eggs, thrown from a slow-moving truck at cars that belonged to people sleeping or eating dinner. {D} bought three dozen for the purpose. The result was etched paint and a $540 bill.", "A Halloween prank that went too far is still a prank. {D} did not know eggs could etch a finish and has offered to pay. The State must prove {D} intended to damage property, not simply to throw eggs."),
        timeline: [(0, "6 p.m.: {D} buys three dozen eggs."), (0, "9:05 p.m.: {D} starts throwing."), (0, "9:15 p.m.: {V} sees the damage."), (1, "{V} sends the door camera video.")],
        identified: "The door camera identifies {D}.",
        notDone: ["The other riders in the truck were never identified.", "The egg carton was never recovered."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let pumpkinPatchTheftV1 = SmallCases.make(
        key: "story.pumpkinPatchTheft",
        category: .property,
        headlines: ["Trailer Loaded With Christmas Trees at Night From Tree Farm", "Tag and Saw Log Shows Eighteen Trees Cut Without Tags"],
        law: "misdLarceny",
        spec: "Stole Christmas trees valued at $480 belonging to {V}, a tree farm, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A tree farm sold trees on a tag-and-saw system where each tree was tagged before cutting. On the night of {DATE}, {D} cut eighteen untagged trees and loaded them on a trailer. A camera at the entrance caught the plate. The trees were worth $480. {D} says the trees came from the cut pile and were free.",
        state: [E(.video, 3, "Entrance Camera", "{D}'s truck with a loaded trailer leaves at 11:40 p.m. with the plate visible."), E(.document, 3, "Tag and Saw Log", "No sales tags for eighteen trees from the south field."), E(.physical, 2, "Stumps", "Eighteen fresh stumps in the south field."), E(.statement, 2, "{V}", "The cut pile is stacked for the wood chipper and not free.")],
        defense: [E(.statement, 1, "Cut Pile", "{DL} says the trees came from the cut pile and were free."), E(.document, 1, "Sign", "A photo of a sign that says 'free cut pile' dated the week before.")],
        role: "Tree farm owner",
        exam: [.direct("How does your tree farm sell trees?", "\"On a tag-and-saw system. Each tree is tagged before cutting, and the customer pays at the shed.\""), .direct("What did you find after the night of {DATE}?", "\"Eighteen fresh stumps in the south field, with no sales tags for them. A camera at the entrance caught {D}'s plate at 11:40 p.m.\""), .direct("What were the trees worth?", "\"$480. The cut pile is stacked for the wood chipper. It is not free.\""), .direct("How does the tag-and-saw system work at your farm?", "\"Customers walk the field, pick a tree, and a worker hangs a tag on it. They saw it down and bring the tag to the counter to pay.\""), .direct("What did you find in the south field?", "\"Eighteen fresh stumps with no tags in the field log and no sales for them. The tops of the cut trees were scattered where they had been loaded.\""), .direct("Where is the cut pile and what is it for?", "\"It sits behind the barn, stacked for the wood chipper. It is waste wood and trimmings, not trees ready for sale, and a free sign had hung there the week before.\""), .cross("{D} says the trees came from the cut pile, doesn't {D.he}?", "\"That is what {D.he} says. A free sign had been up the week before, and it was not taken down.\""), .cross("Did anyone tell the defendant the trees were free?", "\"Not that I know. The sign was from a prior week.\""), .cross("Did the defendant hide the trailer?", "\"No. It was loaded in the open, with the plate visible.\""), .cross("A free sign was posted near the pile the week before, wasn't it?", "\"Yes, for the leftover brush after an event. It should have come down, and I admit it was left up.\""), .cross("{D} might have believed the trees were free, mightn't {D.he}?", "\"About the pile, possibly. But eighteen standing trees cut at night in the south field are not the pile.\"")],
        defenseRole: "Tree farm worker",
        defenseExam: [.direct("Do customers cut their own trees at your farm?", "\"Yes. They choose a tree, tag it at the shed, and cut it with a saw that we lend them for the day.\""), .direct("Do all customers tag their tree before cutting it?", "\"Most of them do. A few forget and come back to the shed afterward to pay and have the tree tagged.\""), .direct("Did {D} ask about tagging trees at the farm?", "\"I do not remember. Many people ask about it, so I could not say whether {D} asked that day or not.\""), .direct("What do you do at the farm?", "\"I work the lot and the field, tagging trees for customers and cutting brush. I have worked there for two seasons.\""), .direct("What did the free sign say?", "\"Free cut pile. It was posted the week before for trimmings after the holiday rush. Nobody took it down.\""), .direct("What did you see the next morning?", "\"Stumps in the south field and a trail where a trailer had run. I called the owner right away.\""), .cross("Was the tree farm open on the night those trees were cut?", "\"No, it was closed. No one was working, and the gate to the field was shut for the night.\""), .cross("Was the free sign still hanging that night?", "\"I think so. It had been up the week before, and we did not take it down right away.\""), .cross("Would a regular customer cut eighteen trees at night?", "\"No. That would be unusual. Most customers cut one tree during the day and pay at the shed.\""), .cross("The sign was at the pile, not the south field, wasn't it?", "\"Yes. It was by the barn, and the south field is a good distance away.\""), .cross("You never told the defendant to cut trees, did you?", "\"No. I never spoke to {D.him}.\"")],
        theory: ("{D} cut untagged trees and hauled them away.", "{D} took trees from a free cut pile."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} had resold trees at a roadside stand.", "The free sign had been up the week before and was not taken down."),
        defendant: [.direct("Did you cut the eighteen trees?", "\"Yes, I cut them. I thought they came from the cut pile, and I believed they were free.\""), .direct("Why did you go at night?", "\"I was off work then. I saw a free sign and thought I could take them.\""), .direct("Did you resell any trees?", "\"I sold a few at a roadside stand. I thought they were free, so I did not think it was wrong.\""), .direct("Why did you come to the farm that night?", "\"I needed a lot of trees for a church fundraiser and saw the free sign at the road when I drove by. I came back after dark when I had time.\""), .direct("Where did you cut the trees?", "\"From a stand near the pile, which I thought was part of the free area. I used a chainsaw and loaded eighteen onto my trailer.\""), .direct("What did you plan to do with them?", "\"Sell some at a roadside stand and give some to the church. I did not think the farm would mind.\""), .cross("You cut eighteen trees from the south field, didn't you?", "\"I cut what I thought were from the cut pile. I did not check.\""), .cross("There were eighteen fresh stumps. How do you cut a pile?", "\"I may have cut from the field. I was careless.\""), .cross("The free sign was from the week before, wasn't it?", "\"I did not know. I assumed it was current.\""), .cross("You had resold trees at a stand before, hadn't you?", "\"Yes, from my own land and from other places. I sold at the same stand.\""), .cross("You never asked anyone at the farm, did you?", "\"No. It was late, and I trusted the sign.\"")],
        openings: ("A tree farm sells on a tag-and-saw system, tagging each tree before cutting. On the night in question, {D} cut eighteen untagged trees from the south field and loaded them on a trailer, and the entrance camera caught the plate.", "By the end of this trial, the proof will show that a free sign had been left up from the week before and that {D} believed the trees came from a free cut pile."),
        closings: ("Eighteen untagged trees, fresh stumps in the south field, a loaded trailer at 11:40 p.m., and a plate on camera. The farm was closed.", "A free sign that was never taken down and a customer who believed it. The State must prove {D} knew the trees were not free."),
        timeline: [(0, "11 p.m.: {D} starts cutting."), (0, "11:40 p.m.: {D}'s trailer passes the camera."), (1, "{V} finds the stumps."), (2, "{V} reports the theft.")],
        identified: "The entrance camera shows {D}'s trailer.",
        notDone: ["The farm's tag count was never reconciled against sales.", "The trailer's load was never weighed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let cemeteryFlowersV1 = SmallCases.make(
        key: "story.cemeteryFlowers",
        category: .property,
        headlines: ["Solar Lights and Potted Plants Taken From Graves for Resale at Flea Market", "Vendor Photo Matches Plant Left on Veteran's Grave"],
        law: "misdLarceny",
        spec: "Stole solar lights and potted plants valued at $260 belonging to {V}, a cemetery visitor, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} placed two solar lights and a potted chrysanthemum on a family grave on the Saturday of {DATE}. By Sunday evening they were gone along with decorations on a dozen other graves. A flea market vendor posted photos of the same items for sale the next weekend under {D}'s stand name. {D} says the items were bought at an estate sale.",
        state: [E(.digital, 3, "Vendor Photos", "Photos of solar lights and a chrysanthemum in {D}'s stall with a family's ribbon visible."), E(.document, 2, "Cemetery Report", "Decorations missing from twelve graves that weekend."), E(.statement, 2, "{V}", "Recognized the ribbon and pot as the ones left on the grave."), E(.physical, 2, "Recovered Items", "Items found at the stall matching {V}'s receipt.")],
        defense: [E(.statement, 1, "Estate Sale", "{DL} says the items were bought at an estate sale."), E(.document, 1, "Estate Sale Flyer", "A flyer for an estate sale listing garden items.")],
        role: "Cemetery visitor",
        exam: [.direct("What did you leave at the cemetery on the Saturday of {DATE}?", "\"Two solar lights and a potted chrysanthemum on my family's grave. I tied a ribbon around the pot, the same one we use every year.\""), .direct("When did you go back?", "\"On Sunday evening. I wanted to see how the lights looked after dark. The grave was bare. The lights, the pot, everything was gone.\""), .direct("Was it only your family's grave?", "\"No. When I walked the rows I saw other graves missing their decorations too. The cemetery report later listed twelve in all.\""), .direct("How did you find out where your items went?", "\"A week later a friend sent me photos from a flea market vendor's page showing solar lights and a chrysanthemum for sale, and I recognized the ribbon.\""), .direct("How did you recognize the items?", "\"The ribbon is a particular color we always use, tied in the same bow. The pot has a chipped rim I remember, and the solar lights are the model I bought.\""), .direct("What did deputies recover?", "\"At the vendor's stall they found items matching my receipt, which I had kept. The stall is under {D}'s name.\""), .cross("Did you see anyone take anything?", "\"No. I was not there Saturday night or Sunday. I only know the grave was bare when I returned.\""), .cross("Are solar lights and chrysanthemums unique?", "\"The model is sold at many stores. What I'm sure about is the ribbon and the chipped rim, which I recognized.\""), .cross("Could someone else have taken the items and sold them to {D}?", "\"That is possible, in theory. I cannot say who took them. I can say what I saw at the stall.\""), .cross("Did you see the defendant in the cemetery?", "\"No. I did not see {D.him} at the cemetery at any time.\""), .cross("How many other families lost items?", "\"Twelve graves according to the report. I do not know how many of those were found at the stall.\"")],
        defenseRole: "Estate sale buyer",
        defenseExam: [.direct("What do you know about the estate sale?", "\"I ran a table at it. It was held at a house on the north side the Saturday morning of {DATE}, and a flyer advertised garden items.\""), .direct("What was sold?", "\"Lawn furniture, planters, solar path lights, and potted plants. Several people bought bins of lights and pots.\""), .direct("Did you see {D} there?", "\"Yes, {D} showed up early, looked through the garden items, and bought a bin of lights and some plants for cash.\""), .direct("Did the plants have ribbons?", "\"A few had ribbons and bows left over from the owner's garden club. It was normal for the items to be decorated.\""), .direct("How did the defendant pay?", "\"In cash, quickly. The sale was a cash-only event, and {D.he} left with a full bin.\""), .direct("How many people attended?", "\"About thirty, I'd say, over the first two hours. It was crowded in the garden.\""), .cross("Did you write down who bought what?", "\"No. It was a cash sale, and nobody kept a list. I cannot give you names.\""), .cross("Did the defendant buy the particular chrysanthemum the owner described?", "\"I can't say. I know {D.he} bought plants, but I can't tell you which.\""), .cross("Where did the estate sale's items come from?", "\"From the house. A family was cleaning it out. I don't know if every item came from the home or whether some were added.\""), .cross("Do you know the defendant well?", "\"I know {D.him} as a regular at these sales. We have done business before.\""), .cross("Did the defendant mention the cemetery?", "\"No. I did not hear anything about a cemetery that day.\"")],
        theory: ("{D} took grave decorations and resold them.", "{D} bought them at an estate sale."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} had been seen walking the rows that Sunday.", "The estate sale existed and sold similar items."),
        defendant: [.direct("What do you sell at the flea market?", "\"Garden items, ceramics, and household decor. I buy lots from estate sales and sell them at my stall on weekends.\""), .direct("Where did the solar lights and chrysanthemum come from?", "\"From an estate sale I went to on the Saturday morning. A flyer listed garden items, and I bought a bin of lights and a few plants.\""), .direct("Did you see a ribbon on the pot?", "\"Yes, a ribbon was on one pot. I thought it was part of the arrangement and left it on because it looked nice.\""), .direct("Did you go to the cemetery that weekend?", "\"I walk there sometimes in the evenings, since it is a quiet place. That Sunday I might have walked a few rows, but I did not take anything.\""), .direct("Who ran the estate sale?", "\"A family clearing out a house. I do not remember the name. It was a quick sale, and I paid cash and took the bin.\""), .direct("What did you do when the deputies came?", "\"I showed them what I had, told them where I bought it, and gave them the flyer. I was surprised and upset.\""), .cross("You can't name the seller at the estate sale, can you?", "\"No. I paid cash and did not keep a receipt. That looks bad, I know.\""), .cross("Your stall had the same ribbon the owner described, didn't it?", "\"I'm told it did, and I will not argue the ribbon. I did not see it as anything special.\""), .cross("You were seen walking the rows on Sunday, weren't you?", "\"Yes, I admit I was in the cemetery on Sunday. I walk there often, and I did not touch the graves.\""), .cross("You posted the items online within a week, didn't you?", "\"Yes. I post new stock every weekend. I had no reason to hide anything.\""), .cross("A dozen graves lost their decorations, and you sold garden items, didn't you?", "\"I sold garden items from an estate sale. I can see how the two fit together, but they are not the same.\"")],
        openings: ("{V} left two solar lights and a potted chrysanthemum with a ribbon on a family grave, and by Sunday evening they were gone along with decorations from eleven other graves. A week later, photos of the same items appeared at {D}'s stall. The ribbon and the chipped pot rim tie them to the grave.", "{D} sells estate sale finds at a flea market and bought a bin of garden items from a real sale that Saturday morning. A flyer and a vendor who worked the sale confirm the sale existed. The State must prove {D} took the items from graves."),
        closings: ("Twelve graves were stripped in one weekend, and the stall that sold the grave's lights and pot belongs to {D}. {V} recognized the ribbon and the chipped rim, and {D} was seen walking the rows that Sunday. The items were found at {D}'s stall.", "Solar lights and potted plants are sold in thousands of garages, and the estate sale really happened. No one saw {D} take anything from any grave. A resemblance and an opportunity are not proof."),
        timeline: [(0, "Saturday: {V} leaves the items on the grave."), (1, "Sunday: the items are gone."), (7, "The vendor posts photos online."), (8, "{V} sees the posting.")],
        identified: "The vendor stall name identifies {D}.",
        notDone: ["The estate sale's seller was never identified.", "The ribbon on the plant was never traced."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let firewoodLotV1 = SmallCases.make(
        key: "story.firewoodLot",
        category: .property,
        headlines: ["Hay Bales Taken From Roadside Seller Overnight", "Truck Plate on Camera Matches Bale Twine"],
        law: "misdLarceny",
        spec: "Stole hay valued at $400 belonging to {V}, a seller, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A roadside hay seller kept thirty bales stacked beside the road with a hand-lettered sign and an honor box on {DATE}. At 1:30 a.m. a farm store camera caught {D}'s truck loaded high with bales. The stack was intact at 10 p.m. and empty at 6 a.m. The bales were worth $400. {D} says the hay came from {D.his} own field.",
        state: [E(.video, 3, "Farm Store Camera", "{D}'s truck passes at 1:30 a.m. loaded with bales."), E(.physical, 3, "Bale Twine", "Orange twine on bales in {D}'s barn matches the seller's twine."), E(.statement, 2, "{V}", "The stack was full at 10 p.m. and empty at 6 a.m."), E(.document, 2, "Honor Box Count", "$0 in the box overnight.")],
        defense: [E(.statement, 1, "Own Field", "{DL} says the hay came from {D.his} own field."), E(.document, 1, "Field Survey", "A survey of a six-acre hay field owned by {DL}.")],
        role: "Hay seller",
        exam: [.direct("What do you sell beside the road?", "\"Hay. I stack thirty or so bales by the road with a hand-lettered sign and an honor box, and customers leave cash when they take a bale.\""), .direct("What was the condition of the stack on the night of {DATE}?", "\"At ten o'clock, when I checked on my way in, the stack was full, thirty bales. I locked up the tool shed and went to bed.\""), .direct("What did you find at six in the morning?", "\"The rack was empty. All thirty bales were gone. The honor box was there, but there was no money in it.\""), .direct("What did the farm store camera show?", "\"A truck loaded high with bales passing at 1:30 a.m., and the plate on the truck belongs to {D}. The farm store is a short distance down the road.\""), .direct("What was the value of the hay?", "\"About $400, based on what I charge per bale. I report that because it is what I lost.\""), .direct("How did you identify the bales as yours?", "\"The twine. I use orange twine, which is not common, and deputies found orange-twined bales in {D.his} barn.\""), .cross("Did you see {D} loading the bales?", "\"No. I was in bed. I only know what the camera shows and what the deputies found.\""), .cross("Isn't orange twine common?", "\"It is not the most common color, but other farmers use it too. I can't say I'm the only one.\""), .cross("Have you ever allowed anyone to take bales at night?", "\"The honor system works at any hour, if they leave money. I never gave anyone permission to take the whole stack without paying.\""), .cross("Did you check the honor box before ten?", "\"Yes, there was a little cash in it from the day. I did not count it exactly.\""), .cross("Does the defendant grow hay of {D.his} own?", "\"I believe {D.he} has a field down the road. I don't know how much it yielded.\"")],
        defenseRole: "Farmer down the road",
        defenseExam: [.direct("How do you know {D}?", "\"We farm along the same road, about a half mile apart. We have shared equipment and helped each other at harvest for years.\""), .direct("Do you know the defendant's hay field?", "\"Yes, six acres on the back side of the property. I have seen {D} cut it and bale it several times.\""), .direct("What twine does the defendant use?", "\"Orange. I've seen the rolls in {D.his} barn. Half a dozen of us around here buy from the same feed store.\""), .direct("What was the season like for hay?", "\"Wet spring, a late cut. Many of us were short. It was a bad year to be selling.\""), .direct("Did you see the defendant on the road at night?", "\"No. I was in bed. I only know that {D.he} often hauls late when rain is coming.\""), .direct("Would the defendant steal from the stand?", "\"I would be surprised. {D.He} has always been square with everyone on this road. But I was not there that night.\""), .cross("Did you see {D} loading hay from the field that night?", "\"No. I do not know where the bales in the truck were loaded.\""), .cross("Is orange twine unusual?", "\"Not very. A lot of us use it, but I can't say how many.\""), .cross("Could someone else have taken the hay from the stand?", "\"Sure. Anyone with a truck could have. I can't speak to who did.\""), .cross("Do you know the seller of the roadside stand?", "\"Yes, we say hello at the feed store. We have never had trouble.\""), .cross("Did you hear about the theft?", "\"I heard about it later. People talked about it at church. I did not hear anything about it that night.\"")],
        theory: ("{D} took hay from a roadside stand.", "{D} used hay from {D.his} own field."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL}'s own field was cut late and was short that year.", "{DL} did bale hay in orange twine too."),
        defendant: [.direct("Do you grow hay?", "\"Yes, I have a six-acre field on my property. I cut and bale it myself and store it in my barn.\""), .direct("Why was your truck on that road at 1:30 a.m.?", "\"I was moving bales from the back field to the barn. We had a rain forecast, and I wanted to get them under cover before morning.\""), .direct("Where did the hay in your truck come from?", "\"From my field. I cut late this year, and I had some of it baled the day before. It was ready to haul.\""), .direct("What color twine do you use?", "\"Orange, as it happens. I buy it at the farm store by the roll, same as many in this area.\""), .direct("Did you take bales from the roadside stand?", "\"No. I did not take anything from that stand. I would not do that to a neighbor.\""), .direct("Why was your own field short that year?", "\"The cutting was late and the yield was low. I'm not going to hide that. But a short year did not make me a thief.\""), .cross("You were on that road at 1:30 a.m. with a truck full of hay, weren't you?", "\"Yes, I was. It was late because I'd been busy all day, and I wanted to move it before the rain.\""), .cross("Your barn has orange-twined bales, doesn't it?", "\"Yes, because I use orange twine. That does not mean they came from the stand.\""), .cross("You couldn't prove which bales came from your field, could you?", "\"Not easily. Bales look alike. That is the difficulty here.\""), .cross("Your field was short that year, wasn't it?", "\"Short, yes. It was cut late, and I did not make as much as I hoped.\""), .cross("You pass the roadside stand to get to your barn, don't you?", "\"Yes, it's on my route. I see it every day and have never touched it.\"")],
        openings: ("The roadside hay stack was full at ten at night and empty at six in the morning, and a farm store camera caught {D}'s truck loaded high with bales at 1:30. Deputies found orange-twined bales in {D}'s barn matching the seller's twine. The loss is $400.", "{D} cuts and bales {D.his} own hay and was moving bales from the back field before a rain. Orange twine is sold at the feed store to half the farmers on that road. You will hear a neighbor who knows both fields."),
        closings: ("A full stack at ten, an empty rack at six, and in between, {D}'s truck on camera with a high load of bales. The twine in {D}'s barn matches the seller's. The honor box held no money.", "Orange twine is common, bales look alike, and {D} owns six acres of hay. No one saw anyone take a bale from the stand. The State has not proved these bales came from it."),
        timeline: [(0, "10 p.m.: the stack is full."), (0, "1:30 a.m.: {D}'s truck passes the camera."), (0, "6 a.m.: {V} finds the rack empty."), (2, "{V} reports the theft to the Sheriff's Office.")],
        identified: "The truck plate on camera is {D}'s.",
        notDone: ["The honor box's cash was never counted.", "The seller was never asked whether others were allowed to take bales at night."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let baitShopTillV1 = SmallCases.make(
        key: "story.baitShopTill",
        category: .property,
        headlines: ["Roadside Produce Stand Cash Box Lifted While Farmer Loads Watermelons", "Stand Camera Shows Customer Pocket the Cash Box"],
        law: "misdLarceny",
        spec: "Stole $360 belonging to {V}, a produce stand, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} was loading watermelons into a customer's truck behind a produce stand at 1:10 p.m. on {DATE}. {D}, who had come to buy corn, was alone at the front table for two minutes. The stand camera shows {D} lift the cash box lid, take out a fold of bills and walk to a parked car. The cash box was $360 short. {D} says {D.he} was making change.",
        state: [E(.video, 3, "Stand Camera", "{D} takes a fold of bills from the cash box at 1:12 p.m. and walks to a car."), E(.document, 2, "Sales Tally", "$420 in sales recorded by the stand before 1 p.m."), E(.physical, 2, "Cash Box", "A metal box with $60 left and a marker for the morning float."), E(.statement, 2, "{V}", "Was loading watermelons for two minutes.")],
        defense: [E(.statement, 1, "Making Change", "{DL} says {D.he} was making change for a customer."), E(.document, 1, "Corn Purchase", "A $6 receipt for corn written at 1:08 p.m.")],
        role: "Produce stand owner",
        exam: [.direct("What do you own?", "\"A produce stand on the county road. I sell corn, watermelons, and tomatoes. On {DATE} I was working it alone in the early afternoon.\""), .direct("What happened at about 1:10 p.m.?", "\"A customer needed a watermelon loaded into a truck behind the stand, so I walked back there. I left the front table with the cash box on it for about two minutes.\""), .direct("Who was at the front table?", "\"{D}, who had come to buy corn. {DL} had paid at 1:08 for a few ears, and I trusted {DL} to stand there while I helped the other customer.\""), .direct("What did the stand camera show?", "\"At 1:12 {DL} lifts the lid of the cash box, takes out a fold of bills, and walks to a parked car without looking back.\""), .direct("What did you find when you returned?", "\"The cash box was short. The sales tally for the morning was $420, and the box had only $60 left plus the marker for the float.\""), .direct("How much was missing?", "\"$360. I counted it twice with the tally and the float. The numbers were clear.\""), .cross("Did you ask {D} to watch the table?", "\"I said something like, I'll be right back. I did not say watch the money. I assumed the cash box was fine for two minutes.\""), .cross("Did the defendant ever pay you for the corn?", "\"Yes, a $6 receipt for corn was written at 1:08. That part was paid.\""), .cross("Could the defendant have been making change for another customer?", "\"I did not see another customer at the front table. The camera shows nobody else near it at 1:12.\""), .cross("Did you count the float before opening that day?", "\"I set it out, but I did not write the exact number. I only knew it was around a hundred dollars.\""), .cross("Did anyone else have access to the box that morning?", "\"A part-time worker was there until noon. I'm not sure when {D.he} last touched it, but the worker left before one.\"")],
        defenseRole: "Stand worker",
        defenseExam: [.direct("What is your job at the stand?", "\"I work there part-time on weekends, usually till noon. I know the cash box and how the owner keeps the float.\""), .direct("How does the owner manage the cash box?", "\"The owner sets out about a hundred dollars as a float in the morning, and we make change from it. We don't put out the whole day's cash.\""), .direct("Were you there on {DATE}?", "\"I was there until noon, and I left a little before one. I did not see what happened after that.\""), .direct("Did you see {D} that day?", "\"I saw {D} browsing the corn earlier. {D.He} seemed friendly and was talking about recipes.\""), .direct("Did the owner ever ask customers to watch the table?", "\"Sometimes, for a minute or two, like for making change. It is not a rule, but it happens.\""), .direct("Who has access to the cash box?", "\"The owner and me, mostly. Customers should never open it.\""), .cross("Did you see the defendant open the cash box?", "\"No. I had already left by then. I cannot speak to what happened at 1:12.\""), .cross("Did you work at the cash box that morning?", "\"Yes, I made change from it several times. I did not take a count at the end of my shift.\""), .cross("Was the box locked?", "\"No. It's a simple metal box with a lid. There is no lock.\""), .cross("Do you know the defendant?", "\"Only as a customer. I recognized the face but I did not know anything beyond that.\""), .cross("Would you leave a cash box unattended?", "\"Not for long. Two minutes is about the limit I would think was safe.\"")],
        theory: ("{D} took cash from an unattended box.", "{D} was making change for a purchase."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} folded the bills into a pocket and left without buying corn.", "{DL} had been asked to watch the table by a worker."),
        defendant: [.direct("What did you go to the stand for?", "\"Corn. I bought a few ears, paid $6, and the owner took a minute to help another customer behind the stand.\""), .direct("What were you doing at the front table?", "\"I was waiting. A customer was standing near the table and wanted change for a larger bill, and the owner had asked me to watch the table.\""), .direct("What did you do with the cash box?", "\"I opened it to make change for that customer. I took out some bills, and then the customer left without waiting.\""), .direct("Why did you walk to your car with bills?", "\"I had them in my hand when I was heading back to the car to get my own receipt, and I should have put them back.\""), .direct("Did you intend to take the money?", "\"No. I did not plan to take anything. I got distracted and walked off with my pocket full of change.\""), .direct("What did you do when you were questioned?", "\"I told them what happened. I gave them back the amount in my pocket and apologized.\""), .cross("The camera shows you taking a fold of bills, doesn't it?", "\"It shows me reaching in and taking bills. I do not argue with the video.\""), .cross("You walked to your car without telling anyone, didn't you?", "\"Yes. I should have put the bills back first. I was not thinking.\""), .cross("No other customer appears on camera at 1:12, does one?", "\"Not on the camera, that's right. The customer I helped had already walked off by then.\""), .cross("$360 is a lot of change, isn't it?", "\"It is. I did not count it. I just took what was in my hand.\""), .cross("You didn't come back to the stand to return it, did you?", "\"I did not come back. I wish I had. I was thinking about it in the car, and then it was too late.\"")],
        openings: ("{V} stepped behind the stand for two minutes to load a watermelon, and the camera shows {D} lift the lid of the cash box at 1:12, take out a fold of bills, and walk to a car. The box was $360 short. You will see the video and the sales tally.", "{D} had just paid for corn and was asked to watch the table, and a customer asked for change. {D} opened the box, got distracted, and made a mistake. You will hear that there was no lock and that the owner often asks customers to keep an eye on things."),
        closings: ("The sales tally says $420, the box held $60, and the camera shows {D} take the bills and leave. A customer who is trusted for two minutes took $360. That is theft.", "No one saw {D} count the money, and the owner admits {D} was asked to watch the table. The float was never counted before. The State has not shown that {D} meant to keep it."),
        timeline: [(0, "1:08 p.m.: {D} buys corn."), (0, "1:10 p.m.: {V} goes to load watermelons."), (0, "1:12 p.m.: {D} takes the bills."), (0, "1:20 p.m.: {V} finds the cash box short.")],
        identified: "The stand camera identifies {D}.",
        notDone: ["The stand worker's request was never recorded on camera.", "The cash box's float was never counted beforehand."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let cartInPondV1 = SmallCases.make(
        key: "story.cartInPond",
        category: .property,
        headlines: ["Four Rental Paddle Boats Untied and Two Sunk at Park Lake Overnight", "Marina Camera Shows Teens Pushing Boats Into Deep Water"],
        law: "injuryPersonalProperty",
        spec: "Willfully and wantonly injured personal property of {V}, rental paddle boats, causing damage of $1,900, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 11 p.m. on {DATE}, {D} and two friends untied four rental paddle boats at a park marina and pushed them into deep water. Two boats filled with water and sank. The marina's camera recorded the incident. Salvage and repairs cost $1,900. {D} says it was a prank and the boats were supposed to float.",
        state: [E(.video, 3, "Marina Camera", "{D} unties four boats and pushes them out at 11:05 p.m."), E(.document, 2, "Salvage Invoice", "$1,900 to raise two boats and repair four."), E(.physical, 2, "Boat Hulls", "Two hulls holed from striking rocks and one with a missing drain plug."), E(.statement, 2, "Marina Manager", "Found the boats adrift and two submerged.")],
        defense: [E(.statement, 1, "Prank", "{DL} says it was a prank and the boats were supposed to float."), E(.document, 1, "Social Post", "A post saying 'night paddle' posted before the incident.")],
        role: "Marina manager",
        exam: [.direct("What is your role at the marina?", "\"I'm the marina manager. I rent paddle boats from a dock at the park lake and lock them up each night. On {DATE} I closed up at dusk.\""), .direct("What did you find the next morning?", "\"At six I came in and found the boats adrift on the lake. Four were loose and two were submerged, with only the corners of the seats showing.\""), .direct("What did your camera show?", "\"At 11:05 p.m. {D} and two others untie four boats, climb in or push them off, and shove them out into the deep water.\""), .direct("How did the boats sink?", "\"Two hulls struck rocks and filled with water. One boat was missing a drain plug. The others took on water slowly and went down by the morning.\""), .direct("What was involved in the salvage?", "\"We hired a diver and a crane to raise two boats, then repaired four hulls. The invoice came to $1,900.\""), .direct("What happened to your business that week?", "\"I could only rent two boats that weekend, at the busiest time of year. I turned people away.\""), .cross("Did you see {D} do any of it?", "\"No. I was home. I know it from the camera and from what I found.\""), .cross("Did the camera show anyone pulling the drain plugs?", "\"It was dark and the angle was bad. I could not see anyone touch a plug on the video.\""), .cross("Were the boats ever left unsecured before?", "\"Once, a rope was tied loosely, and a boat drifted a few feet. That was not like this.\""), .cross("Were there any other people on the camera?", "\"Two others, but I could not make out their faces. I only recognized {D.him}.\""), .cross("Did the defendant say anything online about a night paddle?", "\"I saw a post after the fact. I don't know whether that was written before or after the incident.\"")],
        defenseRole: "Friend at the marina",
        defenseExam: [.direct("How do you know {D}?", "\"We are friends from school. I was at the lake that night, hanging out near the marina with {D} and another friend.\""), .direct("What was the plan?", "\"A night paddle. It was a joke, a plan to take the paddle boats out, paddle around, and bring them back. Nobody planned to sink anything.\""), .direct("What did the defendant do?", "\"{DF} helped untie a few boats and push them away from the dock. {DF} was laughing and thought it would be a fun prank.\""), .direct("What happened with the boats?", "\"They drifted fast and one tipped. We could see one taking on water and heard a scrape on the rocks.\""), .direct("How did the defendant react?", "\"{DF} looked worried and said we had to catch them. When we could not, {DF} wanted to call the marina and I stopped {D.him}.\""), .direct("Did anyone plan to break the boats?", "\"No. The whole idea was to have fun. Nobody said anything about hurting the boats.\""), .cross("Did you see anyone pull a drain plug?", "\"No. I did not see anyone touch the plugs.\""), .cross("Did you untie boats too?", "\"I helped a little, yes. I am not trying to hide my part.\""), .cross("Why did you run instead of staying?", "\"We were scared. We thought we'd be in trouble. It was a bad decision.\""), .cross("Was there a post about the night paddle?", "\"Yes, {D.he} posted it earlier in the evening. I saw it before we went.\""), .cross("Do you think the boats should have floated?", "\"Yes, they are paddle boats. They usually float fine. I don't know why two sank.\"")],
        theory: ("{D} set rental boats adrift and sank two.", "{D} played a prank that went wrong."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} pulled the drain plugs before pushing the boats out.", "{DL} did not mean to sink anything."),
        defendant: [.direct("What were you doing at the marina at 11 p.m.?", "\"A few of us were out at night, and someone suggested a night paddle. We walked to the marina and saw the boats lined up.\""), .direct("Why did you untie the boats?", "\"We thought it would be funny to take a few out on the water. We untied four and pushed them off, thinking they'd float together.\""), .direct("Did you expect the boats to sink?", "\"No. They were supposed to float. We planned to bring them back before morning.\""), .direct("What did you post online?", "\"A post saying night paddle, before we went. It was a joke with friends. I did not think about the damage.\""), .direct("What happened after you pushed the boats off?", "\"They drifted away faster than we expected. We tried to catch them, and then we heard one start to take water, and we ran.\""), .direct("Looking back, how do you feel about it now?", "\"Terrible. I know I cost the marina money. I will pay what I can.\""), .cross("You untied four boats that did not belong to you, didn't you?", "\"Yes, and I pushed them off. I am not going to claim it was an accident.\""), .cross("You left when the boats began to sink, didn't you?", "\"We left, yes. We should have stayed and helped. We panicked.\""), .cross("The marina was closed and locked, wasn't it?", "\"The boats were tied, not locked, and the dock gate was open. I knew it was closed for the night.\""), .cross("You did not call anyone to say the boats were adrift, did you?", "\"No. That is on me. I was scared and ran.\""), .cross("Who pulled the plugs?", "\"I'm not going to guess about that. I did not do it, and I did not see anyone do it.\"")],
        openings: ("At 11:05 p.m., {D} untied four rental paddle boats at the marina and pushed them into deep water. Two hit rocks and sank, and one was missing a drain plug. The camera records it, and the salvage and repairs cost $1,900.", "{D} and two friends planned a night paddle that was meant to be a joke, and the boats were supposed to float. A post before the incident shows the plan. You will hear from a friend who was there that nobody intended to sink anything."),
        closings: ("Four boats untied after closing, shoved into deep water in the dark, and two on the bottom by morning. The camera shows {D}. The bill is $1,900.", "No one saw anyone pull a plug, and a post before the outing shows a joke, not a plan to destroy. The drain plugs were never examined for tool marks. The State has not proved {D} meant to damage the boats."),
        timeline: [(0, "11:05 p.m.: {D} unties the boats."), (0, "11:20 p.m.: two boats begin to sink."), (0, "6 a.m.: the manager finds them."), (2, "The marina prices the salvage.")],
        identified: "The marina camera identifies {D}.",
        notDone: ["The drain plugs were never examined for tool marks.", "The marina's camera was never checked for the other friends."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let bowlingAlleyScuffleV1 = SmallCases.make(
        key: "story.bowlingAlleyScuffle",
        category: .publicOrder,
        headlines: ["Parent Screams at Referee and Threatens Official After Youth Hockey Game", "Rink Manager Calls Deputies as Parent Blocks Referee's Room"],
        law: "disorderly",
        spec: "Disturbed the peace by threatening a game official and refusing to leave a public ice rink, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "After a youth hockey game on {DATE}, {D}, a parent, screamed at the referee in the corridor and said the referee 'would not get to the car.' {D} blocked the door of the referees' room for ten minutes while other parents and children watched. Rink staff asked {D} to leave twice and called deputies at 8:50 p.m. {D} says {D.he} was only venting.",
        state: [E(.video, 3, "Rink Camera", "{D} blocks the referees' room door and shouts from 8:35 to 8:45 p.m."), E(.statement, 3, "Referee", "Heard {D} say 'you won't get to your car.'"), E(.statement, 2, "Rink Manager", "Asked {D} to leave twice and was refused."), E(.document, 2, "League Rules", "A posted code of conduct for parents.")],
        defense: [E(.statement, 1, "Venting", "{DL} says {D.he} was venting after a bad call and made no threat."), E(.document, 1, "Game Sheet", "The game sheet shows a disputed goal in the last minute.")],
        role: "Rink manager",
        exam: [.direct("What is your position at the rink, and were you on duty after the youth game on {DATE}?", "\"I'm the rink manager. That night I was at the front office when the evening youth game let out at about 8:30, and I walked the corridor during the rush.\""), .direct("What did you see in the corridor near the referees' room?", "\"{D}, a parent from one of the teams, was standing squarely in front of the referees' door, shouting at the officials inside. Other parents and several kids were watching from the bench area.\""), .direct("How long did {D} stay at that door?", "\"Our camera has it from 8:35 to 8:45, a full ten minutes. {D.He} would not move, and the referees could not get out to leave the building.\""), .direct("What did you say to the defendant?", "\"I asked {D.him} to step away from the door and then to leave the rink. I asked twice, politely at first and then firmly. {D.He} refused both times.\""), .direct("What was said that you personally heard?", "\"I heard {DL} loudly accuse the referee of costing the team the game, and I heard the line the referee later repeated to me, that the referee would not make it to the car.\""), .direct("What did you do when the defendant would not leave?", "\"I called the Sheriff's Office at 8:50. Deputies took the report at 9:05, after {D.he} had finally walked out toward the parking lot.\""), .cross("The posted code of conduct applies to parents and not only to players, doesn't it?", "\"Yes, it's posted at the entrance, and each parent signs it at registration. I did not pull {D.his} signed copy that night.\""), .cross("Did the defendant put hands on anyone?", "\"No. {D.He} did not touch the referee, a staff member, or a child. {D.He} stood in the doorway and shouted.\""), .cross("Were you close enough to hear the exact words about the car?", "\"I was about fifteen feet away. I heard the tone clearly and part of the sentence. I got the full words from the referee afterward.\""), .cross("Was there a disputed goal in that game?", "\"I heard that there was an argument over a goal in the last minute. I wasn't at the glass, so I can't say how the call looked.\""), .cross("Did you ask the coach to help calm the defendant?", "\"No. The coach was in the locker room with the kids. I did not think to send for the coach, and I never spoke with the coach about it.\"")],
        defenseRole: "Another parent",
        defenseExam: [.direct("What is your connection to the rink?", "\"My child plays on the same team as {D}'s child, so I sat in the stands for the whole game on {DATE}.\""), .direct("What happened in the last minute of the game?", "\"A goal for the other team that many of us thought was kicked in. The referee allowed it anyway, and the stands erupted.\""), .direct("How did {D} react in the stands?", "\"{DF} was upset, yelling at the referee through the glass and then storming off. A lot of parents were angry, not just {DF}.\""), .direct("Did you see the defendant in the corridor afterward?", "\"I walked past about a minute after the game and saw {DF} talking loudly at the referees' door. I kept going to find my child.\""), .direct("What did you understand the defendant to be saying?", "\"Mostly complaining about the call. I did not hear a clear threat from where I was, only a lot of anger and a loud voice.\""), .direct("How did the defendant behave after the deputies talked to {D.him}?", "\"Quietly. {DF} apologized to the manager and told me later that {D.he} was embarrassed in front of the kids.\""), .cross("Were you close enough to hear every word?", "\"No. I heard pieces from the end of the corridor, and the sound carried badly with all the kids in the hall.\""), .cross("Did you see the defendant block the door?", "\"I saw {DF} standing near it. I did not see whether the referees tried to leave and were stopped.\""), .cross("Did you hear the comment about the car?", "\"Not myself. I heard about it afterward from other parents.\""), .cross("Were you also upset about the goal?", "\"I was, yes, but I took a seat and cooled off. I did not confront anyone.\""), .cross("Have you seen {D} get heated at games before?", "\"{DF} is vocal, like a lot of us. I would call {DF} intense, but I have not seen anything like that corridor scene before.\"")],
        theory: ("{D} threatened an official and blocked a door.", "{D} was venting after a bad call."),
        allocution: "\"It was childish, and I know it.\"",
        truths: ("{DL} had been told at an earlier game to keep away from officials.", "{DL} was frustrated about a goal and did not mean the threat."),
        defendant: [.direct("Why were you in the corridor outside the referees' room?", "\"I was furious about a goal in the last minute that I thought was waved off wrongly. I wanted to ask the referee to explain the call.\""), .direct("Why did you stay in the doorway?", "\"I wasn't thinking about the door. I was standing there talking, and when the referee tried to speak I kept going. I know I was in the way.\""), .direct("What did you say about the referee's car?", "\"I said something like, you won't get to your car with that kind of call. I meant that people would be furious, not that I would do anything.\""), .direct("Did you intend to threaten the referee?", "\"No. It was a stupid thing to say in front of children. I was venting, and I was angrier than I have been at any game.\""), .direct("Was your child watching?", "\"Yes. My kid was standing a few feet away in full gear. That is part of why I feel so bad about how I acted.\""), .direct("What did you do when the manager asked you to leave?", "\"I argued the first time. After the second request I walked to the parking lot and waited by my truck. The deputies talked to me there.\""), .cross("You stayed at that door for ten minutes, didn't you?", "\"If the camera says ten, it was ten. It did not feel that long to me. I'm not going to argue about the clock.\""), .cross("You were told to leave twice, weren't you?", "\"Yes, the manager asked me twice. I refused the first time, because I wasn't done. I shouldn't have said no.\""), .cross("You had been warned at an earlier game to keep away from officials, hadn't you?", "\"Yes, there was a talk about that at an earlier game. I'll admit I did not follow it that night.\""), .cross("The referee was a teenager, wasn't the referee?", "\"A young adult, maybe nineteen. I did not think about the age until later. That makes it worse.\""), .cross("Other children heard you say that, didn't they?", "\"Some of them did. I know that. That is the part I would take back the most.\"")],
        openings: ("After a youth hockey game, {D} stood in front of the referees' door for ten minutes, shouting at the officials and telling the referee that the referee would not make it to the car. The rink camera shows the door being blocked, and the manager asked {D} to leave twice before calling deputies.", "A last-minute goal the stands thought was wrong sent {D} into the corridor, angry and loud, and {D} said something foolish in front of children. {D} never touched anyone, and left when the manager asked a second time. The words were venting, not a plan."),
        closings: ("Ten minutes at a locked-in doorway, a threat about the car, and a manager who had to ask twice. The referee could not leave, and kids watched it all. The camera and the referee's account match.", "{D} shouted and said something regrettable, but never touched anyone or reached for a weapon. The referee was never asked about earlier incidents, and the coach was never interviewed. Anger over a youth hockey call is not an intent to threaten."),
        timeline: [(0, "8:30 p.m.: the game ends."), (0, "8:35 p.m.: {D} blocks the door."), (0, "8:50 p.m.: the manager calls deputies."), (0, "9:05 p.m.: deputies take the report.")],
        identified: "The rink camera identifies {D}.",
        notDone: ["The referee was never asked about earlier incidents.", "The coach was never interviewed about the pulled child."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let barTabSkipV1 = SmallCases.make(
        key: "story.barTabSkip",
        category: .property,
        headlines: ["Diner Says He'll Get Wallet From Car, Never Returns After $140 Dinner", "Hostess Notes Table Left After Entrees and Dessert"],
        law: "misdLarceny",
        spec: "Stole restaurant service valued at $140 belonging to {V}, a restaurant, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 8:45 p.m. on {DATE}, {D} finished a $140 dinner for two at a restaurant and told the server that {D.he} needed to get {D.his} wallet from the car. {D} and a companion walked out and did not return. The server held the check for forty minutes. {D} says the card reader was broken and {D.he} meant to come back.",
        state: [E(.video, 3, "Entrance Camera", "{D} and a companion leave at 8:47 p.m. and do not return."), E(.document, 2, "Check", "A $140 check for two entrees, an appetizer and desserts."), E(.statement, 2, "Server", "Held the check forty minutes before telling the manager."), E(.document, 2, "Reservation Record", "The table was booked under a phone number tied to {D}.")],
        defense: [E(.statement, 1, "Broken Reader", "{DL} says the card reader was broken and {D.he} went for cash."), E(.document, 1, "ATM Receipt", "A cash withdrawal attempt at an ATM at 8:55 p.m. that was declined.")],
        role: "Restaurant server",
        exam: [.direct("What is your job at the restaurant?", "\"I'm a server at a sit-down restaurant. On {DATE} I waited a table of two who were seated around 7:30 p.m. and were mine for the whole evening.\""), .direct("What did {D} and the companion order?", "\"Two entrees, an appetizer, and two desserts. The check came to $140. They were cheerful and ordered a second round of drinks.\""), .direct("What happened at about 8:45?", "\"{D} asked for the check, and when I brought it, {D.he} said the wallet was in the car and went to get it. The companion went along.\""), .direct("Did you see them leave?", "\"I saw them head to the front door. The entrance camera shows them leaving at 8:47. They did not come back to the table.\""), .direct("What did you do when they did not return?", "\"I held the check for forty minutes, thinking they might be on a call or having trouble finding the car. I walked outside once and did not see them.\""), .direct("Then what?", "\"At about 9:30 I told the manager, who pulled the reservation. The table was booked under a phone number tied to {D.him}.\""), .cross("Did the defendant say anything about a broken card reader?", "\"No. {D.He} said only that the wallet was in the car. I heard nothing about a card reader.\""), .cross("Was the card reader working that night?", "\"I used it all evening for other tables, so as far as I know it was fine. The terminal was never tested for a failure.\""), .cross("Did the defendant leave anything behind?", "\"A jacket, I believe, on the back of the chair. I did not look carefully. I turned it over to the manager.\""), .cross("Did you tell anyone before 9:30 that the table was gone?", "\"No. I should have told the manager sooner. I wanted to give them the benefit of the doubt.\""), .cross("Did you speak with the companion?", "\"Only about the order and the drinks. The companion was quiet and did not say anything about money.\"")],
        defenseRole: "Dining companion",
        defenseExam: [.direct("What was your relationship to {D}?", "\"We are friends from work. I joined {D} for dinner on {DATE} to celebrate {D.his} promotion.\""), .direct("How was the dinner?", "\"Lovely. The food was good, the service was friendly, and {D.he} was in a great mood the entire time.\""), .direct("What happened when the check came?", "\"{D.He} patted pockets and looked worried, then said the wallet must be in the car. We both stood up to go find it.\""), .direct("Where did you go?", "\"Out to the lot. We checked {D.his} car and then mine. There was no wallet. {D.He} got quiet and said we should find an ATM.\""), .direct("Did you go to an ATM?", "\"Yes, one near the lot. {D.He} tried to take out cash and the machine declined the card.\""), .direct("What did the defendant say after that?", "\"{D.He} said we were in trouble and that {D.he} was too embarrassed to walk back in without the money. I did not push.\""), .cross("Did you have money to cover the check?", "\"I did not offer, and I'm not proud of that. I wasn't carrying that much, and I did not think to call anyone.\""), .cross("Did either of you go back into the restaurant?", "\"No. We both walked out and neither of us went back in that night.\""), .cross("Did the defendant mention a card reader being broken?", "\"No. I did not hear anything about a reader. {D.He} said {D.he} had no wallet.\""), .cross("How long were you outside?", "\"Maybe fifteen minutes. We went to the ATM and stood in the lot. Then we left.\""), .cross("Whose idea was it to leave?", "\"It was mutual. I do not think either of us had a plan. We just did not know what to do.\"")],
        theory: ("{D} dined and left without paying.", "{D} went for cash and the ATM declined."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had no card or cash with {D.him}.", "The ATM withdrawal was declined and {DL} was embarrassed."),
