        state: [E(.physical, 3, "Battery", "A battery with a date code three years old and a rebuilt label under a sticker."), E(.document, 3, "Receipt", "A receipt for 'new battery' at $480."), E(.document, 2, "Shop Report", "The shop says the battery is rebuilt and degraded."), E(.statement, 2, "{V}", "The battery failed three weeks later.")],
        defense: [E(.statement, 1, "Supplier Mistake", "{DL} says the supplier delivered an older battery by mistake."), E(.document, 1, "Supplier Invoice", "An invoice for ten batteries two months earlier.")],
        role: "Truck owner",
        exam: [.direct("What did you pay {D} for?", "\"$480 for a 'brand new' truck battery and installation in my driveway. The receipt says 'new battery.'\""), .direct("What happened three weeks later?", "\"The battery failed. A shop found a date code three years old and a rebuilt label under a sticker.\""), .direct("What did the shop report say?", "\"That the battery was rebuilt and degraded. That is not what I paid for.\""), .direct("What did you buy from the defendant?", "\"A battery for my pickup, advertised as brand new at $480 with installation. {D} came to my driveway the same afternoon.\""), .direct("How did the battery perform?", "\"It worked for about three weeks, then the truck would not start one cold morning. I towed it to a shop for a check.\""), .direct("What did the shop find?", "\"A date code three years old and a label saying rebuilt hidden under a fresh sticker. The shop said the battery was degraded and not worth fixing.\""), .cross("{D} says the supplier delivered an older battery by mistake, doesn't {D.he}?", "\"Yes. The supplier's invoice shows a mixed delivery.\""), .cross("Did the defendant offer to replace it?", "\"I do not recall an offer. I had to call several times.\""), .cross("Did the battery work at first?", "\"For three weeks, yes.\""), .cross("{D} installed it correctly, didn't {D.he}?", "\"Yes, the install itself was clean. The problem was what went in.\""), .cross("You did not look at the battery's date when the defendant installed it, did you?", "\"No. I took the receipt that said new battery at face value.\"")],
        defenseRole: "Mechanic who checked it",
        defenseExam: [.direct("What did the date code on the battery show?", "\"Three years old. That is a long time for a battery sold as new.\""), .direct("Was the battery rebuilt?", "\"The label said so. It was under a sticker, and I peeled the sticker back to see.\""), .direct("Is that common for batteries sold as new?", "\"No. Not when it is sold as new. A rebuilt battery should be labeled and priced differently.\""), .direct("What is your work?", "\"I am a mechanic who checked the battery in the shop. I have worked on trucks for twenty years.\""), .direct("What did you see on the battery?", "\"A date code from three years ago and a sticker over the original label. When I peeled it back, the label said rebuilt.\""), .direct("What state was the battery in?", "\"Degraded, holding only a partial charge. It was reaching the end of its life.\""), .cross("Could the supplier have shipped the wrong battery?", "\"It is possible. I have seen supplier mix-ups before.\""), .cross("Did {D} know the battery was rebuilt?", "\"I cannot say. I only inspected the battery.\""), .cross("Who put the sticker over the rebuilt label?", "\"I do not know. The sticker was added by someone.\""), .cross("A rebuilt battery is sold as rebuilt, not new, isn't it?", "\"Yes. A rebuilt label means it was refurbished, which is cheaper.\""), .cross("The sticker was applied on purpose, wasn't it?", "\"It looked deliberate. I cannot say who did it.\"")],
        theory: ("{D} sold a rebuilt battery as new.", "A supplier delivered an older battery."),
        allocution: "\"It was wrong from the start, and I knew it.\"",
        truths: ("{DL} covered the rebuilt label with a new sticker.", "The supplier's invoice shows a mixed delivery."),
        defendant: [.direct("Did you sell {V} a new battery?", "\"I sold what I believed was a new battery. The supplier delivered an older one by mistake, and I installed it.\""), .direct("Why was the rebuilt label covered by a sticker?", "\"I did not put it there. It came that way from the supplier, I think, and I never peeled the sticker.\""), .direct("Did you check the date code before you installed it?", "\"No. I did not look at it. I trusted the supplier, and I wanted to get the job done quickly.\""), .direct("How do you run your installation business?", "\"I buy batteries from a supplier and install them at customers' homes. I carry a few in my truck and order more as needed.\""), .direct("What did the supplier deliver?", "\"A box of ten batteries two months earlier. I later learned some of them were older, mixed in with new ones.\""), .direct("What did you do when {V} complained?", "\"I said I would look at it, and I told {V} the supplier had mixed up the stock. I offered to swap it.\""), .cross("The receipt says 'new battery,' doesn't it?", "\"Yes. I wrote that on the receipt. I believed it was true when I wrote it for the customer.\""), .cross("A sticker covered a rebuilt label. How did you not notice?", "\"I did not look under the sticker. I installed the battery quickly in the driveway and moved on.\""), .cross("Will you refund the $480 that {V} paid you?", "\"If the battery was wrong, yes. I will make it right, and I want to return the full amount.\""), .cross("You covered a label with a new sticker, didn't you?", "\"Yes, the label was damaged and I put a sticker over it to tidy the look. I did not think it hid anything.\""), .cross("The receipt said new battery, didn't it?", "\"Yes. I wrote it based on what I believed the supplier sent.\"")],
        openings: ("{V} paid {D} $480 for a 'brand new' truck battery and installation in a driveway. Three weeks later the battery failed, and a shop found a three-year-old date code and a rebuilt label hidden under a sticker.", "The defense evidence will establish that the supplier delivered an older battery by mistake, that the invoice shows a mixed delivery, and that {D} never looked under the sticker."),
        closings: ("A receipt that says new, a date code three years old, and a rebuilt label covered by a sticker. {D} sold a degraded battery as a new one and took $480.", "A supplier's mixed delivery and an installer who trusted it without checking. The State must prove {D} knew the battery was rebuilt, and carelessness is not fraud."),
        timeline: [(0, "{D} installs the battery."), (21, "The battery fails."), (22, "The shop finds the rebuilt label."), (30, "{V} reports the sale.")],
        identified: "The invoice and the driveway sale tie to {D}.",
        notDone: ["The battery's source was never traced.", "The shop's teardown report was never entered."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let mowCrewNoShowV1 = SmallCases.make(
        key: "story.mowCrewNoShow",
