        headlines: ["Snow Removal Contractor Takes $600 for Winter and Never Plows", "Driveway Buried After Three Storms and Unanswered Calls"],
        law: "falsePretenses",
        spec: "Obtained $600 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} took $600 from {V} on {DATE} for a full winter of snow plowing and promised same-day service after each storm. Three storms came and {D} never plowed {V}'s driveway or answered messages. Two other customers paid the same fee and say they were not plowed either. {D} says the plow truck broke down.",
        state: [E(.document, 3, "Contract", "A winter plowing contract for $600 signed by {D} on {DATE}."), E(.digital, 3, "Messages", "Seven unanswered messages over the winter."), E(.statement, 2, "Other Customers", "Two customers paid and were not plowed."), E(.video, 2, "Driveway Camera", "Snow piled up and no plow came after three storms.")],
        defense: [E(.statement, 1, "Truck Broke Down", "{DL} says the plow truck broke down in December."), E(.document, 1, "Repair Receipt", "A repair for a transmission dated December 14.")],
        role: "Homeowner",
        exam: [.direct("What did you pay {D} for?", "\"$600 for a full winter of snow plowing, with same-day service promised after each storm. We signed a contract that day.\""), .direct("What happened during the winter?", "\"Three storms came, and {D} never plowed my driveway or answered my messages. I sent seven messages.\""), .direct("What did you learn from other customers?", "\"Two other customers paid the same fee and were not plowed either. My driveway camera shows snow piling up and no plow.\""), .direct("What happened when the storms came?", "\"Three storms dropped a foot each, and no plow came. I shoveled my own driveway each time and sent messages to {D.him}.\""), .direct("How many messages did you send?", "\"Seven over the winter. None got a reply, not even a text back.\""), .direct("What did you do after the second storm passed without a plow?", "\"I called and texted, then shoveled the drive myself. By the third storm I was calling other contractors and asking neighbors who they used.\""), .cross("{D} says the plow truck broke down, doesn't {D.he}?", "\"Yes. I have heard the truck did break down.\""), .cross("Did {D} tell you about the breakdown?", "\"No. {D.He} never told me anything. I heard it later.\""), .cross("Did you pay in advance?", "\"Yes. The full $600 up front.\""), .cross("Your driveway camera shows only the snow, doesn't it?", "\"Yes, with no truck. It shows the storms and the days after.\""), .cross("You do not know about the truck's trouble, do you?", "\"I learned about it later, after I complained. {D.He} did not tell me when it broke.\"")],
        defenseRole: "Other customer",
        defenseExam: [.direct("Did {D} plow your driveway that winter?", "\"Once. Only one time all winter, and it was early on, before the second storm of the season.\""), .direct("Did you pay the defendant in advance for the season?", "\"Yes. I paid in full up front, because that was the arrangement in the contract {D} gave me.\""), .direct("Did the defendant answer your calls and messages?", "\"Sometimes at first. After the first few storms, {D.he} stopped answering, and I never heard back.\""), .direct("How do you know the defendant?", "\"I am another customer who paid for plowing. I live a few streets from {V}.\""), .direct("What happened to your driveway?", "\"The same thing as {V}'s. No plow came after any of the storms.\""), .direct("Did you hear from the defendant?", "\"Once, in January, after I had left messages. {D.He} said the truck was in the shop and was sorry.\""), .cross("Was it supposed to be a full winter of plowing?", "\"It was meant to be. That is what the contract said, and the price was for the whole winter.\""), .cross("Did {D} ever tell you about the truck breaking down?", "\"No. {D.He} did not say anything to me about a breakdown, and I only heard about it later from others.\""), .cross("Did you ask the defendant for a refund of your money?", "\"I did, more than once. I never got a refund, and I am still out the money I paid.\""), .cross("You also paid up front, didn't you?", "\"Yes, the full amount. I never got any service.\""), .cross("{D} did tell you the truck was down, didn't {D.he}?", "\"Weeks after the first storm, and only when I called.\"")],
        theory: ("{D} took payment and never plowed.", "{D}'s plow truck broke down."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} had signed twelve contracts with one truck.", "The truck did break down, but {DL} did not tell anyone."),
        defendant: [.direct("Did you plan to plow for the winter?", "\"Yes. I took the money meaning to plow. I had a truck and a plan.\""), .direct("What happened to the plow truck?", "\"It broke down. I could not afford to fix it quickly, and I fell behind.\""), .direct("How many customers did you sign for the winter?", "\"Twelve contracts at about $600 each. I thought one truck with a plow could cover them if I worked long nights.\""), .direct("What happened with the truck?", "\"The transmission failed on December 14. The repair took weeks, and I fell far behind.\""), .direct("Why did you not answer the messages?", "\"I was ashamed and overwhelmed. I kept telling myself I would get a loaner plow and catch up.\""), .direct("What did you do after the truck broke down?", "\"I tried to get it fixed, but parts took weeks. I meant to hire a substitute, and I did not tell the customers. That was my mistake.\""), .cross("You signed twelve contracts with one truck, didn't you?", "\"Yes. It was too many. I took on more than I could do.\""), .cross("You did not tell customers about the breakdown, did you?", "\"No. That is on me. I hoped to fix it.\""), .cross("You never refunded anyone, did you?", "\"No. I did not have the money. I want to make it right.\""), .cross("You never told {V} the truck broke down, did you?", "\"No, I did not, and I know I should have.\""), .cross("You took $600 from twelve people with one truck, didn't you?", "\"Yes. I took on more than I could do, and it was a mistake.\"")],
        openings: ("{D} took $600 from {V} for a full winter of snow plowing and promised same-day service after each storm. Three storms came, {D} never plowed {V}'s driveway, and {D} ignored seven messages, as did two other customers who paid.", "By the end of this trial, the proof will show that the plow truck really did break down, that {D} meant to plow, and that {D} was overwhelmed and ashamed, not scheming."),
        closings: ("$600 paid up front, three storms, a driveway never plowed, and seven unanswered messages. {D} had signed twelve contracts with one truck.", "A plow truck that broke down and a contractor who fell behind and was ashamed. The State must prove {D} never meant to plow."),
        timeline: [(0, "{V} pays $600."), (40, "The first storm."), (60, "The second storm."), (90, "The third storm and no plow.")],
        identified: "The receipt names {D}.",
        notDone: ["The plow's repair records were never checked.", "The two other customers were never asked about their refunds."],
