    static let formulaShopliftV1 = SmallCases.make(
        key: "story.formulaShoplift",
        category: .property,
        headlines: ["Shopper Hides Diapers and Wipes in Stroller Pocket at Drugstore", "Drugstore Mirror Camera Shows Items Slid Into Stroller"],
        law: "larcenyMerchant",
