        state: [E(.video, 3, "Mirror Camera", "{D} slides three packs of diapers and four packs of wipes into the stroller pocket."), E(.physical, 2, "Recovered Items", "The diapers and wipes recovered from the stroller pocket."), E(.document, 2, "Price Check", "The items total $190."), E(.statement, 2, "Pharmacist", "Saw {D} leave without stopping at the register.")],
        defense: [E(.statement, 1, "Crying Child", "{DL} says {D.he} was holding a crying child and forgot the items."), E(.document, 1, "Receipt", "A $3 receipt for a pack of gum at 12:42 p.m.")],
        role: "Pharmacist",
        exam: [.direct("What do you do at the pharmacy?", "\"I'm the pharmacist on duty. On {DATE} I was behind the counter when {D} came in at about 12:30 p.m. pushing a stroller.\""), .direct("What did you notice about {D}?", "\"I noticed the stroller first, a double-wide one with a deep pocket in the back. {D.He} spent time in the baby aisle and the aisle with wipes.\""), .direct("What does the mirror camera show?", "\"At about 12:35 {DL} slides three packs of diapers and four packs of wipes into the stroller's pocket, glances at the aisle, and moves on.\""), .direct("What did the defendant buy?", "\"A pack of gum, at 12:42 at the register. Then {D.he} walked out at 12:45 without paying for the diapers or wipes.\""), .direct("What did you do?", "\"I saw {DL} head for the door and called after {DL}. {DL} kept walking and left. I called the Sheriff's Office at 12:50.\""), .direct("What were the items worth?", "\"The three packs of diapers and four packs of wipes total $190. Deputies recovered them from the stroller pocket.\""), .cross("Was there a child in the stroller?", "\"Yes, a small child who was crying at times. I could hear it from the pharmacy counter.\""), .cross("Did the defendant try to hide the items?", "\"The pocket is behind the seat, so they were out of sight. The camera shows {DL} sliding them there, which is why I believe it was deliberate.\""), .cross("Was the register footage checked for a missed scan?", "\"No. I'm not sure anyone looked at it. The cashier rang up the gum and nothing else.\""), .cross("Did the defendant say anything when you called out?", "\"I don't think so. I only saw {DL} keep going. I can't say whether {DL} heard me over the crying.\""), .cross("Did the items come back to the store?", "\"Yes, the deputies returned them, and they were all sealed and undamaged.\"")],
        defenseRole: "Shopper in the next aisle",
        defenseExam: [.direct("Where were you in the pharmacy?", "\"In the next aisle over, shopping for allergy medicine. I could see {D} through the gap between shelves.\""), .direct("What did you notice about {D}?", "\"A stroller with a screaming child. {D.He} looked frazzled and was bouncing the stroller with one hand while looking at the shelves.\""), .direct("What did you hear?", "\"The child was crying loudly the entire time. At one point a pack of wipes fell off the shelf and {D.he} muttered something and scooped it up.\""), .direct("Did you see the defendant put things in the stroller?", "\"I saw {DF} put a few things in the pocket behind the seat. I thought it was normal, like putting items in a cart.\""), .direct("Did the defendant go to the register?", "\"Yes, I saw {D.him} at the register paying for something small. The child was wailing, and {D.he} was trying to soothe it.\""), .direct("How did the defendant act at the register?", "\"Rushed and distracted. {DF} seemed focused on the child and not on the cashier.\""), .cross("Did you see the defendant leave the store?", "\"I saw {DF} head for the door with the stroller. I was not watching after that.\""), .cross("Did you know {D} was putting items in the pocket instead of the basket?", "\"It looked like an ordinary storage habit for a parent with a stroller, and I went back to my allergy shelf.\""), .cross("Could the defendant have forgotten the items?", "\"It's possible with a screaming baby. I can't say whether it was forgotten or not.\""), .cross("Did you hear the pharmacist call out?", "\"I heard someone call, but the child was so loud I couldn't make out the words.\""), .cross("Do you know the defendant?", "\"No. I've never seen {DF} before that day. I was just another customer.\"")],
        theory: ("{D} concealed diapers and wipes.", "{D} forgot the items while caring for a child."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} had hidden the items before picking up the gum.", "{DL} was distracted by a crying child and forgot."),
        defendant: [.direct("Why did you go to the pharmacy?", "\"I needed diapers and wipes for my child, and gum for a headache. I had my child in the stroller and was in a hurry.\""), .direct("What happened to the diapers and wipes?", "\"I put them in the pocket of the stroller because my hands were full. My child was fussing, and I was planning to take them out at the register.\""), .direct("What happened at the register?", "\"I paid for the gum. My child started to scream, and I got flustered. I just wanted to get outside.\""), .direct("Why did you leave without paying for the other items?", "\"I forgot. It sounds ridiculous. I was holding my child, my bag, and my keys, and the diapers were out of my mind.\""), .direct("How did you feel when the deputy came?", "\"Mortified. I told the deputy I would pay right away. I handed everything back.\""), .direct("How was money for you at that time?", "\"Tight. I'd rather not say more, but I did have a few dollars for the gum, and I'm not going to claim I had the full amount that day.\""), .cross("You put the items in the stroller pocket on purpose, didn't you?", "\"I put them there because I had no free hands. I did not put them there to hide them.\""), .cross("You paid for gum and nothing else, didn't you?", "\"Yes, I paid for the gum. I should have put the diapers on the counter too.\""), .cross("The pharmacist called out to you, didn't the pharmacist?", "\"I didn't hear it over my child. If I had, I would have stopped.\""), .cross("Seven packs of baby supplies is a lot to forget, isn't it?", "\"It is, and I understand why it sounds like an excuse. That's what I'm telling you, though.\""), .cross("You did not return to the register after leaving, did you?", "\"No. I realized outside, and the deputy was already there.\"")],
        openings: ("{D} pushed a stroller into a pharmacy, slid three packs of diapers and four packs of wipes into the stroller pocket, paid for a pack of gum, and left. The mirror camera recorded the concealment, and the items totaled $190. The pharmacist called deputies at 12:50.", "{D} was shopping with a screaming child, a full set of hands, and a pocket on the stroller. The gum was paid for, and the diapers were forgotten in the commotion. You will hear from a shopper in the next aisle who heard the child the whole time."),
        closings: ("Seven packs of supplies went into a hidden pocket, a pack of gum went on the counter, and the stroller went out the door. The camera shows each step. The items total $190.", "A parent with a wailing child, a paid-for pack of gum, and a pocket full of unpaid items. The register footage was never checked, and the child's behavior was never reviewed. The State must prove {D} meant to steal, not just that {D} forgot."),
        timeline: [(0, "12:30 p.m.: {D} enters."), (0, "12:35 p.m.: {D} slides the items into the pocket."), (0, "12:45 p.m.: {D} leaves."), (0, "12:50 p.m.: the pharmacist calls deputies.")],
        identified: "The mirror camera identifies {D}.",
        notDone: ["The child's behavior was never reviewed on the camera.", "The register footage was never checked for a missed scan."],
        mood: .sympathetic,
        doctrines: ["burdenOfProof"])

