        role: "Drugstore manager",
        exam: [.direct("What did you notice first at your cosmetics aisle?", "\"Empty peg hooks. I checked the camera and saw {D} slide six makeup palettes into an open purse.\""), .direct("What does the aisle camera show about the palettes?", "\"It shows {DL} sliding six palettes into a purse between 6:17 and 6:25 p.m., after standing at the aisle for ten minutes.\""), .direct("What happened at 6:30 that evening?", "\"{D.He} left through the main door without stopping at the register. The six palettes cost $290 together.\""), .direct("How did you notice the missing palettes?", "\"I was walking the cosmetics aisle at about 6:25 and saw empty pegs where six palettes had hung. The display looked gutted.\""), .direct("What did the camera show?", "\"{D.He} stands at the aisle for ten minutes, removes palettes one by one, and slides each into an open purse. {D.He} looks around once before leaving.\""), .direct("What happened at the register?", "\"{D.He} paid for a $9 water at 6:28 and left through the main door. The palettes were never rung up.\""), .cross("{D} says {D.he} meant to pay for them with the purse items, doesn't {D.he}?", "\"Yes. {D.He} says {D.he} paid for some water and forgot about the palettes in the purse.\""), .cross("Did the defendant walk past the register on the way out?", "\"{D.He} walked right past it. I watched on camera as {D.he} headed for the main door.\""), .cross("Did the defendant try to hide the palettes inside the purse?", "\"The purse was open, not zipped. I cannot say whether that was hiding or just carelessness.\""), .cross("{D} paid for something at the register, didn't {D.he}?", "\"Yes, a bottle of water. {D.He} was polite and calm.\""), .cross("You did not stop the defendant at the door, did you?", "\"No. I saw it on the camera after {D.he} had left.\"")],
        defenseRole: "Friend shopping together",
        defenseExam: [.direct("Did {D} mean to pay for the palettes?", "\"I thought so. {D} said in the aisle that we would pay for everything at the register on the way out.\""), .direct("Did you see the palettes go into the purse?", "\"Yes. I saw {DF} slide them in one at a time. I did not think anything of it at that moment.\""), .direct("Did the defendant pass the register on the way out of the store?", "\"Right past it. {D.He} walked out the main door, and I followed without realizing what was happening.\""), .direct("How do you know the defendant?", "\"We are close friends and were shopping together that evening. I was in the next aisle for a few minutes.\""), .direct("What did you see the defendant do?", "\"{D.He} looked at palettes and slid some in the purse while we were chatting. I thought nothing of it.\""), .direct("How did the defendant act at the register?", "\"Normally. {DF} paid for the water, joked with the cashier, and walked out.\""), .cross("Did {D} buy anything at all during that visit?", "\"A bottle of water. I think {D.he} paid for it at the register before heading for the door.\""), .cross("Did you say anything to the defendant about the palettes?", "\"No. I assumed {DF} would pay for them. I was talking about something else as we walked out.\""), .cross("Are you friends with the defendant?", "\"Yes, we are friends. I am telling you what I saw, and I know my friendship matters to you.\""), .cross("You did not remind the defendant about the palettes, did you?", "\"No. I assumed {DF} had paid or put them back.\""), .cross("You saw the defendant put six palettes in a purse, didn't you?", "\"I saw a few go in. I did not count.\"")],
        theory: ("{D} filled a purse with palettes and paid for water.", "{D} forgot the palettes."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had resold palettes online before.", "{DL} paid for water and forgot the palettes."),
        defendant: [.direct("Did you put palettes into your purse?", "\"Yes. I put six in my purse while I was looking. I meant to pay for them at the register.\""), .direct("Why did you walk out without paying for them?", "\"I paid for a bottle of water and forgot about the palettes. I was distracted by a conversation with my friend.\""), .direct("Have you resold palettes online before?", "\"I have sold some of my own online before. That was a separate matter and had nothing to do with this.\""), .direct("What were you doing in the aisle?", "\"Looking at makeup for a few minutes while my friend shopped. I picked up some palettes to compare colors.\""), .direct("Why were the palettes in your purse?", "\"I put them in to keep my hands free, and then I got a call and forgot they were there. I meant to take them out at the register.\""), .direct("What did you pay for?", "\"A bottle of water. I had my phone in one hand and my purse in the other, and I walked out.\""), .cross("You stood at that aisle for ten minutes, didn't you?", "\"I was looking at different colors. I did not realize it was so long, and I was not watching the clock.\""), .cross("You slid six palettes into an open purse. Isn't that hiding them?", "\"It was open. I was not hiding anything from anyone. I did not think about how it looked.\""), .cross("You walked right past the register, didn't you?", "\"Yes, I did. I forgot. I am sorry, and I should have gone back as soon as I realized.\""), .cross("You have sold palettes online before, haven't you?", "\"Yes, ones I bought myself. I never sold any I had not paid for.\""), .cross("Six palettes is a lot to forget, isn't it?", "\"It is, and I know it sounds odd. It was a distracted evening.\"")],
        openings: ("At 6:15 p.m., {D} stood at a drugstore cosmetics aisle for ten minutes and slid six makeup palettes worth $290 into an open purse, then left through the main door without paying.", "The defense witnesses will explain that {D} paid for water at the register, forgot the palettes in the purse, and did not try to hide them."),
        closings: ("Ten minutes at the aisle, six palettes into a purse, and out the door without stopping at the register. The camera shows every step, and the palettes were never paid for.", "A distracted shopper who paid for a bottle of water and forgot the palettes in an open purse. The State must prove {D} meant to leave without paying."),
        timeline: [(0, "6:15 p.m.: {D} reaches the aisle."), (0, "6:25 p.m.: the last palette goes in the purse."), (0, "6:30 p.m.: {D} leaves."), (0, "6:40 p.m.: the manager reviews the camera.")],
