    static let pizzaOrderScamV1 = SmallCases.make(
        key: "story.pizzaOrderScam",
        category: .whiteCollar,
        headlines: ["Caller Orders $310 of Tacos for a 'Company Party' With Stolen Card, Courier Collects", "Restaurant Chargeback Traces Order to Courier's Phone"],
        law: "falsePretenses",
        spec: "Obtained food valued at $310 from {V}, a taco restaurant, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At 4:30 p.m. on {DATE}, a caller placed a $310 catering order for a company party and paid by card over the phone. At 6 p.m., {D} picked up the order at the counter. The card owner disputed the charge the next day. The restaurant's caller ID matches a phone registered to {D}. {D} says a friend asked {D.him} to pick up the food.",
        state: [E(.video, 3, "Counter Camera", "{D} picks up the order at 6:05 p.m. and drives away."), E(.document, 3, "Chargeback Notice", "The card owner disputes the $310 charge as unauthorized."), E(.digital, 2, "Caller ID Record", "The order call came from a phone registered to {D}."), E(.statement, 2, "Restaurant Owner", "Took the order by phone and handed it over at the counter.")],
        defense: [E(.statement, 1, "Friend's Errand", "{DL} says a friend asked {D.him} to pick up the food."), E(.document, 1, "Friend's Text", "A text asking {DL} to 'grab the tacos from the order.'")],
        role: "Restaurant owner",
        exam: [.direct("What order did you take over the phone?", "\"A $310 catering order for a company party, paid by card over the phone at about 4:30 p.m.\""), .direct("Who picked it up?", "\"{D}, at 6:05 p.m. at the counter. {D.He} drove away with it.\""), .direct("What happened with the card?", "\"The card owner disputed the charge as unauthorized the next day. The caller ID matches a phone registered to {DL}.\""), .direct("How did the order come in?", "\"A caller placed a $310 catering order at 4:30 for a company party of thirty and paid by card over the phone. The caller said a person would pick it up at six.\""), .direct("What happened at the counter?", "\"{D.He} came to the counter at about 6:05, gave the order name, and left with seven trays of tacos. I handed the order over myself.\""), .direct("What happened afterward?", "\"The next day the bank notified us that the card owner disputed the $310 charge as unauthorized. We lost the money and the food.\""), .cross("{D} says a friend asked {D.him} to pick up the food, doesn't {D.he}?", "\"Yes. That is what {D.he} says.\""), .cross("Did the defendant place the call?", "\"I cannot say. I do not know the voice.\""), .cross("Did the defendant pay at the counter?", "\"No. It had been paid by card.\""), .cross("{D} had a text asking for tacos, didn't {D.he}?", "\"I have seen it. It does not prove who made the call.\""), .cross("The caller ID matches the defendant's phone, doesn't it?", "\"Yes, a phone registered in {D.his} name placed the call.\"")],
        defenseRole: "Courier dispatcher",
        defenseExam: [.direct("Does your app dispatch couriers to pick up restaurant orders?", "\"Constantly. We send couriers to pick up orders from restaurants all day, and most of them are routine.\""), .direct("Do couriers see how an order was paid for?", "\"No. They only see the pickup name and address. They never see the card or how the order was paid.\""), .direct("Who dispatched {D} for this particular pickup?", "\"A client account. {D} accepted the request through the app, as couriers do many times a day.\""), .direct("What is your job?", "\"I dispatch couriers for deliveries and pickups. I log each request and who takes it.\""), .direct("What did your records show?", "\"A pickup request came through the app, routed to {D.his} account at about 5:30. {D.He} accepted it.\""), .direct("What did the request look like?", "\"A simple order pickup at the restaurant with the order name and phone number. There was nothing unusual.\""), .cross("Did you call the client to check on the order?", "\"No. We do not call clients. We assume the order is real, and we send a courier to pick it up.\""), .cross("Was the defendant told whose card paid for the food?", "\"No. The app does not show that. {D.He} had no way to know whose card was used.\""), .cross("Does the app show a phone number for the client?", "\"Yes. It showed a number, but I do not recall whose it was, and I did not check it.\""), .cross("You do not know who placed the order, do you?", "\"No. I only know about the pickup request.\""), .cross("The same phone number appears on both, doesn't it?", "\"Yes. It is the one tied to {D.his} account.\"")],
        theory: ("{D} placed a fraudulent order and picked it up.", "{D} picked up food for a friend."),
        allocution: "\"I knew better. I want to make it right.\"",
        truths: ("{DL} placed the call from {D.his} own phone.", "The friend's text was real and the friend used {DL}'s phone."),
        defendant: [.direct("Did you place the catering order?", "\"No. A friend asked me to pick up the food. I did not call the order in, and I did not pay.\""), .direct("Whose phone is the caller ID on the order?", "\"Mine. The friend borrowed my phone to place the call. I did not know what it was being used for.\""), .direct("Did you know the card used was stolen?", "\"No, I had no idea. I thought I was doing a favor for a friend, and I never saw a card.\""), .direct("How did you come to pick up the order?", "\"A friend texted me asking me to grab the tacos from an order at the restaurant. I said sure and went after work.\""), .direct("Whose phone made the call?", "\"Mine. The friend borrowed my phone earlier that afternoon to make a call, and I did not hear what it was for.\""), .direct("What did you do with the food?", "\"I drove it to the friend at a park, as asked. I did not eat any, and I got nothing in return.\""), .cross("The order call came from your own phone, didn't it?", "\"Yes. The friend borrowed it, and I did not think about it. I know how that looks to you.\""), .cross("You picked up $310 of food and drove away, didn't you?", "\"Yes. I took the food to my friend, and I did not keep any of it for myself.\""), .cross("Can you give the jury the name of that friend?", "\"Yes, I can give a name, but I cannot reach that person now.\""), .cross("The call came from your phone, didn't it?", "\"Yes, but I was not the one on it. The friend used it.\""), .cross("You paid nothing for the food, did you?", "\"No. The friend said it was handled.\"")],
        openings: ("A caller placed a $310 catering order by card over the phone, and {D} picked it up at 6:05 p.m. The card owner disputed the charge as unauthorized, and the caller ID matches a phone registered to {D}.", "Listen for the defense evidence, which will show that a friend asked {D} to pick up the food, that the friend used {D}'s phone to call, and that {D} did not know the card was stolen."),
        closings: ("A catering order paid with a card that was not the caller's, picked up by {D} at the counter, and a caller ID that matches {D}'s own phone. The food was gone before the dispute.", "A friend's favor and a borrowed phone, with a courier app that sent {D} to pick up an order. The State must prove {D} knew the card was stolen, and it cannot."),
        timeline: [(0, "4:30 p.m.: the order call."), (0, "6:05 p.m.: {D} picks up the order."), (1, "The card owner disputes the charge."), (3, "The restaurant reports the order.")],
        identified: "The counter camera identifies {D}.",
        notDone: ["The caller was never identified.", "The courier app's dispatch record was never pulled."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let utilityShutoffCallV1 = SmallCases.make(
        key: "story.utilityShutoffCall",
        category: .whiteCollar,
        headlines: ["Caller Posing as Grandchild's Lawyer Sends Courier for $1,200 Bail Cash", "Doorbell Camera Shows Courier Collecting Envelope"],
        law: "falsePretenses",
        spec: "Obtained $1,200 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} got a call on {DATE} from a person who said {V}'s grandchild had been arrested and needed $1,200 in cash for bail, and that a courier would pick it up. At 2:30 p.m., {D} came to {V}'s door, took an envelope with $1,200 and left in a car. The grandchild was home and had not been arrested. A doorbell camera recorded {D}. {D} says {D.he} was hired through an app to pick up a package.",
        state: [E(.video, 3, "Doorbell Camera", "{D} takes the envelope from {V} at 2:30 p.m. and drives away."), E(.digital, 3, "Call Records", "A call to {V}'s landline at 1:45 p.m. from a number tied to a prepaid phone."), E(.digital, 2, "Courier App Record", "A pickup request routed to {D}'s account at 2:10 p.m."), E(.statement, 2, "Grandchild", "Was home that afternoon and never arrested.")],
        defense: [E(.statement, 1, "Hired by App", "{DL} says {D.he} was hired through an app to pick up a package."), E(.document, 1, "App Payment", "A $40 payment to {D}'s account for the pickup.")],
        role: "Resident",
        exam: [.direct("What happened at 2:30?", "\"{D} came to my door, took an envelope with $1,200, and left in a car. My doorbell camera recorded it.\""), .direct("What was the truth?", "\"My grandchild was home and had never been arrested. I felt foolish and frightened.\""), .direct("What did the caller tell you?", "\"That my grandchild had been arrested after an accident and needed $1,200 in cash for bail. The caller said I should not tell anyone and that a courier would come.\""), .direct("What did you do?", "\"I went to the bank, took out $1,200 in cash, and put it in an envelope. I waited at the door for the courier.\""), .direct("How did the pickup go?", "\"A courier came at about 2:30, took the envelope, and drove off in a car. When I called my grandchild, I learned that nothing had happened.\""), .direct("What did you do after the courier drove away?", "\"I called my grandchild and heard a normal voice on the phone. Then I called the sheriff's office, and I have not stopped shaking since.\""), .cross("{D} says {D.he} was hired through an app to pick up a package, doesn't {D.he}?", "\"Yes. A pickup request was routed to {D.his} account at 2:10.\""), .cross("Did the defendant say anything to you?", "\"Very little. {D.He} said hello and took the envelope.\""), .cross("Did you call the number back?", "\"No. The call came from a prepaid phone.\""), .cross("The courier did not speak to you much, did {D.he}?", "\"Only a few words. {D.He} said a name and took the envelope.\""), .cross("You never saw anyone else with the defendant, did you?", "\"No. {D.He} was alone.\"")],
        defenseRole: "Courier company owner",
        defenseExam: [.direct("Does {D} pick up cash for your courier clients?", "\"For clients, yes. {D} picks up envelopes and packages for people who request pickups through our app.\""), .direct("Who was the client for this particular pickup?", "\"A phone number. The request came through our app with a number and an address, and nothing more.\""), .direct("Did the defendant know what was inside the envelope?", "\"Not that I know of. Couriers are not told what is inside any package or envelope they pick up.\""), .direct("What is your role?", "\"I own a small courier company that handles deliveries and gig pickups. {D.He} drives for us through the app.\""), .direct("How does the app assign work?", "\"A request comes in with an address and a time, and the nearest driver accepts it. The app records the request and payment.\""), .direct("What did the app record for this job?", "\"A pickup at {V}'s address at 2:10, accepted by {DF}, with a $40 payment. It showed no contents.\""), .cross("Did you check on the client before sending the defendant?", "\"No. I did not check this client. We do not verify every client who requests a pickup.\""), .cross("Has the defendant picked up envelopes from elderly residents before?", "\"I heard about four others. I do not know the details, and I did not look into them.\""), .cross("Do you pay your couriers a normal rate for these jobs?", "\"We pay per job at a normal rate. Nothing about the pay for this job stood out to me.\""), .cross("Your app does not check what is being picked up, does it?", "\"No. We do not inspect packages and drivers are told not to open them.\""), .cross("You do not know who made the request, do you?", "\"No. It came from an account created with a prepaid phone.\"")],
        theory: ("{D} collected cash for a bail scam.", "{D} was hired through an app."),
        allocution: "\"I'm sorry to everyone I let down. I'll repay what I can.\"",
        truths: ("{DL} had picked up envelopes from four other elderly residents.", "The app request was real and {DL} did not know the contents."),
        defendant: [.direct("Did you take the envelope from {V}?", "\"Yes. I was hired through an app to pick up a package. I did not know it was cash.\""), .direct("Did you know about the grandchild?", "\"No. I knew nothing. I just followed the address in the app.\""), .direct("Why did you drive away right after?", "\"The job said to bring it to a drop-off. I followed instructions.\""), .direct("How did you get this job?", "\"Through a courier app where I accept pickups. A request came through to my account at about 2:10 and said to pick up a package at an address.\""), .direct("What were you told about the package?", "\"Only that I was to pick up an envelope and meet another driver to hand it over. I was paid $40 through the app.\""), .direct("What did you think was in the envelope?", "\"Documents or a small item. I did not open it, and I did not think to ask.\""), .cross("You had picked up envelopes from four other elderly residents, hadn't you?", "\"I picked up packages. I did not know what they were.\""), .cross("You did not ask what was in the envelope, did you?", "\"No. I wish I had. I did not think to.\""), .cross("$1,200 in cash in an envelope. Didn't that feel odd?", "\"It was heavier than a package. I did not question it.\""), .cross("You picked up envelopes from other elderly residents too, didn't you?", "\"Yes, four others that month. I thought it was a normal business.\""), .cross("You never asked why a courier was collecting cash, did you?", "\"No. A courier who handles cash from older people should have wondered more.\"")],
        openings: ("A caller told {V} that a grandchild had been arrested and needed $1,200 for bail, and a courier would pick it up. At 2:30 p.m. {D} took the envelope from {V}'s door and drove away, and the grandchild was home.", "The defense case is that {D} was hired through a courier app to pick up a package and did not know what was inside."),
        closings: ("A false arrest story, a frightened resident, an envelope with $1,200, and {D} on a doorbell camera. {D} had picked up envelopes from four other elderly residents.", "A courier who followed an app's instructions and never knew what was in the envelope. The State must prove {D} knew it was a scam."),
        timeline: [(0, "1:45 p.m.: the call to {V}."), (0, "2:10 p.m.: the app routes the pickup to {D}."), (0, "2:30 p.m.: {D} takes the envelope."), (1, "{V}'s family reports the scam.")],
        identified: "The doorbell camera identifies {D}.",
        notDone: ["The caller was never identified.", "The courier's dispatch record was never pulled."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

