        defense: [E(.statement, 1, "Bought From Friend", "{DL} says {D.he} bought it from a friend and did not know."), E(.document, 1, "Text From Friend", "A text from a friend that says 'got a tablet for you.'")],
        role: "Buyer",
        exam: [.direct("What did you buy from {D}?", "\"A used tablet advertised as 'clean and unlocked.' I paid $280 in cash in a parking lot.\""), .direct("What happened when you turned it on?", "\"It showed a 'lost device' message from the previous owner. The tablet was locked.\""), .direct("What did the previous owner say?", "\"That the tablet was stolen two weeks before the sale. I have the report.\""), .direct("How did you find the tablet?", "\"On a marketplace listing that said clean and unlocked, for $280. I messaged the seller and arranged to meet in a parking lot.\""), .direct("How did you pay?", "\"In cash at the meeting. {D} handed me the tablet in a box and said it was good to go.\""), .direct("What did you discover at home?", "\"When I turned it on, it showed a lost device message from the first owner. I contacted the owner, who said it had been stolen two weeks earlier.\""), .cross("{D} says {D.he} bought it from a friend and did not know, doesn't {D.he}?", "\"Yes. A friend sold alongside {DL}.\""), .cross("Did {D} offer a refund?", "\"Not at first. I had to ask more than once.\""), .cross("Did the defendant say anything about checking it?", "\"The ad said 'clean and unlocked.' That is what I relied on.\""), .cross("You did not check the tablet before paying, did you?", "\"I looked at the screen and it was off. I did not turn it on, and I wish I had.\""), .cross("{D} told you it was clean, didn't {D.he}?", "\"Yes, in the ad and again in person. {D.He} said the tablet was unlocked and ready.\"")],
        defenseRole: "Friend who sold alongside",
        defenseExam: [.direct("Did {D} buy the tablet from someone else?", "\"Used, from someone. I was there when {D} bought it, and it looked like a normal deal between friends.\""), .direct("Did you ever see the lost-mode screen on the tablet?", "\"No. I never saw that. It was turned off when we sold it, and nobody turned it on.\""), .direct("Was the tablet advertised as clean and unlocked?", "\"Yes. {DF} wrote 'clean and unlocked' in the ad, because that is what our friend had told us.\""), .direct("How do you know the defendant?", "\"We have been friends for years and sometimes resell electronics together. I was with {D.him} when the tablet came up for sale.\""), .direct("What did you see?", "\"{DF} got the tablet from another friend, who said it was ready to sell. {DF} listed it that evening.\""), .direct("What did the defendant say about it?", "\"That it was clean. {D.He} did not seem to know anything about a lock.\""), .cross("Did the defendant check whether the tablet was locked before selling it?", "\"Not that I saw. {D.He} did not turn it on, and I did not turn it on either.\""), .cross("Did the defendant sell other devices that month besides this tablet?", "\"Two others, as I recall. I do not know anything about those two sales or what happened to them.\""), .cross("Did the friend say the tablet was fine when handing it over?", "\"Yes. The friend said it was fine and handed it over. We trusted that, and we did not check.\""), .cross("You did not check it either, did you?", "\"No. We both trusted the friend.\""), .cross("You sell a lot of devices, don't you?", "\"Some, yes. We buy and sell used electronics.\"")],
