    static let towTruckOverchargeV1 = SmallCases.make(
        key: "story.towTruckOvercharge",
        category: .whiteCollar,
        headlines: ["Garage Charges $160 Lost Ticket Fee Where Sign Says $20", "Posted Rate Sign and Receipt Do Not Match"],
        law: "falsePretenses",
        spec: "Obtained $160 from {V}, a motorist, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} lost a parking ticket at a downtown garage on {DATE}. The attendant, {D}, charged a $160 'lost ticket and overnight fee' and told {V} that was the posted rate. A sign at the booth lists a $20 lost ticket fee and no overnight fee. {D} says the sign was out of date.",
        state: [E(.document, 3, "Posted Sign", "A sign at the booth that lists a $20 lost ticket fee."), E(.document, 3, "Receipt", "A receipt for $160 for 'lost ticket and overnight fee.'"), E(.video, 2, "Booth Camera", "{D} points to the rate board and takes the cash."), E(.statement, 2, "{V}", "Was told $160 was the posted rate.")],
        defense: [E(.statement, 1, "Old Sign", "{DL} says the sign was out of date."), E(.document, 1, "Owner's Memo", "A memo to staff about a new $160 policy dated last month.")],
        role: "Motorist",
        exam: [.direct("What happened when you lost your parking ticket?", "\"The attendant, {D}, charged a $160 'lost ticket and overnight fee' and told me that was the posted rate.\""), .direct("What does the sign at the booth say?", "\"A $20 lost ticket fee and no overnight fee. The posted sign lists those rates.\""), .direct("What does the booth camera show?", "\"It shows {DL} pointing at the rate board and taking the cash.\""), .direct("What happened at the garage?", "\"I lost my ticket after a late dinner and went to the booth to leave. The attendant, {DL}, said it would be $160 for a lost ticket and overnight fee.\""), .direct("What did you see on the booth?", "\"A sign that said lost ticket fee $20, with no overnight fee listed. I pointed to it and {D.he} pointed to the rate board and said that was the rate.\""), .direct("What did you do?", "\"I paid $160 in cash because I needed to leave, and I took the receipt. The next day I wrote to the owner.\""), .cross("{D} says the sign was out of date, doesn't {D.he}?", "\"A memo did set a new rate that was never posted. That is fair.\""), .cross("Did you ask about the rate?", "\"Yes. I was told $160 was the posted rate. I paid because I needed my car.\""), .cross("Did you get a receipt?", "\"Yes. It says $160 for 'lost ticket and overnight fee.'\""), .cross("You paid without arguing, didn't you?", "\"I argued briefly, then paid. It was late and I wanted to go.\""), .cross("You do not know about a memo, do you?", "\"I learned about it later. It was not posted at the booth.\"")],
        defenseRole: "Garage manager",
        defenseExam: [.direct("What is the lost ticket fee at your garage?", "\"Twenty dollars. That is what the posted sign says, and that is what attendants are supposed to charge.\""), .direct("Did {D} charge more than the posted fee?", "\"I heard that {D} did. I did not witness it myself, but the receipt says $160 for the fee.\""), .direct("Does the booth show the rate on a sign for customers?", "\"Yes. The rate is on a sign visible from the booth window, listing the lost ticket fee and nothing else.\""), .direct("What is your role at the garage?", "\"I am the garage manager and write staff memos about fees. I issued the memo about the new lost ticket rate.\""), .direct("What did the memo say?", "\"That the lost ticket fee would be $160 starting the next month, including overnight. It was a company decision.\""), .direct("Was the sign updated?", "\"No. We ordered a new one, and it had not arrived.\""), .cross("Did the defendant get any training on the rates when starting?", "\"Once, when {D.he} started. It was a short talk about the rates and how to give receipts.\""), .cross("Was a new rate set by a memo that was never posted?", "\"A memo did set a new rate. It was never posted on the sign, and I know that is a problem for the garage.\""), .cross("Did the defendant keep the extra money in a drawer?", "\"I heard the extra was kept in a drawer at the booth. I do not know what happened to it after that.\""), .cross("The old sign was still posted when {V} came, wasn't it?", "\"Yes, and that was my failure.\""), .cross("The memo was not given to the public, was it?", "\"No. It went to staff only.\"")],
        theory: ("{D} charged more than the posted rate.", "The posted rate was out of date."),
        allocution: "\"I should have told the truth the first time.\"",
        truths: ("{DL} kept the extra $140 in a drawer.", "A memo did set a new rate that was never posted."),
        defendant: [.direct("Did you charge {V} $160 for the lost ticket?", "\"Yes. I charged $160 for a lost ticket and an overnight fee. I believed that was the rate we were using.\""), .direct("Why did you point at the rate board for {V}?", "\"I thought it showed the new rate from the memo. I did not read it closely before pointing.\""), .direct("Where did the extra cash go after the sale?", "\"I put it in the drawer at the booth. I planned to turn it in at the end of the shift.\""), .direct("What did your boss tell staff?", "\"A memo said the lost ticket fee was now $160, including overnight. I read it the week before and followed it.\""), .direct("Why was the sign still up?", "\"No one had replaced it. I assumed the owner would fix it.\""), .direct("What did you do with the money?", "\"I put it in the drawer and logged it on the sheet. I did not take any of it.\""), .cross("The posted sign says $20, doesn't it?", "\"It does. I did not look at the sign. I went by the memo I was given about a new rate.\""), .cross("You kept $140 extra in a drawer, didn't you?", "\"Yes. I should have given it back. I kept it in the drawer, and I did not use it for myself.\""), .cross("You told {V} that $160 was the posted rate. Was that true?", "\"I thought so at the time. I was wrong, and I regret telling {V.him} that.\""), .cross("The posted sign said $20, didn't it?", "\"Yes. I knew the sign had not been changed, and I should have said so.\""), .cross("The extra $140 sat in your drawer, didn't it?", "\"Yes, until the end of the shift when I turned it in.\"")],
        openings: ("{V} lost a parking ticket at a garage, and the attendant, {D}, charged $160 for a 'lost ticket and overnight fee,' calling it the posted rate. The sign at the booth lists a $20 lost ticket fee and no overnight fee.", "Jurors will hear that a memo set a new rate that was never posted and that {D} honestly believed $160 was correct."),
        closings: ("A sign that says $20, a receipt for $160, and an attendant who pointed at the board. {D} kept the extra $140.", "A memo with a new rate and an attendant who followed it. The State must prove {D} knew the charge was wrong."),
        timeline: [(0, "{V} loses the ticket."), (0, "{D} charges $160."), (1, "{V} reads the posted sign."), (3, "{V} reports the overcharge.")],
        identified: "The receipt and the sign identify {D}'s booth.",
        notDone: ["The garage's rate sheet history was never produced.", "Other customers' receipts that day were never reviewed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let stereoNoiseV1 = SmallCases.make(
        key: "story.stereoNoise",
        category: .publicOrder,
        headlines: ["DJ Speakers on Rooftop Terrace Rattle Apartments Until 1 a.m.", "Decibel Meter Reads 92 From Courtyard During Rooftop Party"],
        law: "disorderly",
        spec: "Disturbed the peace by making loud noise in a residential area at night, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} hosted a rooftop party on {DATE} with a DJ and two large speakers. Neighbors in the two nearest buildings called starting at 11:20 p.m. Deputies arrived at 12:10 a.m. and measured 92 decibels from the courtyard. {D} was warned at midnight to turn the speakers off and kept playing until 1 a.m. {D} says the music was at a normal party volume.",
        state: [E(.document, 3, "Decibel Readings", "92 decibels measured from the courtyard at 12:15 a.m."), E(.statement, 2, "Neighbors", "Four neighbors called between 11:20 and 12:10."), E(.video, 2, "Body Camera", "Deputies hear the bass from the street and warn {D} at midnight."), E(.document, 2, "Building Rules", "Quiet hours begin at 10 p.m.")],
        defense: [E(.statement, 1, "Normal Volume", "{DL} says the music was at a normal party volume."), E(.document, 1, "Speaker Specs", "Specs for the speakers listing a maximum of 98 decibels.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find when you responded to the rooftop party?", "\"Loud bass I could hear from the street. Four neighbors called between 11:20 and 12:10, and I measured 92 decibels from the courtyard at 12:15 a.m.\""), .direct("How long did the music continue?", "\"Until about 1 a.m. {D} turned the volume down a little but kept playing past the warning. Quiet hours in the building begin at 10 p.m.\""), .direct("How did you respond to the calls?", "\"Four neighbors called between 11:20 and 12:10 about loud bass from a rooftop party. I arrived at 12:10 and could hear it from the street before I reached the building.\""), .direct("What did your meter read?", "\"92 decibels from the courtyard at 12:15 a.m. That is well above a conversation level, and it was long past the building's ten o'clock quiet hours.\""), .direct("What did you tell {D}?", "\"At midnight I told {DL} to turn the speakers off because of the complaints. {DL} turned them down for a short while, but music kept playing until about one.\""), .direct("What did you notice when you stood in the courtyard below?", "\"I could feel the bass in my chest before I reached the door. People were leaning out of windows and a few had come out onto the street.\""), .cross("{D} says the music was at a normal party volume, doesn't {D.he}?", "\"That is what {D.he} says. But 92 decibels is well above what most people would call normal.\""), .cross("Did {D} lower the volume after the warning?", "\"A little, yes. The bass still carried across the courtyard to the neighboring buildings.\""), .cross("Did the defendant argue with you?", "\"No. {D.He} was polite. {D.He} simply did not shut it off.\""), .cross("The speakers can reach 98 decibels, can't they?", "\"The specs list a maximum of 98, so my reading of 92 was below their limit. It was still far above what the building allows after ten.\""), .cross("You measured from the courtyard, not from a neighbor's window, didn't you?", "\"Yes, from the courtyard near the building entrance. I cannot tell you what it measured inside any unit, only what the street and courtyard heard.\"")],
        defenseRole: "Party guest",
        defenseExam: [.direct("Was the music loud at the rooftop party?", "\"Very. The DJ had two big speakers, and you could feel the bass in your chest from across the roof.\""), .direct("Did anyone ask {D} to turn the volume down?", "\"Once that I saw. A guest asked, and {D} said it was fine. Later the deputies came and asked again.\""), .direct("Did the defendant comply with the request to turn it down?", "\"A little. The volume dropped some, but the bass carried, and the party kept going well past midnight.\""), .direct("How do you know the defendant?", "\"I am a friend of {DF} and was a guest at the party. I stayed on the roof for most of the night near the DJ table.\""), .direct("How loud was the music from where you stood?", "\"Loud enough to dance, but people were still chatting without shouting. Nobody was covering their ears or leaving because of the noise.\""), .direct("What did the defendant do when deputies came?", "\"{D.He} turned the volume down at once and thanked the deputies for coming. The bass still thumped, but the music itself was much lower.\""), .cross("Was the party still going after midnight?", "\"Yes. It went past midnight, until about one o'clock, even after the deputies had warned {D.him}.\""), .cross("Did you hear the warning from the deputies?", "\"I heard part of it. I heard them say to turn it off at midnight, and {DF} said okay.\""), .cross("Did the defendant tell the DJ to stop playing?", "\"Not right away. The DJ kept going until close to one o'clock.\""), .cross("You could hear the bass from the street, couldn't you?", "\"Probably so, since bass carries farther than the rest of the music. I did not walk down to check, so I cannot say how far.\""), .cross("The music played for another hour after midnight, didn't it?", "\"Yes, until about one o'clock. It was quieter after the deputies spoke to {D.him}, but it did not stop right then.\"")],
        theory: ("{D} kept loud music playing after a warning.", "The volume was normal for a party."),
        allocution: "\"I was angry and I made it everyone else's problem.\"",
        truths: ("{DL} was told twice to turn it down and refused.", "{DL} turned the speakers down but the bass carried."),
        defendant: [.direct("Did you host the rooftop party?", "\"Yes. I hosted a party with a DJ and two speakers for friends. It was a birthday celebration, and I did not mean to cause trouble.\""), .direct("Was the music at a normal party volume?", "\"I thought so. It was loud enough for a party, but I did not think it would carry that far.\""), .direct("Did you turn the speakers down after the deputies came?", "\"I turned them down some, but the bass still carried. I should have shut the whole thing off.\""), .direct("What was the party for?", "\"A birthday gathering for about thirty friends, with a DJ and two rented speakers on the roof. We started around eight in the evening.\""), .direct("What did you think about the volume?", "\"It seemed normal for a party. People were talking over the music without shouting, and I did not think it would reach the next building.\""), .direct("What did you do when deputies came?", "\"I turned the speakers down right away and kept the music low. I shut it off at one when the guests began leaving for the night.\""), .cross("Four neighbors called, and deputies measured 92 decibels. Do you dispute that?", "\"I do not dispute the number. It was louder than I realized.\""), .cross("Quiet hours begin at 10 p.m. in your building, don't they?", "\"Yes. I knew that. I thought a party on a rooftop would be okay, and I was mistaken.\""), .cross("You were told at midnight to turn it off, weren't you?", "\"Yes. I turned it down but let it go on for another hour, which I should not have done after a direct warning.\""), .cross("Quiet hours begin at ten, don't they?", "\"Yes, I knew that. I got caught up in the party and did not watch the clock until deputies were standing there.\""), .cross("You were told at midnight to turn it off and you kept playing until one, didn't you?", "\"I turned it down but not off. I thought the quieter level was fine. I understand why the neighbors did not agree.\"")],
        openings: ("{D} hosted a rooftop party with a DJ and two large speakers. Four neighbors called, deputies measured 92 decibels, and {D} was warned at midnight to turn the music off but kept playing until 1 a.m.", "The defense evidence will establish that {D} thought the music was at normal party volume, turned it down after the warning, and did not mean to disturb anyone."),
        closings: ("Four neighbors, 92 decibels, a warning at midnight, and music that played until 1 a.m. Quiet hours had begun at 10, and {D} knew it.", "A birthday party on a rooftop and a host who turned the volume down when asked. The State must prove {D} knowingly disturbed the peace."),
        timeline: [(0, "11:20 p.m.: the first call."), (0, "12:10 a.m.: deputies arrive."), (0, "12:15 a.m.: the meter reads 92."), (0, "1 a.m.: {D} stops the music.")],
        identified: "The rooftop terrace is {D}'s.",
        notDone: ["The decibel meter's calibration was never checked.", "The building's quiet-hours rule was never produced."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let leafBlowerDawnV1 = SmallCases.make(
        key: "story.leafBlowerDawn",
        category: .publicOrder,
        headlines: ["Garage Band Practice at 1:30 A.M. Shakes Walls of Neighbors' Homes", "Decibel Meter Reads 88 at Property Line During Drum Solo"],
        law: "disorderly",
        spec: "Disturbed the peace by making loud noise in a residential area late at night, on {DATE}.",
        ages: 18...60,
        victim: false,
        summary: "{D} hosted a band practice in a garage at 1:30 a.m. on {DATE} with drums and amplifiers. Neighbors called at 1:40 a.m. and a deputy arrived at 2 a.m. The deputy's decibel meter read 88 at the property line and rattled windows on two homes. {D} says the garage door was closed and the music was low.",
        state: [E(.document, 3, "Decibel Readings", "88 decibels at the property line at 2:05 a.m."), E(.statement, 2, "Neighbors", "Three neighbors called about the drums and amplifiers."), E(.video, 2, "Body Camera", "The deputy hears drums from the street."), E(.document, 2, "County Noise Ordinance", "Quiet hours begin at 10 p.m.")],
        defense: [E(.statement, 1, "Door Closed", "{DL} says the door was closed and the volume was low."), E(.document, 1, "Amp Settings Photo", "A photo of an amp with the volume dial at three.")],
        role: "Sheriff's deputy",
        exam: [.direct("What did you find at 2 a.m. at {D}'s garage?", "\"Drums and amplifiers going at full tilt. Windows on two homes were rattling, and my decibel meter read 88 at the property line.\""), .direct("How did the call come in?", "\"Neighbors called at 1:40 a.m. Three neighbors called about the drums and amplifiers before I arrived at 2.\""), .direct("What does the county ordinance say?", "\"Quiet hours begin at 10 p.m. The band was well into the middle of the night when I got there.\""), .direct("How did you receive the call?", "\"A neighbor called at 1:40 a.m. about drums and amplifiers in a garage. A second and third call came within ten minutes, so I headed over.\""), .direct("What did you hear when you arrived?", "\"Drums and heavy bass from the street, audible three houses away. I measured 88 decibels at the property line at 2:05.\""), .direct("What did you notice at the neighboring homes?", "\"Windows on two homes rattled with each drum hit, and one neighbor stood outside in a robe, upset. The garage door itself was closed.\""), .cross("{D} says the garage door was closed and the music low, doesn't {D.he}?", "\"The door was closed, I will agree. But I could hear the drums from the street, so it was not low.\""), .cross("Was it mainly the drums?", "\"The drums were the loudest part. The amplifiers were turned low.\""), .cross("Did {D} turn it down when you asked?", "\"A little. The drums were the problem, and the drummer kept playing.\""), .cross("The garage door was closed, wasn't it?", "\"Yes, it was down. Drums still carry through a closed garage door, especially at that hour when everything else is quiet.\""), .cross("The amplifier volume was low, wasn't it?", "\"I saw a photo with the dial at three, which is low. The drums were the loud part, and they do not have a volume knob.\"")],
        defenseRole: "Bandmate",
        defenseExam: [.direct("What time did band practice start that night?", "\"Late, after a shift. Everyone in the band works, and we only get together when we are all off work.\""), .direct("Did neighbors complain about the noise before the deputy came?", "\"Once, I think. A neighbor knocked and asked us to keep it down. We said we would.\""), .direct("Did {D} turn the volume down when asked?", "\"A little. The amps went down, but you cannot turn drums down much, and the drummer kept playing.\""), .direct("What is your role in the band?", "\"I play bass guitar and was in the garage that night. I have practiced there with {D} for about two years.\""), .direct("How was the volume set that night?", "\"The amps were turned down to three, which is quiet for us. The drums were what made most of the noise.\""), .direct("What happened when the deputy arrived?", "\"{DF} turned everything off and walked outside to meet the deputy. We all apologized and packed up our gear within ten minutes.\""), .cross("Was it past midnight when practice was happening?", "\"Yes. It was well past midnight by the time the deputy arrived, around two in the morning.\""), .cross("Had neighbors told the defendant to stop before that night?", "\"I heard that two neighbors had asked {D.him} to stop. I was not there for those conversations.\""), .cross("Were the windows rattling on nearby homes?", "\"I heard that afterward. Inside the garage, I could not tell.\""), .cross("Drums are loud even with the door shut, aren't they?", "\"Yes, they are. That was our mistake, and we know we should have practiced earlier in the day.\""), .cross("You were told to stop before by neighbors, weren't you?", "\"I heard about it from {D.him}. We kept going because we thought low amps and a closed door would be enough.\"")],
        theory: ("{D} played loudly after quiet hours.", "The garage door was closed and the volume low."),
        allocution: "\"I understand why people were afraid. I'm sorry.\"",
        truths: ("{DL} had been told twice by neighbors to stop.", "The amps were low and the drums were the problem."),
        defendant: [.direct("Did you host a band practice at 1:30 a.m.?", "\"Yes. We started late because everyone worked a shift, and I did not think about the hour.\""), .direct("Was the garage door closed during practice?", "\"Yes, it was closed. I kept the amps low, and I thought the sound would stay inside.\""), .direct("What was the loudest part of the practice?", "\"The drums. You cannot really quiet drums. The amplifiers were low, but the drumming carried.\""), .direct("Why practice so late?", "\"Our drummer works nights, and 1:30 was the only time all four of us could be together. We had a gig coming up that weekend.\""), .direct("What did you do to limit the noise?", "\"We closed the garage door, turned the amps low, and put muting pads on the drums. We tried hard not to bother anyone.\""), .direct("What happened when the deputy came?", "\"I stopped right away and apologized to the deputy. I promised we would practice earlier and quieter from now on.\""), .cross("Two neighbors had already asked you to stop before that night, hadn't they?", "\"Yes. I should have listened. I did not think a late practice was a big deal.\""), .cross("The deputy measured 88 decibels at your property line, didn't the deputy?", "\"That is what the meter said. I did not realize it was that loud outside.\""), .cross("Windows rattled on two homes. Do you accept responsibility for that?", "\"I do. I am sorry to my neighbors, and I will not practice that late again.\""), .cross("Neighbors had asked you to stop before, hadn't they?", "\"Twice, on earlier nights, and I brushed it off. I figured a closed door would be enough, and it was not.\""), .cross("88 decibels at the property line is loud, isn't it?", "\"It is. I did not know the number at the time, but I understand why the neighbors were upset at that hour.\"")],
        openings: ("{D} hosted a band practice in a garage at 1:30 a.m. with drums and amplifiers. Three neighbors called, and a deputy measured 88 decibels at the property line, with windows rattling on two homes.", "By the end of this trial, the proof will show that the garage door was closed, that the amplifiers were low, and that the drums were hard to quiet."),
        closings: ("Drums at 1:30 a.m., 88 decibels at the property line, and rattling windows on two homes. Two neighbors had already asked {D} to stop.", "A band that practiced late behind a closed door with the amps turned low. The State must prove {D} knowingly disturbed the neighbors."),
        timeline: [(0, "1:30 a.m.: practice begins."), (0, "1:40 a.m.: neighbors call."), (0, "2 a.m.: the deputy arrives."), (0, "2:10 a.m.: {D} stops.")],
        identified: "The garage is at {D}'s address.",
        notDone: ["The meter's calibration was never checked.", "The county's quiet-hours rule was never read into the record."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let cartParkingFightV1 = SmallCases.make(
        key: "story.cartParkingFight",
        category: .violent,
        headlines: ["Parents Shove at Youth Soccer Sideline Over Folding Chair", "Sideline Video Shows Shove After Chair Is Moved"],
        law: "simpleAssault",
        spec: "Assaulted {V} by shoving {V.him}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At a youth soccer game on {DATE}, {V} moved a folding chair that {D} had left to hold a spot. {D} confronted {V} at the sideline and shoved {V} backward over a cooler. {V} fell and bruised an elbow. Another parent filmed the shove at 10:15 a.m. {D} says {V} swung first.",
        state: [E(.video, 3, "Sideline Video", "{D} shoves {V} backward over a cooler at 10:15 a.m."), E(.document, 2, "Medical Note", "A bruised elbow and a scrape."), E(.statement, 2, "Other Parent", "Filmed the shove and saw no swing from {V}."), E(.document, 2, "League Report", "The league's incident form filed that morning.")],
        defense: [E(.statement, 1, "Swung First", "{DL} says {V} swung first."), E(.statement, 1, "Held Spot", "{DL} says the chair held a spot for a relative.")],
        role: "Other parent",
        exam: [.direct("Where were you on the morning of {DATE}?", "\"At a youth soccer field, watching my kid's game with the other parents along the sideline. The game began at ten.\""), .direct("What did you see happen with the chair?", "\"A chair was left holding a spot, and about ten minutes in, {V} picked it up and moved it so {V.he} could set up. {D} noticed and came over.\""), .direct("What did {D} do?", "\"{DL} walked up and began yelling at {V} about the chair. It escalated quickly, and then {DL} shoved {V} backward with both hands.\""), .direct("What happened to {V}?", "\"{V} stumbled back over a cooler and fell onto the ground, landing on an elbow. {V} was shaken up and sat there for a moment.\""), .direct("What did you do?", "\"I pulled out my phone and recorded part of it, and I helped {V} up afterward. The video shows the shove at 10:15.\""), .direct("Did you see {V} swing at the defendant?", "\"No. I watched the whole thing, and {V} did not swing or strike {DL}. I was a few feet away.\""), .cross("How far were you from them?", "\"About ten or twelve feet. I had a clear line, though some people were standing between us for a moment.\""), .cross("Did you hear what was said before the shove?", "\"I heard raised voices. Some words were lost in the crowd noise, so I can't give you everything that was said.\""), .cross("Did {V} raise a hand toward the defendant?", "\"I did not see one. {V} may have gestured while talking, but I did not see anything that looked like a swing.\""), .cross("Did your video begin before the argument?", "\"It starts partway through, right as {D.he} came up. I wasn't recording the earlier minutes.\""), .cross("Was the defendant angry about something else that morning?", "\"I'd heard grumbling about a call in the game, but I couldn't tell you whether that fed into it.\"")],
        defenseRole: "Referee",
        defenseExam: [.direct("What was your role at the game?", "\"I was the referee. I was running the match on {DATE}, and the sideline was about fifteen feet from where I stood.\""), .direct("What did you notice during the game?", "\"A few heated reactions from the parents about a call near the middle of the first half. {D} was one of those who grumbled.\""), .direct("What did you see at 10:15?", "\"I saw an argument at the sideline between {DF} and {V}, loud enough that I looked over. I saw a push and a parent fall back.\""), .direct("Did you see who started it?", "\"I saw them face each other first, and I saw {DF}'s hands go out. I did not see any swing before that.\""), .direct("What did you do?", "\"I stopped play briefly, walked over, and asked everyone to calm down. I told {D.him} to take a walk, and {D.he} did.\""), .direct("Did you file a report?", "\"The league has an incident form, and I filled it out afterward with what I saw. It is not detailed.\""), .cross("Were you watching the sideline before the push?", "\"No. My attention was on the field. I looked up when I heard voices rise.\""), .cross("Did you see {V}'s hands before the push?", "\"I saw {V}'s hand move near {DF}'s face, but I couldn't tell you whether it was a swing or a gesture.\""), .cross("Were you upset about the earlier call, too?", "\"No, I made the call and I stand by it. I understand it upset some parents.\""), .cross("Are you friendly with either of them?", "\"I know {D.his} child from the league, and I have seen {V} at games. I don't know either well.\""), .cross("How far were you?", "\"About fifteen feet, with players between us for part of it. I had a decent view but not a perfect one.\"")],
        theory: ("{D} shoved {V} over a chair.", "{V} swung first."),
        allocution: "\"I lost my temper, and I'm sorry for what I did.\"",
        truths: ("{DL} was already angry about a call from the game.", "{V} raised a hand in front of {D.him}."),
