        state: [E(.video, 3, "Station Camera", "{D}'s pickup blocks {V}'s car and {D} shouts at the window from 5:11 to 5:15 p.m."), E(.statement, 2, "{V}", "Stayed in the car and called deputies."), E(.statement, 2, "Station Clerk", "Heard the shouting and the horn."), E(.document, 2, "Deputy's Report", "Deputies arrived at 5:25 p.m. and found {D} still beside the truck.")],
        defense: [E(.statement, 1, "Near Collision", "{DL} says {V} nearly hit {D.him} backing out."), E(.document, 1, "Pump Lane Photo", "A photo of a tight turn and a crowded pump lane.")],
        role: "Gas station clerk",
        exam: [.direct("What did you see at the pumps at about 5:10 p.m.?", "\"{V} pulled out of a pump lane, and {D}'s pickup cut across the exit. {DL} stopped the truck in front of {V}'s car and got out.\""), .direct("What did {D} do after getting out?", "\"{D.He} shouted at {V}'s window for about four minutes. I could hear the shouting and a horn from inside the store.\""), .direct("What did {V} do?", "\"{V} stayed in the car and called deputies at 5:15. Deputies arrived at 5:25 and found {DL} still beside the truck.\""), .direct("What did you see at the pump?", "\"At about 5:10 a pickup pulled in front of a car at the exit and blocked it. The driver climbed out and began yelling at the car window.\""), .direct("How long did it go on?", "\"Four minutes on the camera, from 5:11 until 5:15. The driver pounded the hood once, then went back to shouting at the window.\""), .direct("What did you hear from inside?", "\"Shouting, a horn, and a lot of profanity coming through the glass. I stood at the counter ready to call, but {V} had already phoned deputies.\""), .cross("{D} says {V} nearly hit {D.him} backing out, doesn't {D.he}?", "\"A driver at the next pump says {V} did pull out sharp in a crowded lane. I will give you that.\""), .cross("Did {D} touch the car?", "\"I did not see that. The camera does not show contact.\""), .cross("Did the defendant follow {V} from the highway?", "\"I heard that, but I did not see it myself.\""), .cross("The pump lane was crowded that afternoon, wasn't it?", "\"Yes, with cars waiting at three pumps and a delivery truck on the side. It is a tight lane even on a calm day.\""), .cross("You do not know what started it, do you?", "\"No. I only saw the end of the turn out of the pump lane and the blocking that followed. I did not see the first words.\"")],
        defenseRole: "Driver at the next pump",
        defenseExam: [.direct("Did the car cut in at the pumps?", "\"It pulled out sharp. The lane was crowded, and {V} did not leave much room as the car came out.\""), .direct("Did the pickup block the car?", "\"For a while. It sat in front of the car for a few minutes, and the car could not move.\""), .direct("Did {D} shout at the car?", "\"Yes. {D} shouted at the window for several minutes. It was loud, and a few people turned to look.\""), .direct("What did you see at the next pump?", "\"A car backed out in the crowded lane and nearly hit the driver who was fueling at the next pump. It was a very tight space for that.\""), .direct("How did the defendant react?", "\"{D.He} jumped back and then stormed over to the car, clearly shaken. It looked to me like a real scare, not an act.\""), .direct("What did you do?", "\"I stepped away from my pump and watched. I did not get involved, and I did not hear every word that was said.\""), .cross("Did you see the defendant touch the car?", "\"I did not see that. I was filling my tank and watching from the side.\""), .cross("Did the defendant threaten {V} in any way?", "\"I could not hear the words. I only heard shouting, and it sounded angry.\""), .cross("Was {V} in danger?", "\"I do not think so. {V} stayed in the car, and nothing physical happened.\""), .cross("You did not see the whole thing, did you?", "\"No. I saw the near miss and then the shouting, but I turned back to my fuel for a moment in between.\""), .cross("The shouting went on for several minutes, didn't it?", "\"Yes, it did, and it felt longer standing there. I would call it more than a quick burst of anger.\"")],
        theory: ("{D} blocked and screamed at {V}.", "{V} nearly hit {D}."),
        allocution: "\"I'm sorry for the trouble I caused.\"",
        truths: ("{DL} had followed {V} from the highway before the stop.", "{V} did back out in a crowded lane."),
        defendant: [.direct("Did you block {V}'s car with your pickup?", "\"Yes. I stopped in front of it because {V} nearly hit me backing out of the pump lane.\""), .direct("Why did you shout at {V}?", "\"I was scared and angry. The car came within inches of me, and I got out to tell {V.him}.\""), .direct("Had you followed {V} from the highway?", "\"I was on the same road. I did not follow {V.him}. I came into the station behind {V.him}.\""), .direct("What happened as {V} pulled out?", "\"I was fueling when a car backed out of its spot at a sharp angle, and I had to jump back to keep from being hit. My heart was pounding.\""), .direct("Why did you stop in front of the car?", "\"I wanted to talk to the driver and make sure the person understood how close it was. I parked my truck across the exit and got out.\""), .direct("What did you say?", "\"I shouted that the driver needed to watch where the car was going. I was frightened and angry, and my voice got loud.\""), .cross("You shouted at the window for four minutes, didn't you?", "\"Yes. I was loud. I should have walked away after a few seconds.\""), .cross("{V} stayed in the car and called deputies. Was {V} afraid?", "\"I think so. I did not mean to scare {V.him}. I feel awful about it.\""), .cross("You were still beside the truck when deputies arrived, weren't you?", "\"Yes. I did not leave. I told them what happened.\""), .cross("You blocked the car, didn't you?", "\"Yes, with my truck. I did not want the driver to leave before I had a chance to say my piece, and I know that was wrong.\""), .cross("You saw {V}'s car on the highway before the station, didn't you?", "\"I noticed the car on the road earlier and recognized it when it pulled into the station. I was not following it deliberately.\"")],
        openings: ("At a gas station, {D}'s pickup cut across the exit of {V}'s car, and {D} stopped the truck in front of it, got out, and shouted at {V}'s window for four minutes. {V} stayed inside and called deputies.", "The defense witnesses will explain that {V} backed out sharply in a crowded lane, nearly hit {D}, and that {D} shouted in fright, without touching the car."),
