        timeline: [(0, "5:10 p.m.: {V} pulls out."), (0, "5:11 p.m.: {D} blocks the car."), (0, "5:15 p.m.: {V} calls deputies."), (0, "5:25 p.m.: deputies arrive.")],
        identified: "The station camera identifies {D}'s truck.",
        notDone: ["The gas pump's sound recording was never reviewed.", "The other drivers in line were never interviewed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let shedSprayPaintV1 = SmallCases.make(
