        defense: [E(.statement, 1, "Lights On", "{DL} says the lights were on so {D.he} thought the field was open."), E(.document, 1, "Lighting Schedule", "A schedule showing the lights on until 10 p.m. for a practice.")],
        role: "Custodian",
        exam: [.direct("What did you find at the stadium at 8:30 p.m.?", "\"{D} and three friends climbed the gate and played flag football under the lights. A posted notice says the field closes to the public after 6.\""), .direct("What did you tell the group?", "\"I asked them twice to leave. They refused both times and stayed until deputies arrived at 9:15.\""), .direct("How was the gate marked?", "\"With signs on the gate and an athletic department notice. The gate was closed that evening.\""), .direct("What was the status of the stadium that night?", "\"Closed to the public after six, with a notice on the gate. A practice had ended at eight, and the lights stayed on until ten.\""), .direct("What did you see?", "\"Four people climbed the gate at 8:30 and began a flag football game on the field. I called to them from the sideline.\""), .direct("What did you say?", "\"I told them the field was closed and asked them to leave. I asked a second time about ten minutes later when they kept playing.\""), .cross("{D} says the lights were on so {D.he} thought it was open, doesn't {D.he}?", "\"The lights were on for a practice that had ended. I will agree they were on.\""), .cross("Was the sign easy to read?", "\"It was faded in places. I know that.\""), .cross("Was anyone hurt or anything damaged?", "\"No. No one was hurt, and nothing was damaged.\""), .cross("The lights were on, weren't they?", "\"Yes, they were on for a practice that had just ended. I did not turn them off myself, and I know that could confuse people.\""), .cross("No one damaged anything, did they?", "\"No. They played football and left when deputies arrived, and the field was fine the next morning.\"")],
        defenseRole: "Friend who played",
        defenseExam: [.direct("Was the stadium gate open that night?", "\"Closed. We had to climb over it to get onto the field, and it was not hard for anyone.\""), .direct("Did you see the sign on the gate?", "\"Faded. I did not read it before climbing. I only noticed it after the custodian came and pointed.\""), .direct("Did the stadium lights come on by themselves?", "\"They were on when we arrived. A practice had ended earlier, and the lights stayed on for hours.\""), .direct("How do you know {D}?", "\"We are friends from the same team. I was part of the group that climbed the gate and played.\""), .direct("What was the situation when you arrived?", "\"Lights on, gate closed, and a clean field with no one around. We assumed it was fine because the lights were on.\""), .direct("What did the defendant say about it?", "\"That the lights meant the field was open and we could use it. {D} was the one who suggested climbing over.\""), .cross("Did you climb the gate along with the defendant?", "\"Yes. We all climbed it together. It was easy enough, and none of us stopped to think.\""), .cross("Did a guard come right away when you started playing?", "\"Eventually. The custodian came first, and then deputies later, after we had played a while.\""), .cross("Did anyone tell you the field was closed that night?", "\"The custodian did, twice. We stayed anyway, and I regret that now.\""), .cross("You saw the notice, didn't you?", "\"On the way over the gate, yes. I did not stop to read what it said.\""), .cross("You stayed after the custodian asked you to leave, didn't you?", "\"We did, for about half an hour. We thought we would just finish the game.\"")],
        theory: ("{D} climbed into a closed stadium and stayed.", "{D} thought the field was open because of the lights."),
