        state: [E(.video, 3, "Helmet Camera", "{D} passes stopped cars at close range with the speedometer visible."), E(.document, 2, "Radar Reading", "80 miles per hour on the shoulder at 5:42 p.m."), E(.digital, 2, "911 Recordings", "Two callers describe a motorcycle weaving between stopped cars."), E(.statement, 2, "Trooper", "Stopped {D} at 5:55 p.m. after a chase of two miles.")],
        defense: [E(.statement, 1, "Speed of Traffic", "{DL} says traffic was moving and {D.he} rode at the speed of traffic."), E(.document, 1, "Traffic Report", "A report showing slow movement at 5:30 p.m.")],
