        doctrines: ["burdenOfProof"],
        genders: ["D": .female])

    static let ghostKitchenFeeV1 = SmallCases.make(
        key: "story.ghostKitchenFee",
        category: .whiteCollar,
        headlines: ["Man Takes $900 to File Business Licenses for Four Hair Braiders and Files Nothing", "County Clerk Finds No Applications Under Braiders' Names"],
        law: "falsePretenses",
        spec: "Obtained $900 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} told {V}, a hair stylist, on {DATE} that {D} could file the licenses and permits for a home salon and charged $900. Four other stylists paid the same fee. {D} promised the filings within two weeks and then stopped answering. The county clerk had no applications under any of the five names. {D} says the county lost the paperwork.",
        state: [E(.document, 3, "Receipts", "Five receipts for $900 signed by {D}."), E(.document, 3, "County Response", "No applications under any of the five names."), E(.digital, 2, "Texts", "{D} promises filings within two weeks and then goes silent."), E(.statement, 2, "Other Stylists", "Four stylists paid the same fee for the same service.")],
        defense: [E(.statement, 1, "Lost Paperwork", "{DL} says the county lost the paperwork."), E(.document, 1, "Filing Copy", "A copy of an application dated two days after the fee with no stamp.")],
        role: "Hair stylist",
        exam: [.direct("How do you earn a living?", "\"I'm a hair stylist. I rent a chair in a shop now, and I wanted to open a small home salon, which needs county permits and a license.\""), .direct("How did you meet {D}?", "\"{D} came through a stylist group and said {D.he} handled licenses and permits for home salons. {D.He} said the fee was $900 and the filing would be done within two weeks.\""), .direct("What did you do?", "\"I paid $900 on {DATE} and signed a receipt. I have the receipt, and {D.he} signed it too.\""), .direct("What did the defendant promise?", "\"In texts, {D.he} promised that the filings would be in within two weeks. After that date passed, I wrote back and got no reply.\""), .direct("What did you do when you did not hear back?", "\"I called the county clerk. About three weeks after I paid, the clerk told me there was no application under my name.\""), .direct("Were you the only one who paid?", "\"No. Four other stylists told me they had paid the same fee for the same service, and the county had nothing for any of us.\""), .cross("Did you ever see the defendant file anything?", "\"No. I never saw a filing or a stamped form. I only had {D.his} word.\""), .cross("Did the county tell you the application might have been lost?", "\"The clerk said there was no record, which could mean never filed or misfiled. The clerk did not say it was lost.\""), .cross("Did the defendant ever show you a copy of an application?", "\"Not at first. Later, {D.he} sent a copy dated two days after the payment, but it had no stamp. That did not reassure me.\""), .cross("How long did you wait before reporting?", "\"About a month after paying. I gave {DL} time, texts and calls, before going to the Sheriff's Office.\""), .cross("Did the defendant refund any part of the fee?", "\"No. Not a dollar. {D.He} stopped answering my messages.\"")],
        defenseRole: "Stylist who paid",
        defenseExam: [.direct("How did you come to know {D}?", "\"I met {D} through a stylist group chat. {D.He} offered to handle home salon permits for a flat fee, and I signed up.\""), .direct("What did you pay?", "\"$900 in cash, on a date close to the other stylists' payments. {D.He} signed a receipt for me.\""), .direct("What did the defendant promise?", "\"That the application would be filed with the county within two weeks. {D.He} texted me to say it was on the way.\""), .direct("What happened after two weeks?", "\"Nothing. I texted and called. At first {DF} replied, then there was silence.\""), .direct("How did you check on it?", "\"I called the county clerk's office about three weeks after payment. They had nothing under my name.\""), .direct("What did you do then?", "\"I talked to the other stylists. We all paid the same fee, and none of us had anything filed.\""), .cross("Did you see the application?", "\"Once, a copy that {D.he} emailed. It had no stamp on it. I had no way of knowing if it was filed.\""), .cross("Did the defendant tell you the county lost anything?", "\"Eventually, {D.he} suggested that. The clerk told me nothing about lost documents.\""), .cross("Did you ask for a refund?", "\"Yes, in a text. {D.He} did not answer.\""), .cross("How much money did you lose?", "\"$900. I'm out that amount, and I have not been able to open a home salon.\""), .cross("Did you check the county's website?", "\"I looked. There was no application number that matched any of our names.\"")],
        theory: ("{D} took fees and filed nothing.", "The county lost the paperwork."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} spent the fees on a car repair.", "{DL} did prepare an application but never submitted it."),
        defendant: [.direct("What service did you offer?", "\"I helped people with the paperwork for home salon permits and licenses. It is a long process, and I charged $900 for putting the applications together.\""), .direct("Did you collect fees from five stylists?", "\"Yes, $900 each. I signed a receipt for each one, and I meant to file every application.\""), .direct("Did you prepare the applications?", "\"I started one. I had it ready two days after the fee came in. I did not send it, and I regret that.\""), .direct("Why did you stop answering the stylists?", "\"I got overwhelmed. I'd taken money I could not account for, and I did not know what to say. I let the messages pile up.\""), .direct("What happened to the money?", "\"I used part of it for a car repair that I needed to get to work. I planned to catch up on the filings.\""), .direct("What do you say about the county?", "\"I believe the county lost some of the paperwork. I'm not sure about that, and I will not claim it for all of them.\""), .cross("The county has nothing under any of the five names, does it?", "\"That is what I'm told. I don't dispute that the county has no record.\""), .cross("The copy you gave {V} has no stamp, does it?", "\"No stamp. It was a copy of what I prepared, but I did not submit it.\""), .cross("You took $4,500 in total, didn't you?", "\"Five fees of $900. Yes. I understand it adds up to that.\""), .cross("You promised two weeks and went silent, didn't you?", "\"I did, and I did not call back. That was wrong, and I own it.\""), .cross("You spent the money on a car repair, didn't you?", "\"On part of it. It was a need. I know it was not mine to spend.\"")],
        openings: ("Five hair stylists each paid {D} $900 to file home salon licenses and permits. {D} promised filings in two weeks and then stopped answering, and the county has no application under any of the five names. You will hear from a stylist who paid and who has the signed receipt.", "{D} did take $900 from each stylist and did prepare at least one application. {D} says the county lost the paperwork, and a copy of the application survives. You will hear that the money went to real expenses and a plan to catch up."),
        closings: ("Five receipts signed by {D}, a promise of two weeks, and four and a half thousand dollars with nothing filed. The county has no record for any of the five. {D} stopped answering and spent the money.", "{D} prepared an application and believes the county lost some paperwork. The stylists were never asked about the promised timeline, and the unsent application was never recovered. The State must prove {D} never meant to do the work."),
        timeline: [(0, "{V} pays the fee."), (14, "The promised filing date passes."), (20, "The county reports no application."), (30, "{V} reports the fee to the Sheriff's Office.")],
        identified: "The signed receipts name {D}.",
        notDone: ["The unsent application was never recovered.", "The stylists were never asked about the promised timeline."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let stolenChargerV1 = SmallCases.make(
