        state: [E(.video, 3, "Laundromat Camera", "{D} picks up a phone and wallet and puts them in a laundry bag at 7:17 p.m."), E(.digital, 3, "Phone Locator", "The phone pings from {D}'s address at 9 p.m."), E(.document, 2, "Wallet Contents", "A driver's license and cards in {V}'s name."), E(.statement, 2, "Attendant", "Saw {D} folding at the next table.")],
        defense: [E(.statement, 1, "Thought It Was Mine", "{DL} says {D.he} thought the phone and wallet were {D.his} own."), E(.document, 1, "Similar Phone", "A receipt for a similar phone model owned by {DL}.")],
        role: "Laundromat customer",
