        defense: [E(.statement, 1, "Scanner Error", "{DL} says the scanner mislabeled the address."), E(.document, 1, "Scanner Maintenance Log", "A repair ticket on the scanner the week before.")],
        role: "Package recipient",
        exam: [.direct("What did you order?", "\"Three packages worth $410 in all. They were marked 'delivered' but never arrived at my home.\""), .direct("What does the scan log show?", "\"Three scans at a vacant lot address by {D}'s scanner at 3:10 p.m., after which {D.he} left the route.\""), .direct("What turned up later?", "\"The same items on {D.his} marketplace account two days later.\""), .direct("What did you order and when did it ship?", "\"Three items totaling $410, a pair of headphones, a camera lens, and a speaker. The tracking said they shipped together and would arrive on the same afternoon.\""), .direct("What did the tracking show?", "\"All three were scanned as delivered to a vacant lot address at 3:10 p.m. I was home that afternoon and no truck came to my door.\""), .direct("How did you find the items?", "\"Two days later I saw the same headphones and lens on a marketplace account tied to {D.him}. The photos showed the original packaging.\""), .cross("{D} says the scanner mislabeled the address, doesn't {D.he}?", "\"The scanner was repaired the week before and had some glitches. That much is true.\""), .cross("Is the vacant lot on the defendant's route?", "\"No. The dispatcher says it is not on the route.\""), .cross("Did anyone see the defendant take the packages?", "\"No. No one saw {DL} take them.\""), .cross("You did not see the driver at any time, did you?", "\"No, I was inside, and my doorbell camera shows no delivery that day. I rely on the scan log and the listings.\""), .cross("Scanners sometimes mislabel addresses, don't they?", "\"Occasionally, and the company has said so. A mislabel would not explain why my items showed up for sale.\"")],
        defenseRole: "Fellow driver",
        defenseExam: [.direct("Was the delivery route overloaded for drivers?", "\"Always. We carried far more packages than we could deliver in a shift, and drivers fell behind constantly.\""), .direct("Did you ever scan packages to a vacant lot?", "\"Never. I have never scanned a package to a vacant lot. That would be a serious problem.\""), .direct("Did {D} fall behind on the route?", "\"Often. {D} had the heaviest route, and I saw {DF} struggling to finish on time.\""), .direct("How do you know the defendant?", "\"We drive for the same delivery company and cross paths at the depot. I was there the day the scanner was repaired.\""), .direct("What problems did the scanners have?", "\"Several froze and recorded wrong addresses for a few days. A repair ticket was filed on {D.his} unit.\""), .direct("How did the defendant handle it?", "\"{DF} complained about the glitches and asked a supervisor to look. Nothing was done for a week.\""), .cross("Did you see the defendant selling parcels online?", "\"No. I did not see that. I only know about the route.\""), .cross("Was the scanner repaired recently?", "\"The week before. It had glitches afterward, and some of us had odd scans.\""), .cross("Could a glitch put a scan at a vacant lot?", "\"It could mislabel an address. I do not know about a lot that is not on the route.\""), .cross("A glitch would not put items on a marketplace account, would it?", "\"No. That part has to be done by a person.\""), .cross("You did not check the defendant's deliveries, did you?", "\"No. I only handle my own route.\"")],
        theory: ("{D} scanned packages as delivered and sold them.", "A scanner mislabeled the address."),
        allocution: "\"I'm sorry. It won't happen again.\"",
        truths: ("{DL} had done the same to four other customers.", "The scanner was repaired the week before and had glitches."),
        defendant: [.direct("Did you steal {V}'s packages?", "\"No. The scanner mislabeled the address, and I did not mean to scan them to a vacant lot.\""), .direct("Why did you leave the route at 3:10?", "\"I was behind and exhausted. I went off the route to catch up, and I did not realize the scans.\""), .direct("Where did the items listed on your account come from?", "\"I bought items from a customer who gave them to me. I did not know they were {V}'s.\""), .direct("How is your route organized?", "\"About a hundred and twenty stops a day, scanned on a handheld unit. The unit had been repaired the week before after it kept freezing.\""), .direct("What happened with these packages?", "\"The scanner glitched and recorded the wrong address for several stops. I corrected a few and missed these.\""), .direct("How do you explain the listings?", "\"I bought a few returned items from a liquidation sale and listed them. I did not realize some matched deliveries.\""), .cross("The items on your marketplace account match {V}'s orders, don't they?", "\"They do. I do not know how. I did not take them.\""), .cross("You did the same to four other customers, didn't you?", "\"I did not. If it happened, it was the scanner.\""), .cross("You marked packages for four other customers the same way, didn't you?", "\"Yes, and I told dispatch they were scanner errors. In hindsight it looks like a pattern.\""), .cross("The vacant lot is not on your route, is it?", "\"No. I do not have a good reason for why the scanner picked it.\""), .cross("The scanner was repaired the week before, but you never reported a problem, did you?", "\"No. It worked well enough that I did not report anything. I should have told dispatch about the glitches right away.\"")],
        openings: ("{V} ordered three packages worth $410 that were marked 'delivered' but never arrived. The scan log shows {D}'s scanner marking them delivered to a vacant lot, and the same items appeared on {D}'s marketplace account.", "The defense evidence will establish that the scanner had been repaired the week before and had glitches, and that the route was impossibly overloaded."),
        closings: ("Three scans to a vacant lot that is not on the route, and the same items for sale on {D}'s account two days later. This was theft by a driver.", "A glitchy scanner and an overloaded route. The State must prove {D} took the packages, and a mislabeled scan is not a theft."),
        timeline: [(0, "3:10 p.m.: {D} scans the packages."), (2, "{D} lists the items online."), (3, "{V} sees the listing."), (5, "{V} reports the theft.")],
        identified: "The scan log names {D}.",
        notDone: ["The route's timing and workload were never reviewed.", "The marketplace listings' account was never traced to a location."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let rentalTrailerNotReturnedV1 = SmallCases.make(
        key: "story.rentalTrailerNotReturned",
        category: .property,
        headlines: ["Customer Keeps Rented Pressure Washer and Generator for Five Weeks", "Rental Tracker Shows Equipment at Job Sites Across Town"],
        law: "misdLarceny",
        spec: "Stole rented equipment valued at $1,300 belonging to {V}, a rental company, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} rented a pressure washer and a generator on {DATE} for a weekend and did not return them. The rental company's trackers show the equipment at three job sites over five weeks. The company called and texted {D} eleven times. A manager recovered both machines on day 36. {D} says {D.he} asked for an extension by text.",
        state: [E(.digital, 3, "Equipment Trackers", "Both machines at three different job sites over five weeks."), E(.document, 3, "Rental Contract", "A weekend rental ending Monday at 8 a.m. signed by {D}."), E(.digital, 2, "Call and Text Log", "Eleven calls and texts to {D} with no answer."), E(.statement, 2, "Rental Manager", "Recovered the equipment on day 36.")],
        defense: [E(.statement, 1, "Extension Text", "{DL} says {D.he} asked for an extension by text."), E(.document, 1, "Sent Text", "A text 'can I keep it another week?' sent on day four.")],
        role: "Rental manager",
        exam: [.direct("What did {D} rent from your company?", "\"A pressure washer and a generator for a weekend. The contract ended Monday at 8 a.m., and {D} signed it.\""), .direct("What did the defendant rent?", "\"A pressure washer and a generator for a weekend, due back Monday at eight in the morning. {D.He} signed the contract and left a card.\""), .direct("What did your trackers show?", "\"Both machines moved to three different job sites over five weeks, with long runs of use. The generator ran for hours each day.\""), .direct("How did you try to reach the defendant?", "\"Eleven calls and texts over five weeks with no answer. I recovered both machines at a job site on day 36.\""), .direct("What did you do when the equipment was not back by Monday at 8 a.m.?", "\"I called and texted. When there was no answer, I checked the tracker and saw it moving between job sites, so I knew it was being used.\""), .direct("What condition was the equipment in when you recovered it?", "\"Both machines were dirty and the generator had a cracked housing. We had to clean the washer and replace a hose before it could be rented again.\""), .cross("{D} says {D.he} asked for an extension by text, doesn't {D.he}?", "\"Yes. A text shows {DL} asking. I will say that no one answered it.\""), .cross("Did the defendant use the equipment on paid jobs?", "\"The trackers suggest so. It was at job sites, so probably.\""), .cross("Was the equipment damaged?", "\"No. Both machines came back working. I have no complaint about the condition.\""), .cross("You did receive a text asking about an extension, didn't you?", "\"Yes, on day four, asking whether {D.he} could keep the equipment another week. I did not answer it.\""), .cross("{D} was billed for the extra time, wasn't {D.he}?", "\"Yes, the card on file was charged for the overage.\"")],
        defenseRole: "Job site foreman",
        defenseExam: [.direct("Did {D} use the pressure washer and generator on jobs?", "\"Three jobs that I know of. I saw the equipment on the sites where {D} was working.\""), .direct("Did the defendant know the equipment was due back?", "\"I would guess so. The contract is clear about the date, though no one reminded {D.him} at the site.\""), .direct("Did anyone ask the defendant to return the equipment?", "\"No. Nobody on the sites said anything to {D.him} about returning it while I was there.\""), .direct("What is your role?", "\"I am a job site foreman who works with {D.him} on projects. I saw the machines on site.\""), .direct("What did the defendant tell you about the rental?", "\"That it was extended by text and that the shop knew. I took it at face value.\""), .direct("How were the machines used?", "\"Daily, for washing siding and powering tools on three different sites. They were in good shape.\""), .cross("Did you see calls coming in to the defendant's phone?", "\"Some. I saw {DF} look at the phone and put it away a few times, and I did not ask.\""), .cross("Was {D} paid for the jobs that used the equipment?", "\"Yes, as far as I know. {D.He} was paid by the clients for the work.\""), .cross("Did the defendant ever mention the rental company to you?", "\"Once. {D.He} said something about asking for more time, but I did not hear details.\""), .cross("You never saw the text from the shop, did you?", "\"No. I only heard about it from {D.him}.\""), .cross("The machines were not returned on time, were they?", "\"No. They were with us for weeks.\"")],
        theory: ("{D} kept rented equipment for five weeks.", "{D} asked for an extension."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} used the equipment on paid jobs.", "{DL} did text but never got an answer and kept it."),
        defendant: [.direct("Did you keep the rental equipment past the weekend?", "\"Yes. I asked for an extension by text, and I never got an answer. I kept using it on jobs.\""), .direct("Why did you not return it?", "\"I did not hear back, and I assumed it was fine. I should have called, and I did not.\""), .direct("Did you use the equipment on paid jobs?", "\"Yes. Three jobs. I needed the machines, and I intended to pay the extra rental fees.\""), .direct("Why did you keep the equipment?", "\"A job came up that needed both machines, and I could not afford to rent new ones. I sent a text asking for more time.\""), .direct("What did you hear back?", "\"Nothing. I figured silence meant it was fine, and I kept working.\""), .direct("What did you do when the manager came?", "\"I handed over both machines and paid what I owed. I apologized for the confusion.\""), .cross("You ignored eleven calls and texts, didn't you?", "\"I did not answer most of them. I was embarrassed that I kept it so long.\""), .cross("Five weeks is a long time past a weekend rental, isn't it?", "\"It is. I know. I let it go on too long.\""), .cross("You never got an answer to your extension text, did you?", "\"No. I took that as a yes. I should not have.\""), .cross("You used the equipment on paid jobs, didn't you?", "\"Yes. I earned money from the equipment I should have returned.\""), .cross("You did not answer the manager's calls, did you?", "\"No. I did not pick up. I kept thinking I would bring the equipment back after the next job, and one job turned into another.\"")],
        openings: ("{D} rented a pressure washer and a generator for a weekend and kept them for five weeks, using them at three job sites. The company called and texted eleven times, and a manager recovered both machines on day 36.", "By the end of this trial, the proof will show that {D} texted the company for an extension, never got an answer, and fully meant to pay for the extra time the machines were used."),
        closings: ("A weekend rental, five weeks, three job sites, and eleven calls and texts ignored. {D} kept the equipment and used it for pay.", "A text asking for an extension that was never answered, and a renter who kept working. The State must prove {D} meant to keep the equipment."),
        timeline: [(0, "{D} rents the equipment."), (2, "Monday: the equipment is not returned."), (4, "{D} sends the extension text."), (36, "The manager recovers the machines.")],
        identified: "The rental contract and the tracker identify {D}.",
        notDone: ["The rental company's call log was never matched to {DL}'s phone.", "The late fee schedule was never read into the record."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let campgroundHookupsV1 = SmallCases.make(
        key: "story.campgroundHookups",
        category: .property,
        headlines: ["RV Plugged Into State Park Maintenance Shed Outlet for Three Weeks", "Park Ranger Traces Extension Cord From Shed to Camper"],
        law: "misdLarceny",
        spec: "Stole electricity valued at $320 belonging to {V}, a state park, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} parked an RV in an overflow lot at a state park and ran a cord to an outlet on a maintenance shed for three weeks before {DATE}. The park's meter showed constant draw. A ranger followed the cord to the RV on {DATE}. The unpaid power was valued at $320. {D} says a ranger told {D.him} the shed outlet was fine.",
        state: [E(.physical, 3, "Extension Cord", "A 100-foot cord from the shed outlet to the RV, with a splice."), E(.document, 3, "Meter Readings", "Constant draw on the shed circuit from the first day."), E(.statement, 2, "Ranger", "Followed the cord and found {D}'s RV."), E(.document, 2, "Camping Permit", "A permit for the overflow lot that does not include power.")],
        defense: [E(.statement, 1, "Ranger Said Fine", "{DL} says a ranger said the shed outlet was fine."), E(.document, 1, "Fee Receipt", "A receipt for the overflow lot for three weeks.")],
        role: "Park ranger",
        exam: [.direct("What do you do at the state park?", "\"I'm a park ranger. I patrol the campgrounds and the overflow lot, and I check on the maintenance buildings.\""), .direct("What led you to {D}'s RV?", "\"The park's electric meter on the shed circuit showed a constant draw that did not fit our equipment. On {DATE} I followed an extension cord from the shed outlet.\""), .direct("What did you find on the cord?", "\"A 100-foot orange cord with a splice in the middle, running across the grass and under a hedge to an RV in the overflow lot.\""), .direct("Whose RV was it?", "\"{D}'s. The overflow lot permit on the dash had {D.his} name. The permit covers parking only, and it does not include power.\""), .direct("How long was the RV plugged in?", "\"About three weeks. The meter showed the draw starting the day the RV was parked, and it never stopped.\""), .direct("What was the cost?", "\"The park priced the power at $320 for three weeks of continuous use.\""), .cross("Was the shed outlet locked?", "\"The outlet box had a cover, but I did not inspect whether the lock was cut. I only noticed the cord.\""), .cross("Did any ranger tell the defendant the outlet was fine?", "\"I did not. I can't speak for the other rangers or the seasonal workers. I do not know who {D.he} talked to.\""), .cross("Did the defendant hide the cord?", "\"It ran under a hedge for part of the way, but I'd say it was visible from the lot. It was not buried.\""), .cross("Did the defendant pay a fee for the overflow lot?", "\"Yes, a receipt shows three weeks of lot fees. Those cover the space only.\""), .cross("Did the defendant cooperate when you found the RV?", "\"Yes. {D.He} came out of the RV when I knocked, answered every question, and unplugged when I asked.\"")],
        defenseRole: "Seasonal park worker",
        defenseExam: [.direct("What do you do at the park?", "\"I'm a seasonal worker. I mow, clean the restrooms, and help campers find sites. I was working that summer.\""), .direct("Do campers ask about power?", "\"All the time. We tell them hookups are only at the numbered sites, and the overflow lot is dry.\""), .direct("Did you talk to {D}?", "\"I spoke with {D} once, when {D.he} was checking in to the overflow lot. {D.He} asked about electricity.\""), .direct("What did you say?", "\"I said there was an outlet on the shed that some campers charge phones at. I did not tell {D.him} to run a cord for weeks.\""), .direct("What is your authority at the park?", "\"None, really. I'm not a ranger. I can't approve power use. I should have said so more clearly.\""), .direct("Did you ever see the cord?", "\"Later in the week I saw an orange cord near the shed. I thought it was for charging, and I didn't report it.\""), .cross("Did you tell the defendant the power was free?", "\"I said people charge phones there. I did not say a camper could hook an RV to it.\""), .cross("Did you know about the three weeks?", "\"No. I'd have said something if I had. I did not notice the length of time.\""), .cross("Did you check with a supervisor?", "\"No. I answered off the cuff. I should not have.\""), .cross("Do you remember exactly what you said?", "\"Not word for word. I remember the phone charging part.\""), .cross("Did you see the RV?", "\"I saw it parked in the lot. I did not go inside.\"")],
        theory: ("{D} drew park power for weeks without paying.", "A ranger said it was fine."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} had cut the lock to the shed outlet box.", "A seasonal worker had told {DL} the outlet was free."),
        defendant: [.direct("Why were you parked at the overflow lot?", "\"I was between jobs and traveling in my RV. The overflow lot was cheap, and the park had no hookups left in the regular sites.\""), .direct("How did you get power?", "\"I ran a cord to an outlet on the maintenance shed. I saw it was an exterior outlet with a plug-in cover and assumed it was meant for use.\""), .direct("Did anyone tell you it was fine?", "\"A worker at the park told me the shed outlet was free for campers. I accepted the worker's word without question.\""), .direct("Did you know it would draw park power?", "\"Yes, of course it did. I did not know it was a metered circuit that would be billed to the park.\""), .direct("Did you cut a lock on the box?", "\"I'm not going to get into that. The outlet was usable, and I plugged in.\""), .direct("What did you do when the ranger found you?", "\"I unplugged right away and apologized. I offered to pay for what I had used.\""), .cross("You spliced the cord, didn't you?", "\"The cord had a splice because I'd repaired it once. It is the one I had.\""), .cross("Your permit did not include power, did it?", "\"No, only the lot space. I read that, but I thought the shed outlet was an exception.\""), .cross("You were plugged in for three weeks, weren't you?", "\"Close to it. The draw was constant because of the refrigerator and the heater.\""), .cross("You never asked the front office about the outlet, did you?", "\"No. I should have gone to the office. I trusted what I was told.\""), .cross("You can't name the person who said it was free, can you?", "\"It was a seasonal worker in a park shirt. I did not catch a name.\"")],
        openings: ("For three weeks, a 100-foot orange cord ran from a maintenance shed outlet to {D}'s RV in the overflow lot. The meter showed constant draw from the first day, and the ranger followed the cord to the RV. The power is valued at $320.", "{D} was told by someone in a park shirt that the shed outlet was free for campers. A seasonal worker will tell you what was said and admit that no one defined the limits. {D} unplugged the moment a ranger asked."),
        closings: ("A cord, a splice, a permit that covers a space and no power, and three weeks of draw on the park's meter. {D} knew the outlet was not on any site. That is $320 of park electricity.", "A seasonal worker talked about phone charging, and {D} took it to mean more. The worker's authority was never defined and the meter was never read on the first day. The State must prove {D} knew the power was not free."),
        timeline: [(-21, "{D} parks the RV and plugs in."), (0, "The ranger follows the cord."), (0, "The park reads the meter."), (2, "The park prices the power.")],
        identified: "The cord ties the RV to {D}.",
        notDone: ["The seasonal worker's authority was never defined.", "The shed circuit's meter was never read on the first day."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let hayBaleTheftV1 = SmallCases.make(
        key: "story.hayBaleTheft",
        category: .property,
        headlines: ["Farm Hand Hauls Feed Sacks Out of Barn Over Several Weeks", "Feed Store Inventory Does Not Match Sacks Used on the Farm"],
        law: "misdLarceny",
        spec: "Stole feed valued at $620 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D}, a hired farm hand, was in charge of the feed barn on {DATE}. {V} noticed the feed bill climbing while the herd stayed the same size. A count showed twenty-two sacks missing over three weeks, worth $620. A neighbor reported {D}'s truck leaving the barn at dawn with sacks in the bed. {D} says the missing sacks were leftover scraps.",
        state: [E(.document, 3, "Inventory Count", "Twenty-two sacks missing over three weeks against feed store receipts."), E(.document, 3, "Feed Store Receipts", "Deliveries of 40 sacks a week for a herd that uses 28."), E(.statement, 2, "Neighbor", "Saw {D}'s truck leave the barn at dawn with sacks in the bed."), E(.video, 2, "Barn Camera", "{D} loads six sacks into a truck bed at 5:40 a.m.")],
        defense: [E(.statement, 1, "Leftover Scraps", "{DL} says the missing sacks were leftover scraps being thrown away."), E(.document, 1, "Waste Log", "A log with several entries for 'spoiled feed' signed by {DL}.")],
        role: "Farm owner",
        exam: [.direct("What do you own?", "\"A dairy and beef farm with a feed barn behind the milking parlor. I hired {D} as a farm hand and gave {DL} a key to the barn.\""), .direct("What made you suspicious?", "\"The feed bill kept climbing while my herd stayed the same size. I counted the cows twice and the number never changed.\""), .direct("What did the receipts show?", "\"Deliveries of forty sacks a week for a herd that uses about twenty-eight. The extra twelve a week had to be going somewhere.\""), .direct("What did your inventory count find?", "\"Twenty-two sacks missing over three weeks, worth $620. I checked the delivery slips against what was in the barn.\""), .direct("What did your neighbor tell you?", "\"A neighbor who drives by at dawn said {DL}'s truck left the barn at about 5:40 with sacks in the bed, more than once.\""), .direct("What did your barn camera show?", "\"It shows {DL} loading six sacks into a truck bed at 5:40 a.m. on the camera. I saw it when I reviewed footage.\""), .cross("Was feed ever lost to rats or spoilage?", "\"Some, yes, every barn has it. I never measured it, and I can't give a figure for the loss from pests.\""), .cross("Did you give {D} permission to dispose of spoiled feed?", "\"If a sack went bad, I told {D.him} to throw it out. I did not tell {D.him} to drive it away or take it home.\""), .cross("Did the waste log show entries?", "\"Yes, {D.he} signed several entries for spoiled feed. I didn't review them closely until the shortage.\""), .cross("Did anyone else have a key?", "\"I had one, and a relative's family farms next door and sometimes borrows feed. I would have known about that.\""), .cross("Did you confront the defendant before calling the Sheriff?", "\"I asked about the sacks, and {DL} said they were scraps. I did not accept that and reported it three days later.\"")],
        defenseRole: "Neighboring farmer",
        defenseExam: [.direct("How do you know the farm?", "\"I farm next door. I have known the owner for years and I know the barn.\""), .direct("Do you know {D}?", "\"Yes. {D} came to work there last spring, and we talk at the fence line.\""), .direct("Do feed barns lose product?", "\"All the time. Rats, damp, and spills. A barn that size can lose a dozen sacks in a month without anyone doing anything wrong.\""), .direct("Did you see the defendant haul sacks?", "\"Yes, early in the morning. I thought it was spoiled feed going to a dump. I've seen farm hands do the same.\""), .direct("What is the value of spoiled feed?", "\"Nothing. Moldy feed can make animals sick. You throw it out.\""), .direct("Did you ever buy feed from the defendant?", "\"No. I buy mine from the store.\""), .cross("Did you look at the sacks in the truck?", "\"No. I saw them from the road. I could not tell what was in them.\""), .cross("Could the sacks have been good feed?", "\"They could. I can't say. They looked like regular sacks.\""), .cross("How early did you see the defendant?", "\"Around dawn, quarter to six. I'm up early with my own animals.\""), .cross("How many times did you see this?", "\"Two or three times over a few weeks. I did not keep count.\""), .cross("Did you tell the owner?", "\"Eventually, yes. I mentioned it after the owner asked whether I'd seen anything.\"")],
        theory: ("{D} took feed sacks from the barn.", "{D} threw out leftover scraps."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} sold the feed at a flea market.", "{DL} logged some spoilage that was real."),
        defendant: [.direct("What was your job on the farm?", "\"I was the hired hand in charge of the feed barn. I opened up at dawn, fed the herd, and kept the logs.\""), .direct("What were you loading into the truck at 5:40 a.m.?", "\"Leftover scraps and some spoiled feed that had gone moldy or gotten wet. I was taking it to dump, as I'd been told to do.\""), .direct("How did you log the waste?", "\"In the waste log. I signed entries for spoiled feed, with dates. Some of the spoilage was real.\""), .direct("Where did you dump the scraps?", "\"At a field edge off the county road. It's where the farm throws things that cannot be fed.\""), .direct("Why did the feed count not match?", "\"Rats, wet feed, and delivery mistakes. I did not keep a clean count, and I am not a bookkeeper.\""), .direct("Did you sell any feed?", "\"I'm not going to talk about anything I did not do. I took out scraps, and I recorded them.\""), .cross("You loaded six sacks, didn't you?", "\"Six sacks on that morning, yes. They weren't all scraps, to be honest. Some were half full.\""), .cross("The delivery slips show forty a week, don't they?", "\"Yes. I did not order them. The owner or the feed store set that.\""), .cross("Twenty-two sacks are $620, aren't they?", "\"If that is the price, yes. I did not take that many for any purpose.\""), .cross("You had a key to the barn, didn't you?", "\"Yes. So did the owner.\""), .cross("You didn't dump them in the barn's own trash, did you?", "\"No, I drove them off. The barn bin is small.\"")],
        openings: ("{V}'s feed bill climbed while the herd stayed the same size, and a count showed twenty-two sacks missing over three weeks, worth $620. A neighbor saw {D}'s truck leave the barn at dawn with sacks in the bed, and the barn camera shows {D} loading six at 5:40 a.m.", "Feed barns lose product to rats, damp and spills, and {D} signed spoilage entries in the waste log. The sacks in the truck were scraps headed for a dump. You will hear a neighboring farmer explain how common that is."),
        closings: ("Forty sacks a week delivered for a herd that eats twenty-eight, twenty-two sacks gone, and six of them on camera going into {D}'s truck at dawn. The log entries cannot explain that. {D} had the key.", "Rats, damp, and mold take feed from every barn, and no one ever measured the loss at this one. The neighbor's own feed purchases were never checked against the missing sacks. The State has not proved that {D} stole anything."),
        timeline: [(-21, "The feed bills begin to rise."), (0, "{V} counts the sacks."), (0, "{V} reviews the barn camera."), (3, "{V} reports the loss to the Sheriff's Office.")],
        identified: "The barn key and the neighbor's report point to {D}.",
        notDone: ["The barn's spoilage and rat losses were never measured.", "The neighbor's feed purchase was never matched to the missing sacks."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let catchBasinCoverV1 = SmallCases.make(
        key: "story.catchBasinCover",
        category: .property,
        headlines: ["Copper Wire Pulled From Ball Field Light Poles and Sold to Scrap Yard", "Scrap Yard Slip Shows Copper Sold Two Days After Poles Went Dark"],
        law: "misdLarceny",
        spec: "Stole copper wire valued at $900 belonging to {V}, a town, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "Four ball field light poles went dark on {DATE} after about 300 feet of copper wire was pulled from the conduit. Two days later a scrap yard bought 38 pounds of insulated copper from {D}. The yard slip carries {D}'s ID and the wire's stripped insulation. The town valued the loss at $900. {D} says the wire came from a junked house.",
        state: [E(.document, 3, "Scrap Slip", "38 pounds of copper bought from {D} with {D}'s ID."), E(.physical, 3, "Conduit", "Four conduits cut open and the wire gone."), E(.document, 2, "Town Estimate", "$900 to replace the wire and repair the conduit."), E(.video, 2, "Scrap Yard Camera", "{D} unloads a sack at the scale.")],
        defense: [E(.statement, 1, "Junk House", "{DL} says the wire came from a junked house."), E(.document, 1, "Salvage Note", "A note from a demolition crew about wire left at the site.")],
        role: "Town public works supervisor",
        exam: [.direct("What is your job with the town?", "\"I'm the public works supervisor. I oversee the ball fields, lights, and the crews that maintain them.\""), .direct("What happened on {DATE}?", "\"Four light poles at the ball field went dark. When my crew checked, about 300 feet of copper wire had been pulled out of the conduit overnight.\""), .direct("How was the conduit damaged?", "\"Four conduits had been cut open at the base of each pole. The wire was gone, and the cuts were clean, like a bolt cutter or a hacksaw.\""), .direct("How was {D} connected?", "\"Two days later, a local scrap yard bought 38 pounds of insulated copper from {D}. The scrap slip carries {D.his} ID and notes stripped insulation.\""), .direct("What did the yard's camera show?", "\"It shows {DL} unloading a sack at the scale. The yard sent us the video after we traced the wire.\""), .direct("What did the loss cost the town?", "\"$900 for new wire and the conduit repairs. We had to bring in an electrician.\""), .cross("Was the town's wire marked in any way?", "\"No. It was ordinary building wire. We don't stamp it, and I can't prove that this copper is ours by marking.\""), .cross("How much copper was in the 300 feet?", "\"I estimate roughly forty pounds with insulation. That is close to the weight on the slip.\""), .cross("Did anyone see the defendant at the field?", "\"No one. The field is empty after dark, and we have no camera there.\""), .cross("Was the wire the same gauge as what the defendant sold?", "\"I did not compare gauges. I did not inspect what the yard bought.\""), .cross("Are there other places where wire like that is sold or scrapped?", "\"Sure. Any demolition or rewiring job produces it. I can't rule out that {D.he} got it elsewhere.\"")],
        defenseRole: "Demolition worker",
        defenseExam: [.direct("What do you do?", "\"I work on a demolition crew. We take houses down and haul the debris.\""), .direct("Did you work on a house recently?", "\"Yes, a small one on the east side the week of {DATE}. We pulled out all the old wiring before the walls came down.\""), .direct("What happens to the wire?", "\"Usually we throw it in a pile for scrap or let the owner decide. Sometimes people ask for it.\""), .direct("Did you meet {D}?", "\"{D} came by on the second day and asked about the wire. I told {DF} it was going in the dumpster and {D.he} could take some.\""), .direct("What kind of wire was it?", "\"A mix of old household copper. Some was a different gauge than modern wiring.\""), .direct("Did you write anything down?", "\"I left a note about wire left at the site for the owner. It does not name {DF}.\""), .cross("Did you see the defendant take the wire?", "\"I saw {DF} put a sack in a truck. I did not see how much.\""), .cross("Did you inventory the copper?", "\"No. We do not count scrap. It goes in the dumpster.\""), .cross("Do you know what the town's wire looks like?", "\"No. I have never seen it.\""), .cross("How well do you know the defendant?", "\"Not well. We met that week.\""), .cross("Could the wire have been from another source?", "\"I can't say. I know where mine came from.\"")],
        theory: ("{D} stripped the wire and sold it.", "{D} sold wire from a junked house."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had cut the conduits with a bolt cutter at night.", "The wire at the junked house was a different gauge and {DL} bought a spool to mix."),
        defendant: [.direct("Where did you get the copper you sold?", "\"From a house that was being demolished. A friend in the trade told me the crew was throwing out old wire, and I picked up some.\""), .direct("How much did you take?", "\"About 38 pounds, mostly insulated. I stripped the insulation off some to get a better price.\""), .direct("Why did you sell it at the scrap yard?", "\"I needed the money. I was doing odd jobs, and the check was about a hundred dollars.\""), .direct("Did you take wire from the ball field?", "\"No. I did not touch the field. I have been to that field to watch games, but I never went near the poles.\""), .direct("What happened when you were asked about it?", "\"I told them where I got it and gave them the name of the demolition crew.\""), .direct("What would you say to the town?", "\"That I'm sorry the lights went out. I did not do it.\""), .cross("You sold 38 pounds of copper two days after the lights went out, didn't you?", "\"Yes. The timing is bad. I'm just telling you where it came from.\""), .cross("You stripped the insulation yourself, didn't you?", "\"I stripped some. It's how scrap yards pay more. Plenty of people do it.\""), .cross("You can't give an inventory of what that house had, can you?", "\"No. I didn't take stock. I took a sack of wire from a pile.\""), .cross("You own bolt cutters, don't you?", "\"Most people who do odd jobs do. I did not use them on the town's conduit.\""), .cross("You've been to the ball field, haven't you?", "\"Yes, to watch games. That's not unusual.\"")],
        openings: ("Four ball field light poles went dark after roughly 300 feet of copper wire was cut out of the conduits. Two days later, a scrap yard bought 38 pounds of stripped copper from {D}, and the slip carries {D}'s ID. The town's loss is $900.", "{D} sold wire that came from a junked house, and a demolition worker will confirm that crew was tossing old copper. The town's wire carries no marks, and no one saw {D} at the field. The State must tie this particular copper to these poles."),
        closings: ("Wire pulled on a night when no one was watching, and 38 pounds of insulated copper at a scrap yard two days later under {D}'s name. The conduits were cut open and the camera shows the sack. {D}'s story cannot be checked.", "The town never marked its wire, never inventoried the demolition site's copper, and no one saw anyone at the field. Scrap copper comes from many places. A suspicious timing is not proof of theft."),
        timeline: [(0, "Night: the wire is pulled."), (0, "Morning: the poles go dark."), (2, "{D} sells the copper."), (4, "The town traces the wire to the slip.")],
        identified: "The scrap slip names {D}.",
        notDone: ["The demolition site's copper was never inventoried.", "The town's wire was never stamped or marked."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let streetSignTheftV1 = SmallCases.make(
        key: "story.streetSignTheft",
        category: .property,
        headlines: ["Bronze Town Plaque Pried From Monument and Found in Garage", "Scrap Dealer Photo Matches Missing Plaque"],
        law: "misdLarceny",
        spec: "Stole a bronze plaque valued at $1,100 belonging to {V}, a town, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "A bronze plaque honoring local veterans was pried from a stone monument on {DATE}. A scrap dealer reported a customer who offered a similar plaque for cash and a photo of the plaque matched the town's records. Deputies found the plaque in {D}'s garage with pry marks on the back. The plaque was valued at $1,100. {D} says {D.he} found it in a ditch.",
        state: [E(.physical, 3, "Plaque", "The bronze plaque found in {D}'s garage with pry marks."), E(.digital, 3, "Scrap Dealer Photo", "A photo of the plaque sent by {D} to a scrap dealer."), E(.document, 2, "Town Records", "A purchase record and photo of the plaque."), E(.statement, 2, "Public Works Supervisor", "Found the monument bare and the screws sheared.")],
        defense: [E(.statement, 1, "Found in a Ditch", "{DL} says {D.he} found the plaque in a ditch."), E(.document, 1, "Ditch Photo", "A photo of a ditch on a county road dated the week before.")],
        role: "Public works supervisor",
        exam: [.direct("What did you find at the monument?", "\"A bronze veterans' plaque had been pried off, with the screws sheared. The monument stood bare.\""), .direct("Where was the plaque recovered?", "\"In {D}'s garage, with pry marks on the back. It was valued at $1,100.\""), .direct("What was the plaque?", "\"A bronze plaque with the names of veterans from the county, bolted to a stone monument in the town square. It was dedicated forty years ago.\""), .direct("What did you find that morning?", "\"The monument was bare, the screws sheared off, and pry marks on the stone. I called the Sheriff's Office.\""), .direct("How did you get the plaque back?", "\"A scrap dealer reported a customer who offered a similar plaque for cash. The dealer's photo matched our records, and deputies found it in {D.his} garage.\""), .direct("What did the monument look like when you found it bare?", "\"Four sheared screw holes and clean marks where the plaque had sat. Pry marks were on the stone, and the veterans' names were gone from the site.\""), .cross("{D} says {D.he} found it in a ditch, doesn't {D.he}?", "\"Yes. A veterans' post member says the plaque had been loose for a year.\""), .cross("Did the town repair the plaque?", "\"No. We did not. It sat loose for a year.\""), .cross("Did anyone see the defendant take the plaque?", "\"No. No one saw it taken.\""), .cross("The plaque could have fallen in a ditch, couldn't it?", "\"I cannot see how. The screws were cut and there were fresh pry marks.\""), .cross("{D} sent the photo openly to the dealer, didn't {D.he}?", "\"Yes, from {D.his} own number. That helped us find it.\"")],
        defenseRole: "Veterans' post member",
        defenseExam: [.direct("Was the plaque loose before it was taken?", "\"For a year. It was loose, and I reported it to the town more than once.\""), .direct("Did the town repair it after you reported it?", "\"No. Nothing was done. It hung loose for the whole year.\""), .direct("Did {D} visit the monument?", "\"Sometimes. {D} came to events, and I saw {DF} looking at the plaque.\""), .direct("How do you know the defendant?", "\"We belong to the same veterans' post. I have known {DF} for years.\""), .direct("What did the defendant say about the plaque?", "\"That {D.he} found it in a ditch and did not know what it was. {D.He} seemed shocked to hear it was the monument's.\""), .direct("Why does the plaque matter to the post?", "\"It honors local veterans, many of whom were friends. We were heartbroken when it was taken.\""), .cross("Did the defendant ask about the plaque?", "\"Once. {DF} asked why it was loose, and I told {DF} the town knew about it.\""), .cross("Would a loose plaque come off with pry marks?", "\"Pry marks suggest it was pried. A loose plaque could also be pried by someone.\""), .cross("Did the defendant measure the screws?", "\"I heard that.\""), .cross("You do not know where {D} found it, do you?", "\"Only what {D.he} told me.\""), .cross("The plaque was bolted to the monument, wasn't it?", "\"Yes. It would not have fallen off by itself.\"")],
        theory: ("{D} pried off a plaque and kept it.", "{D} found the plaque in a ditch."),
        allocution: "\"It was a stupid decision and someone else paid for it.\"",
        truths: ("{DL} had measured the screws before taking it.", "{DL} had found a plaque in a ditch and never connected it to the monument."),
        defendant: [.direct("Did you take the veterans' plaque from the monument?", "\"No. I found a plaque in a ditch and did not connect it to the monument.\""), .direct("Why did you send a photo to a scrap dealer?", "\"I wanted to see what it was worth. I did not know it was from the monument.\""), .direct("Where did you keep the plaque?", "\"In my garage. I planned to find out who it belonged to.\""), .direct("Where did you find the plaque?", "\"In a ditch on a county road when I was walking my dog. It looked like scrap, and I took it home.\""), .direct("Why did you take it to a scrap dealer?", "\"I needed cash, and I thought it was a piece of scrap bronze. I did not know where it came from.\""), .direct("What did you do when deputies came?", "\"I showed them the plaque and told them where I had found it. I did not try to hide it.\""), .cross("Pry marks were on the back, weren't they?", "\"Yes. They were there when I found it.\""), .cross("You measured the screws before taking it, didn't you?", "\"I measured a plaque I found. I did not measure the monument.\""), .cross("A scrap dealer got a photo of the plaque from you. Isn't that selling it?", "\"I asked about value. I did not sell it.\""), .cross("The back had pry marks, didn't it?", "\"Yes. I did not think about what they meant.\""), .cross("You measured the screws, didn't you?", "\"Yes, because I wanted to see if it would fit something. I should not have taken it.\"")],
        openings: ("A bronze plaque honoring local veterans was pried from a stone monument. A scrap dealer reported a customer offering a similar plaque, and deputies found it in {D}'s garage with pry marks, valued at $1,100.", "The defense case is that the plaque had been loose for a year, that the town never repaired it, and that {D} found a plaque in a ditch."),
        closings: ("A veterans' plaque pried from its monument, photographed for a scrap dealer, and found in {D}'s garage with pry marks. It honored the town's veterans.", "A loose plaque, a ditch, and a person who did not connect the two. The State must prove {D} pried the plaque off the monument."),
        timeline: [(0, "The plaque is pried off."), (3, "{D} sends the photo to a scrap dealer."), (5, "The dealer calls the Sheriff's Office."), (6, "Deputies find the plaque in {D}'s garage.")],
        identified: "The scrap dealer's photo and the garage tie to {D}.",
        notDone: ["The monument's pry marks were never matched to a tool.", "The scrap dealer's cash log was never read."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let houseSitterV1 = SmallCases.make(
        key: "story.houseSitter",
        category: .property,
        headlines: ["Pet Sitter Photographs Herself Wearing Owner's Ring and Pawns Camera", "Doorbell Camera Shows Sitter Leaving With Camera Bag"],
        law: "misdLarceny",
        spec: "Stole a camera valued at $900 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} hired {D} to feed a cat and water plants for a week on {DATE}. When {V} returned, a camera and a lens from a closet shelf were missing. The doorbell camera showed {D} leaving on the fourth day with a bag that was not there on arrival. A pawn shop took in the same camera model from {D} on day five. {D} says {V} lent the camera for photos of the cat.",
        state: [E(.video, 3, "Doorbell Camera", "{D} leaves on day four with a camera bag that was not there on arrival."), E(.document, 3, "Pawn Ticket", "A camera and lens pawned by {D} for $280 on day five."), E(.document, 2, "Purchase Receipt", "The camera and lens cost {V} $900."), E(.statement, 2, "{V}", "Never lent the camera to anyone.")],
        defense: [E(.statement, 1, "Lent for Photos", "{DL} says {V} lent the camera for photos of the cat."), E(.document, 1, "Cat Photos", "A phone album of photos of the cat taken by {DL}.")],
        role: "Homeowner",
        exam: [.direct("What did you hire {D} to do?", "\"To feed my cat and water my plants for a week while I was away. {D} was recommended through a sitter app, and I gave {DL} a key.\""), .direct("What was on the closet shelf?", "\"A camera and a lens in a padded bag on the top shelf of the hall closet. I bought them together for $900 and kept the receipt.\""), .direct("What did you find when you came home?", "\"The shelf was empty. The cat and plants were fine, but the camera and lens were gone, and nothing else was disturbed.\""), .direct("What does your doorbell camera show?", "\"On day four, {D.he} leaves with a camera bag that was not there when {D.he} arrived on day one.\""), .direct("What did deputies learn?", "\"A pawn shop took in a camera and lens of the same model from {D.him} on day five. The ticket shows $280.\""), .direct("Did you ever lend the defendant the camera?", "\"No. I never lent it to {DL} or anyone, and I did not give permission for it to leave the house.\""), .cross("Did you text the defendant anything about the camera?", "\"I sent texts about the cat and the plants. I may have mentioned photos of the cat, but I did not offer the camera.\""), .cross("Did you check the closet before leaving on your trip?", "\"I did not look in the closet before I left. I assumed it was there as always.\""), .cross("Could someone else have had access to the house that week?", "\"Only {DL}, as far as I know. The doors were locked, and there was no sign of forced entry.\""), .cross("Are the pawned camera and yours the same serial?", "\"The pawn ticket lists the model and a serial that matches my receipt. I confirmed that with the deputy.\""), .cross("Did the defendant send you cat photos during the week?", "\"Yes, a few. They looked like they were taken on a phone. I did not see any from a real camera.\"")],
        defenseRole: "Fellow pet sitter",
        defenseExam: [.direct("How do you know {D}?", "\"We both pet sit for the same app. I've worked with {D} on a few jobs, and we trade tips.\""), .direct("What do you know about this job?", "\"{DF} told me about the cat and the owner's texts. {DF} said the owner mentioned taking photos of the cat.\""), .direct("Did you see the texts?", "\"{D.He} showed me one that said something about the camera bag being fine to use for the cat. I did not read the entire thread.\""), .direct("What kind of person is the defendant with animals?", "\"Great. {D.He} is patient, shows up on time, and sends owners lots of updates and photos.\""), .direct("Has the defendant ever had a complaint?", "\"Not that I know of. {D.his} reviews are good.\""), .direct("What did the defendant say after the pawn?", "\"{D.He} said it had been a bad decision made under money pressure. {D.He} was ashamed.\""), .cross("Were you at the house?", "\"No. I never went to the owner's house.\""), .cross("Did you see the camera bag?", "\"No. I only know of it from {D.him}.\""), .cross("Did you see the owner's text?", "\"I saw part of one that {D.he} showed me, on a phone, briefly.\""), .cross("Did the defendant pawn items from other homes?", "\"I have not heard that.\""), .cross("Do you know the date {D} pawned it?", "\"Only that it was a few days into the job.\"")],
        theory: ("{D} took a camera and pawned it.", "{V} lent the camera for photos."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had pawned items from other homes.", "{V} had texted {DL} that the camera bag could be used for cat photos."),
        defendant: [.direct("What did you do in the house?", "\"Fed the cat, watered the plants, brought in mail, and kept the place tidy. I was there twice a day.\""), .direct("Did you take the camera?", "\"I did take it out of the closet. {V} had texted that the camera bag could be used for cat photos, so I thought it was fine.\""), .direct("Why did you leave on day four with the bag?", "\"I wanted to take photos of the cat at my place with better light, and I planned to bring the camera back.\""), .direct("Why did you pawn the camera?", "\"I was short on rent, and I figured I could redeem it before {V} got home. I know that was wrong.\""), .direct("Did you plan to get it back?", "\"Yes. I planned to redeem it with my next paycheck. It did not happen in time.\""), .direct("What did you tell the deputy?", "\"That {V} had said I could use it for cat photos, and that I'd pawned it. I did not lie.\""), .cross("You pawned a camera that did not belong to you, didn't you?", "\"Yes. Whatever I thought I was allowed to do with it, I was not allowed to pawn it.\""), .cross("{V} says the camera was never lent, doesn't {V.he}?", "\"That is {V.his} account. I think the text was clear enough for me, but I should have asked.\""), .cross("You pawned it the day after you took it out, didn't you?", "\"Yes, on day five. I didn't hold on to it long.\""), .cross("$280 is far less than the camera cost, isn't it?", "\"Yes. It was a quick loan, and I knew the pawn price would be low.\""), .cross("You didn't tell {V} the camera was pawned, did you?", "\"No, I did not. I planned to fix it before anyone knew.\"")],
        openings: ("{V} hired {D} to feed a cat and water plants for a week. On day four the doorbell camera shows {D} leaving with a camera bag that was not there on arrival, and on day five a pawn shop took a matching camera and lens from {D} for $280. {V}'s receipt shows they cost $900.", "{V} told {D} by text that the camera bag could be used for cat photos, and {D} took that as permission. A fellow sitter will describe {D}'s work and the money trouble behind it. The pawn was wrong, but it was not a plot."),
        closings: ("A closet shelf emptied, a bag leaving on day four, and a pawn ticket the day after. {V} never lent the camera to anyone. {D} had the only key.", "A text about cat photos, and a sitter with an exemplary record, show how {D} came to hold the camera. The owner never checked the closet before the trip, and the pawn date was never compared with the stay. The State must prove {D} meant to deprive {V}."),
        timeline: [(0, "Day 1: {D} starts the job."), (0, "Day 4: {D} leaves with a camera bag."), (0, "Day 5: {D} pawns the camera."), (1, "{V} returns and finds the shelf empty.")],
        identified: "The doorbell camera identifies {D}.",
        notDone: ["The owner's closet was never checked for the lens before the trip.", "The pawn ticket's date was never compared with the stay."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let nannyPettyV1 = SmallCases.make(
        key: "story.nannyPetty",
        category: .property,
        headlines: ["Dog Walker Takes Cash From Entryway Jar Over Five Weeks", "Doorbell Camera Shows Hand in Jar During Weekday Walks"],
        law: "misdLarceny",
        spec: "Stole $280 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} kept a jar of cash for the dog walker's tip and for small errands on the entryway table. Over five weeks, bills went missing from the jar even after the tips were paid. On {DATE} the entryway camera recorded {D} take two $20 bills from the jar after a walk. {V} counted $280 missing over the period. {D} says the money was an advance on pay.",
        state: [E(.video, 3, "Entryway Camera", "{D} takes two twenties from the jar at 12:20 p.m."), E(.document, 2, "Jar Notes", "{V}'s notes of bills missing across five weeks."), E(.document, 2, "Payment Log", "Payments to {D} up to date each week."), E(.statement, 2, "{V}", "Never agreed to any advance.")],
        defense: [E(.statement, 1, "Advance on Pay", "{DL} says the money was an advance on pay."), E(.document, 1, "Text", "A text from {DL} asking about 'getting ahead on the month.'")],
        role: "Dog owner",
        exam: [.direct("What did you keep on your entryway table?", "\"A jar of cash for the dog walker's tip and small errands. Over five weeks, bills went missing even after tips were paid.\""), .direct("How much was missing?", "\"$280 over the period, according to my notes. {D} was paid up to date each week.\""), .direct("What was the jar for?", "\"I keep a jar on the entryway table with cash for the dog walker's tip and small errands. I count it every Friday.\""), .direct("What did you notice?", "\"Bills went missing even after the tips were paid, over about five weeks. I started keeping notes and totaled $280.\""), .direct("What does the entryway camera show?", "\"On one day at 12:20, {DL} takes two twenties from the jar after a walk and puts them in a pocket.\""), .direct("How did you first notice that money was missing from the jar?", "\"I always count the jar on Sundays. It came up short by a twenty one week, then another, and I started writing the totals down.\""), .cross("{D} says the money was an advance on pay, doesn't {D.he}?", "\"Yes. {D.He} says {D.he} asked about an advance. I never agreed to one.\""), .cross("Did the defendant ask you directly?", "\"I do not recall. {D.He} may have asked, and I did not answer.\""), .cross("Did you tell the defendant the jar was only for tips?", "\"I said it was for tips. That is what I told {D.him}.\""), .cross("{D} had been paid up to date, hadn't {D.he}?", "\"Yes. The payment log shows each week paid.\""), .cross("{D} texted about getting ahead on the month, didn't {D.he}?", "\"Yes. I did not answer, and I never agreed to an advance.\"")],
        defenseRole: "Neighbor dog walker",
        defenseExam: [.direct("Did {V} leave a jar for tips?", "\"Yes, on the entryway table. It was for tips and small errands for the dog.\""), .direct("Did {V} say to take from it?", "\"Only for tips. I was told to take a tip and nothing more.\""), .direct("Did {D} take more than a tip?", "\"I am not sure. I saw {D} take some money, but I do not know how much.\""), .direct("How do you know the defendant?", "\"I walk dogs in the same neighborhood and see {DF} most mornings. We chat on the sidewalk while the dogs sniff around, and we have for about a year.\""), .direct("What did the defendant say about money?", "\"That the month was tight and that an advance on pay would help a lot. {D.He} brought it up more than once while we walked.\""), .direct("How does the defendant treat the dogs?", "\"Very well. {DF} is reliable, never late, and the dogs run to the door when they see {DF} coming up the walk.\""), .cross("Did you ever take cash from the jar?", "\"No. I never took anything. I took only the tip I was given.\""), .cross("Did you see the defendant take $40 from the jar?", "\"No. I did not see it. I only know the arrangement.\""), .cross("Do you know whether {D} asked for an advance?", "\"I do not know.\""), .cross("You do not know what {V} agreed to, do you?", "\"No, I only heard {DF}'s side of it. I was never part of any conversation between {DF} and {V} about pay.\""), .cross("You did not see the defendant take anything from the jar, did you?", "\"No. I was not in the house, and I only learned about it when {D.he} told me what had happened.\"")],
        theory: ("{D} took cash from the jar.", "{D} took an advance on pay."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} had taken money on four earlier visits too.", "{DL} had asked about an advance but never got an answer."),
        defendant: [.direct("Did you take money from the jar?", "\"Yes. I took two twenties. I thought I was owed an advance on pay, since I had asked about one.\""), .direct("Did {V} agree to an advance?", "\"I asked and did not get an answer. I took silence as a yes. That was wrong.\""), .direct("Why did you take money on earlier visits?", "\"I took a little a few times. I was short on money, and I told myself I would square it.\""), .direct("What was your situation?", "\"I was short on rent that month and asked about getting an advance on pay. I never got an answer.\""), .direct("What did you take?", "\"Two twenties from the jar after a walk. I figured it was an advance, and I meant to settle it.\""), .direct("Did you take money before?", "\"A few times in earlier weeks, small amounts. I thought of it as the same arrangement.\""), .cross("$280 over five weeks went missing. Is that all from you?", "\"Some of it. I do not know about all of it.\""), .cross("You were paid up to date each week, weren't you?", "\"Yes. I know. I was short, and I made a bad choice.\""), .cross("You never told {V} you were taking from the jar, did you?", "\"No. I should have. I am ashamed.\""), .cross("Nobody told you it was fine, did they?", "\"No. I assumed, and that was wrong.\""), .cross("You never told {V} what you took, did you?", "\"No. I should have said something at the time.\"")],
        openings: ("{V} kept a jar of cash on an entryway table for the dog walker's tip, and over five weeks $280 went missing. On camera, {D} takes two $20 bills from the jar, though {D} was paid up to date each week.", "Jurors will hear that {D} had asked about an advance on pay and took the money believing it was owed, not to steal."),
        closings: ("A jar meant for tips, $280 gone over five weeks, and {D} on camera taking two twenties. {V} never agreed to any advance.", "A dog walker who asked about an advance and took silence as a yes. The State must prove {D} meant to steal, and a mistaken belief is not intent."),
        timeline: [(-35, "The first missing bills."), (0, "12:20 p.m.: {D} takes two twenties."), (1, "{V} reviews the camera."), (2, "{V} reports the theft.")],
        identified: "The entryway camera identifies {D}.",
        notDone: ["The jar's tips were never counted on a ledger.", "The earlier five weeks of footage were never reviewed."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let coachFeesV1 = SmallCases.make(
        key: "story.coachFees",
        category: .whiteCollar,
        headlines: ["Youth League Registrar Uses Tournament Entry Fees for Rent and Car Payment", "Bank Statement Shows League Account Drained Over Two Months"],
        law: "embezzlement",
        spec: "Embezzled $2,100 entrusted to {D} by {V}, a youth baseball league, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} served as registrar for a youth baseball league and collected tournament entry fees from families. Over two months before {DATE}, {D} moved $2,100 from the league account to a personal account for rent and a car payment. The league's board reviewed the statements and found the balance short. {D} says the money was a loan until a sponsor paid.",
        state: [E(.document, 3, "Bank Statements", "Transfers totaling $2,100 from the league account to an account in {D}'s name."), E(.document, 3, "Fee Ledger", "Entry fees collected from forty families recorded by {D}."), E(.statement, 2, "League President", "No loan was approved by the board."), E(.document, 2, "Personal Account Records", "Rent and a car payment cleared from the personal account the same days.")],
        defense: [E(.statement, 1, "Loan", "{DL} says the money was a loan until a sponsor paid."), E(.document, 1, "Sponsor Letter", "A letter promising a $2,500 sponsorship after the season.")],
        role: "League president",
        exam: [.direct("What is your role in the youth baseball league?", "\"I'm the league president. We run recreational teams and an annual tournament, and a registrar collects the entry fees.\""), .direct("Who was the registrar?", "\"{D}, who volunteered for that job. {D.He} collected fees from about forty families for the tournament and kept the ledger.\""), .direct("What did the board find?", "\"Reviewing the bank statements, we found the league balance short. Over two months, transfers totaling $2,100 had moved to an account in {D.his} name.\""), .direct("Did the board approve a loan?", "\"No. The board never voted on a loan, and there is nothing in the minutes. Nobody told me about one.\""), .direct("What did the personal account records show?", "\"Rent and a car payment cleared from {D.his} personal account on the same days as the transfers.\""), .direct("What did you do?", "\"I asked {D.him} about the shortfall two days after the board's review. About ten days later the league reported the shortage.\""), .cross("Did {D} say anything about a sponsor?", "\"Yes. {D.He} said a sponsor had pledged $2,500 after the season and that the money was a short-term loan.\""), .cross("Did you ever see a letter from the sponsor?", "\"I saw a letter later, promising $2,500 after the season. I did not contact the sponsor to confirm.\""), .cross("Did the defendant try to hide the transfers?", "\"The ledger showed the entry fees. I did not see the transfers there at first, but I can't say whether that was deliberate.\""), .cross("Have earlier boards approved loans to officers?", "\"I don't know. The old minutes were never checked, and I was not president then.\""), .cross("Did the defendant offer to repay?", "\"{D.He} said {D.he} would, as soon as the sponsor paid. Nothing was repaid before I reported it.\"")],
        defenseRole: "League treasurer",
        defenseExam: [.direct("What is your role in the league?", "\"I'm the treasurer. I work with the registrar and sign the deposits.\""), .direct("Do you know the sponsor?", "\"A local business pledged $2,500 for the season, in a letter. I saw the letter and thought it was real.\""), .direct("What did you know about the transfers?", "\"I learned about them after the board's review. I did not know they were happening before.\""), .direct("How did {D} react when asked?", "\"{D} said it was a loan and showed the sponsor letter. {D.He} looked scared and embarrassed.\""), .direct("Has the defendant been reliable?", "\"Yes. For two years {DF} ran registration well, never missed a deadline, and kept families informed.\""), .direct("Was there any record of the sponsor's payment?", "\"The sponsor paid late, after the report, and the league received the money.\""), .cross("Did you approve the transfers?", "\"No. I did not know about them. I'm not a signer on that account.\""), .cross("Did the defendant tell you about the loan?", "\"No. I heard about it after the board review.\""), .cross("Did the sponsor money cover the full amount?", "\"I believe so, but I did not handle the deposit.\""), .cross("Did the defendant ever pay back the money on {D.his} own?", "\"I don't know if {D.he} did. The sponsor's check covered it.\""), .cross("Would the board have approved a loan?", "\"Unlikely. We have never done that.\"")],
        theory: ("{D} moved league money to a personal account.", "{D} took a loan against a pledged sponsorship."),
        allocution: "\"I'm sorry to everyone I let down. I'll repay what I can.\"",
        truths: ("{DL} hid the transfers in the ledger with a false line.", "The sponsor did pledge money and {DL} meant to repay."),
        defendant: [.direct("Why did you move money out of the league account?", "\"I was behind on rent and had a car payment due. I expected a sponsor to pay $2,500 after the season.\""), .direct("Did you intend to keep the money?", "\"No. I meant it as a loan until the sponsor paid. I planned to put it back.\""), .direct("Did you tell anyone about the transfers?", "\"I did not tell the board. I should have asked first. I was ashamed to say I was short.\""), .direct("What did you do when the president asked?", "\"I told the president it was a loan against the sponsor's pledge. I showed the letter.\""), .direct("Did you track the transfers anywhere?", "\"I kept my own note. I did not make a clean line in the ledger, and I know that looks bad.\""), .direct("What would you say to the families?", "\"That I'm sorry. Their money was not mine to use, even for a short time.\""), .cross("You moved $2,100 over two months, didn't you?", "\"In several transfers, yes. The total came to that.\""), .cross("Rent and a car payment cleared the same days, didn't they?", "\"Yes. That is what I used it for.\""), .cross("The board never approved a loan, did it?", "\"No, it did not. I did not ask.\""), .cross("The sponsor had not paid when you reported the shortage, had it?", "\"Not yet. The letter promised money after the season.\""), .cross("You did not repay a dollar before the board reviewed the account, did you?", "\"No. I had not repaid anything. I was waiting for the sponsor.\"")],
        openings: ("{D} was the league registrar and collected tournament fees from forty families. Over two months, $2,100 moved from the league account to {D}'s personal account, and rent and a car payment cleared on the same days. The board never approved a loan.", "{D} took a short-term loan against a pledged sponsorship of $2,500 and did not tell the board. A letter from the sponsor survives, and the treasurer will tell you the sponsor eventually paid. {D} was wrong not to ask, but did not intend to steal."),
        closings: ("$2,100 in transfers, rent and a car payment on the same days, and no board vote. The registrar was entrusted with forty families' money. A loan nobody approved is not a loan.", "A pledge letter for $2,500 and a sponsor that paid explain the plan to repay. The sponsor was never asked whether payment was coming, and the board minutes were never checked for earlier loans. The State must prove {D} intended to keep the money."),
        timeline: [(-60, "The transfers begin."), (0, "The board reviews the account."), (2, "The president asks {D} about the shortfall."), (10, "The league reports the shortage.")],
        identified: "The bank statements name {D}.",
        notDone: ["The sponsor was never asked whether payment was coming.", "The board minutes were never checked for earlier loans."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let campusBikeV1 = SmallCases.make(
        key: "story.campusBike",
        category: .property,
        headlines: ["Golf Clubs Taken From Club Storage Rack and Listed Online for Half Price", "Serial Numbers on Listing Match Member's Receipt"],
        law: "misdLarceny",
        spec: "Stole golf clubs valued at $1,600 belonging to {V}, a club member, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} left a set of golf clubs in the member storage rack at a country club on {DATE}. By the next morning the bag was gone and a listing for the same set appeared on a marketplace page for $800 under {D}'s account. The club's inventory sheet shows {D}, a locker attendant, worked that night. The serial numbers matched {V}'s receipt. {D} says {D.he} bought the set at a yard sale.",
        state: [E(.digital, 3, "Marketplace Listing", "A club set listed for $800 under {D}'s account with serials visible."), E(.document, 3, "Purchase Receipt", "{V}'s receipt for the set with serial numbers."), E(.document, 2, "Shift Sheet", "{D} was the only attendant on the night shift."), E(.video, 2, "Storage Room Camera", "A person in a staff vest carries a bag out at 11:40 p.m.")],
        defense: [E(.statement, 1, "Yard Sale", "{DL} says the set was bought at a yard sale for $100."), E(.document, 1, "Yard Sale Ad", "A weekend yard sale ad that listed golf equipment.")],
        role: "Club member",
        exam: [.direct("Where did you leave your golf clubs on {DATE}?", "\"In the member storage rack at the country club, in a black bag with my name tag. I put them there in the evening after a round.\""), .direct("What did you find the next morning?", "\"The rack was empty where my bag had been. I checked the pro shop and the locker room, and no one had moved them.\""), .direct("How did you learn who had them?", "\"Two days later I saw a listing on a marketplace page for the same set of clubs at $800, under {D}'s account.\""), .direct("How did you confirm they were yours?", "\"The listing photos showed the serial numbers on the irons, and they matched my purchase receipt. I also recognized a ding on the driver.\""), .direct("Who is {D}?", "\"A locker attendant at the club. The shift sheet shows {DL} was the only attendant on the night shift that evening.\""), .direct("What did the camera show?", "\"A person in a staff vest carrying a bag out of the storage room at 11:40 p.m. I recognized my bag by its shape.\""), .cross("Could you see the person's face on the video?", "\"Not clearly. The person wore a vest and a cap. It was the angle and the light.\""), .cross("Did you see the defendant take the bag?", "\"No. I went home that evening and only learned about it the next day.\""), .cross("Did other staff have access to the rack?", "\"The pro shop staff and the manager have keys to the storage room. I can't say who else walked through.\""), .cross("Did the defendant say anything when you asked about the listing?", "\"{D.He} said {D.he} had bought the set at a yard sale for $100. I did not accept that.\""), .cross("Were the clubs ever recovered?", "\"The deputies found a set in the trunk of {D.his} car. I confirmed the serial numbers matched mine.\"")],
        defenseRole: "Yard sale organizer",
        defenseExam: [.direct("What is your connection to this case?", "\"I organized a neighborhood yard sale the weekend before {DATE}. There were about a dozen tables in driveways.\""), .direct("Was golf equipment sold?", "\"Yes, a few tables had sports gear, and an ad I posted listed golf clubs among the items.\""), .direct("Did {D} come to the sale?", "\"I recall a person buying a set of clubs early on Saturday. I can't swear it was {D}, but the description fits.\""), .direct("Who sold the clubs?", "\"I'm not sure. Several households were selling, and I only organized. I did not keep track of each table.\""), .direct("Did anyone keep records?", "\"No. It was cash, informal, and nobody wrote down names.\""), .direct("Did you see the ad?", "\"I wrote it. It said golf equipment and other sports items, but it did not name specific sellers.\""), .cross("Do you know who had the clubs?", "\"No. I could not name the seller.\""), .cross("Do you remember the serial numbers?", "\"No. I never looked at them.\""), .cross("Did the defendant tell you about the clubs?", "\"No. News of the theft reached me days afterward.\""), .cross("Was the sale on the weekend before the theft?", "\"Yes, the weekend before. I remember because of the weather.\""), .cross("Did you know the defendant before that?", "\"I knew {DF} slightly. We'd met at the club a few times.\"")],
        theory: ("{D} took a member's clubs and sold them.", "{D} bought a set at a yard sale."),
        allocution: "\"I wasn't thinking about the person on the other end. I am now.\"",
        truths: ("{DL} had the set in a trunk when deputies arrived.", "The yard sale was real but its seller was never found."),
        defendant: [.direct("What is your job at the club?", "\"I'm a locker attendant. I handle towels, clean the locker room, and help members with storage.\""), .direct("Where did you get the clubs?", "\"From a yard sale last weekend, a few streets over. I paid $100 for the set and thought it was a good deal.\""), .direct("Why did you list them for $800?", "\"That is what a set like that goes for used. I wanted to flip them for a profit.\""), .direct("Did you take a bag from the storage room?", "\"I took a bag out of the storage room that night, but it was a staff bag I was returning. It was not a member's set.\""), .direct("What did you tell the deputies?", "\"That I bought the clubs at a yard sale and had the ad for it. I let them look in my trunk.\""), .direct("Did you recognize the serials?", "\"I did not check them. I didn't think a yard sale set could be a member's.\""), .cross("You were the only attendant on that night shift, weren't you?", "\"Yes. It's a quiet shift. That's why I'm the only one.\""), .cross("The clubs were in your trunk when deputies came, weren't they?", "\"Yes. I hadn't sold them yet.\""), .cross("You can't name the person who ran the yard sale, can you?", "\"No. It was a table in a driveway, and I paid cash. I didn't write down a name.\""), .cross("A person in a staff vest carried a bag out at 11:40, didn't they?", "\"That could be me carrying the staff bag. I told you it was a different bag.\""), .cross("$100 for an $800 set should have raised a flag, shouldn't it?", "\"In hindsight, yes. At the time I thought I'd found a bargain.\"")],
        openings: ("A member's golf clubs disappeared from the club's storage rack overnight and, two days later, the same set appeared for sale at $800 under {D}'s account. The serial numbers match {V}'s receipt, and {D} was the only attendant on that shift. A camera shows a person in a staff vest carrying a bag out at 11:40.", "{D} says the clubs came from a yard sale for $100, and an organizer will confirm that a sale with golf equipment took place. The video never shows a face. The State must prove {D} took the clubs from the rack."),
        closings: ("A member's clubs vanish on {D}'s shift, and the same serial numbers turn up in {D}'s listing and trunk. The vest on the camera fits {D}'s job. The price of $100 for an $800 set speaks for itself.", "The video shows a vest and a cap, not a face. A yard sale really took place, and its seller was never found. The organizer was never interviewed by deputies. Suspicion about a locker attendant is not proof."),
        timeline: [(0, "Evening: {V} leaves the clubs in the rack."), (0, "11:40 p.m.: a bag is carried out."), (1, "{V} finds the rack empty."), (2, "{V} sees the marketplace listing.")],
        identified: "The marketplace account is {D}'s.",
        notDone: ["The yard sale organizer was never interviewed.", "The club's rack camera was never reviewed for earlier nights."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let phoneWaitressV1 = SmallCases.make(
        key: "story.phoneWaitress",
        category: .property,
        headlines: ["Phone Left on Gym Treadmill Console Disappears During Workout", "Locator App Shows Phone Moving to Parking Lot"],
        law: "misdLarceny",
        spec: "Stole a phone valued at $750 belonging to {V}, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{V} left a phone on a treadmill console at a gym at 6:10 p.m. on {DATE} and walked to the water fountain. At 6:12 p.m., {D} picked up the phone and walked toward the locker room. A locator app showed the phone moving to the parking lot at 6:25 p.m. and then to {D}'s address that night. The phone was worth $750. {D} says {D.he} meant to take it to the front desk.",
        state: [E(.video, 3, "Gym Camera", "{D} picks up the phone at 6:12 p.m. and walks toward the locker room."), E(.digital, 3, "Locator App", "The phone moves to the parking lot at 6:25 p.m. and to {D}'s address that night."), E(.document, 2, "Purchase Receipt", "The phone cost {V} $750."), E(.statement, 2, "Front Desk Attendant", "No lost phone was turned in that evening.")],
        defense: [E(.statement, 1, "Meant to Turn In", "{DL} says {D.he} meant to take the phone to the front desk."), E(.document, 1, "Gym Rules", "A posted rule asking members to turn in lost items.")],
        role: "Gym member",
        exam: [.direct("What did your locator app show?", "\"The phone moving to the parking lot at 6:25 and then to {D}'s address that night. It was worth $750.\""), .direct("What happened with your phone?", "\"I left it on a treadmill console and walked to the water fountain. When I came back two minutes later, it was gone.\""), .direct("What does the gym camera show?", "\"At 6:12, {D.he} picks up the phone and walks toward the locker room. {D.He} does not go to the front desk.\""), .direct("How was the phone tracked?", "\"The locator showed it in the parking lot at 6:25 and at {D.his} address that night. It was off for part of the time.\""), .direct("What did you do when you realized the phone was gone from the console?", "\"I looked at the floor, the next machine and the fountain, then asked the front desk. Nobody had turned a phone in.\""), .direct("How did you follow the phone after it left the gym?", "\"I used a locator app on my tablet. It showed the phone moving to the lot, then across town to a house where it stayed all night.\""), .cross("{D} says {D.he} meant to take it to the front desk, doesn't {D.he}?", "\"Yes. {D.He} walked toward the front desk at first, I understand.\""), .cross("Did the desk have a lost box?", "\"Yes. It does. No lost phone was turned in that evening.\""), .cross("Did anyone see the defendant leave?", "\"The camera shows the parking lot afterward.\""), .cross("The front desk is close to the treadmills, isn't it?", "\"Yes, about thirty feet. {D.He} walked past it.\""), .cross("{D} may have meant to turn it in, mightn't {D.he}?", "\"I cannot say. No phone was turned in that evening.\"")],
        defenseRole: "Gym front desk worker",
        defenseExam: [.direct("Do phones get left on consoles at the gym?", "\"Daily. Members leave phones on treadmills and on benches all the time, and we turn in many of them.\""), .direct("Did {D} turn the phone in at your desk?", "\"No. {D} never turned in a phone that evening. No phone came to the desk.\""), .direct("Does your desk keep a lost box?", "\"Yes. Anything left behind goes into the lost box behind the desk, and members can claim it later.\""), .direct("What is your job at the gym?", "\"I work the front desk. I handle check-ins and lost items.\""), .direct("What is the policy on lost items?", "\"Members should turn them in to the desk. We log each item and hold it for thirty days.\""), .direct("Was a phone turned in that evening?", "\"No. Nothing came in that night.\""), .cross("Did the defendant visit the desk that evening?", "\"No. I did not see {D.him} at the desk at any time that evening.\""), .cross("Did you ask the defendant about the phone?", "\"No. I did not know a phone was missing until the owner reported it.\""), .cross("How long do you keep items in the lost box?", "\"About thirty days. We try to return everything.\""), .cross("You did not see the defendant with a phone, did you?", "\"No. I was helping a member.\""), .cross("The desk is near the treadmills, isn't it?", "\"Yes. A person walking to the locker room passes it.\"")],
        theory: ("{D} picked up a phone and kept it.", "{D} meant to turn it in."),
        allocution: "\"I knew it wasn't mine. I'll pay it back.\"",
        truths: ("{DL} turned the phone off in the locker room.", "{DL} did walk toward the front desk and was distracted."),
        defendant: [.direct("Did you take {V}'s phone?", "\"I picked it up to take it to the front desk. I got distracted and walked out with it.\""), .direct("Why did you turn it off in the locker room?", "\"It was ringing, and I wanted it quiet. I planned to turn it in after my workout.\""), .direct("What did you do with the phone afterward?", "\"I took it home. I told myself I would drop it off. I did not.\""), .direct("Why did you pick up the phone?", "\"I saw it lying on the console and picked it up to take to the front desk. A friend called to me, and I got distracted.\""), .direct("Why did you turn it off?", "\"It buzzed with calls in the locker room, and I silenced it. I meant to give it to the desk after changing.\""), .direct("What happened after that?", "\"I left with it in my bag and forgot until I got home. I intended to bring it back the next day.\""), .cross("The locator shows the phone in your parking lot, then at your address, doesn't it?", "\"Yes. I did not turn it in. That was a mistake.\""), .cross("You walked toward the locker room, not the front desk, didn't you?", "\"I walked toward the desk first and then changed direction. I got distracted.\""), .cross("$750 is a lot to keep for a day. Why not return it the next morning?", "\"I was embarrassed. I let it sit.\""), .cross("You walked right past the front desk, didn't you?", "\"Yes, because I was going to the locker room first. It was a mistake.\""), .cross("The phone was at your address that night, wasn't it?", "\"Yes. I did not call the gym about it.\"")],
        openings: ("{V} left a $750 phone on a gym treadmill console and walked to the water fountain. At 6:12, {D} picked it up and walked toward the locker room, and the phone later pinged from the parking lot and from {D}'s address.", "The defense will present evidence that {D} meant to take the phone to the front desk, got distracted in the locker room, and never meant to keep it for good."),
        closings: ("A phone picked up on camera, carried toward a locker room, then to the parking lot and to {D}'s home. It never reached the lost box at the desk.", "A person who picked up a phone to turn it in and forgot. The State must prove {D} meant to keep it."),
        timeline: [(0, "6:10 p.m.: {V} leaves the phone."), (0, "6:12 p.m.: {D} picks it up."), (0, "6:25 p.m.: the phone reaches the lot."), (1, "The locator shows {D}'s address.")],
        identified: "The gym camera identifies {D}.",
        notDone: ["The phone's lock screen was never checked for a message.", "The locker room entrance log was never pulled."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let glovesShopliftV1 = SmallCases.make(
        key: "story.glovesShoplift",
        category: .property,
        headlines: ["Customer Slips Out of Tractor Supply Store in New Rain Gear", "Gate Camera Shows Rain Jacket and Boots Worn Out"],
        law: "larcenyMerchant",
        spec: "Took rain gear valued at $240 from {V}, a farm supply store, without paying, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} walked into a farm supply store at 3 p.m. on {DATE}, took a rain jacket and boots from a display and put them on in the aisle. {D} left through the garden gate in them at 3:20 p.m. The old coat and shoes were left in a pile. The items cost $240. {D} says it was raining and {D.he} meant to pay at the register.",
        state: [E(.video, 3, "Gate Camera", "{D} walks out the garden gate in the new jacket and boots at 3:20 p.m."), E(.physical, 2, "Old Clothes", "A worn coat and shoes in a pile on the aisle floor."), E(.document, 2, "Price Tags", "Price tags for $240 found cut off on the aisle floor."), E(.statement, 2, "Store Employee", "Saw {D} put on the gear and lost sight of {D.him}.")],
        defense: [E(.statement, 1, "Raining", "{DL} says it was raining and {D.he} meant to pay."), E(.document, 1, "Weather Record", "A heavy downpour at 3 p.m. that afternoon.")],
        role: "Store employee",
        exam: [.direct("What is your job at the store?", "\"I work the floor at a farm supply store. On {DATE} I was in the garden section when I noticed {D} in the apparel aisle.\""), .direct("What did you see {D} do?", "\"{DL} picked up a rain jacket and a pair of boots from a display, and put them on right there in the aisle. I didn't see a basket or a cart.\""), .direct("What happened to the defendant's own clothes?", "\"{DL} left a worn coat and shoes in a pile on the aisle floor. I found them after {DL} left.\""), .direct("What happened to the price tags?", "\"They were cut off. I found tags totaling $240 on the aisle floor near the pile.\""), .direct("How did the defendant leave?", "\"Through the garden gate at 3:20, in the new jacket and boots. I lost sight of {DL} when {DL} went around a rack.\""), .direct("What did you do?", "\"I checked the register, saw no sale, and found the old clothes. About ten minutes later, at 3:30, I reported it to my manager.\""), .cross("It was pouring rain at about three, wasn't it?", "\"Heavy rain. The garden section was getting soaked. I don't doubt the weather.\""), .cross("Did the defendant walk past a register on the way out?", "\"The garden gate is not near the registers. {D.He} did not have to pass one to reach it.\""), .cross("Did the defendant say anything to you?", "\"No. I did not speak to {D.him} at any point. {D.He} did not ask me about a price or a register.\""), .cross("Did you try to stop {D}?", "\"I started toward the gate, but {D.he} was already outside. I did not want to chase a customer into the rain.\""), .cross("Was the old coat ever claimed?", "\"No. It sat at the register for a few days. Nobody came back for it.\"")],
        defenseRole: "Store greeter",
        defenseExam: [.direct("What do you do at the store?", "\"I'm the greeter at the garden entrance. I hand out carts and say hello to customers who come through the garden gate.\""), .direct("What was the weather like?", "\"A downpour. People were running in from the lot, and the garden section was a puddle.\""), .direct("Did you see {D}?", "\"Yes, I recall {D} coming in wet from the garden side. {D.He} asked if the store sold rain gear.\""), .direct("What did you say?", "\"I pointed to the apparel aisle and said they would find jackets and boots there.\""), .direct("Did the defendant seem to be hiding anything?", "\"No. {D.He} was open about being drenched and cold.\""), .direct("Did you see the defendant leave?", "\"I saw {DF} walk back toward the garden gate in dry gear, and I assumed {DF} was going to the lot to get something.\""), .cross("Did you see the defendant pay?", "\"No. I did not watch the registers.\""), .cross("Did you see the defendant cut the tags?", "\"No. I never saw that.\""), .cross("Did you stop {D} at the gate?", "\"I'm a greeter. I do not stop people. It's not my job.\""), .cross("Was the gate supposed to be an exit?", "\"It's an entrance for garden customers. People leave through it too.\""), .cross("Did the defendant tell you what the plan was?", "\"No. I did not hear a plan.\"")],
        theory: ("{D} put on store gear and walked out.", "{D} meant to pay and it was raining."),
        allocution: "\"I'm ashamed of it, Your Honor. I want to make it right.\"",
        truths: ("{DL} had cut the tags in the aisle before leaving.", "{DL} was caught in the downpour and walked out in a hurry."),
        defendant: [.direct("Why did you go into the store?", "\"It started pouring while I was walking, and the farm store was the nearest place with an open door. I was soaked.\""), .direct("Why did you put on the jacket and boots?", "\"My old coat and shoes were drenched. I grabbed a dry jacket and boots from the display to wear while I shopped.\""), .direct("Did you plan to pay?", "\"Yes. I planned to take them to the register and pay once I'd finished looking. I thought I'd keep the tags and have them rung up.\""), .direct("Why did you cut the tags?", "\"The tags were sticking out and flapping, and the boots were hard to walk in with them attached. I snipped them with my keys.\""), .direct("Why did you leave through the garden gate?", "\"The rain let up and I was in a rush to get to my appointment. I walked out without thinking. I was not trying to hide.\""), .direct("What did you do afterward?", "\"I realized I had not paid and felt sick about it. I should have gone back.\""), .cross("You left your old coat in a pile and walked out, didn't you?", "\"I did. I meant to go back for it, but I never did.\""), .cross("You never went to the register, did you?", "\"No. I did not go to the register at all.\""), .cross("You cut off the tags, didn't you?", "\"Yes, with my keys. I know it looks like I was hiding the price.\""), .cross("The gate camera shows you leaving at 3:20, doesn't it?", "\"Yes. I walked straight out.\""), .cross("$240 is a lot to forget, isn't it?", "\"Yes. I was not thinking about the price. I was thinking about being dry.\"")],
        openings: ("{D} picked a rain jacket and boots from the display, put them on in the aisle, cut off the tags, left a pile of old clothes on the floor, and walked out the garden gate at 3:20. The gate camera shows it, and the gear costs $240. You will hear from the employee who saw {D} put it on.", "It was pouring, {D} was soaked, and {D} meant to pay at the register. A greeter at the garden entrance will tell you how drenched people were and how openly {D} behaved. The State must prove {D} intended to steal."),
        closings: ("The jacket and boots went on in the aisle, the tags came off, and the old clothes stayed on the floor. {D} walked out the garden gate and never visited a register. That is a theft of $240.", "{D} did everything in plain sight, in a downpour, and left the old clothes where staff would find them. A thief does not leave an identifiable pile behind. The old jacket was never located and the tags were never recovered."),
        timeline: [(0, "3 p.m.: {D} takes the gear."), (0, "3:10 p.m.: {D} puts it on in the aisle."), (0, "3:20 p.m.: {D} leaves."), (0, "3:30 p.m.: staff find the old clothes.")],
        identified: "The gate camera identifies {D}.",
        notDone: ["The old jacket was never located.", "The tags were never recovered from the jacket and boots."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

    static let bakerySkipV1 = SmallCases.make(
