        state: [E(.video, 3, "Deli Camera", "{D} lifts a wrapped platter from the pickup shelf at 11:40 a.m. and leaves."), E(.document, 3, "Order Slip", "The platter was taped with another customer's name and a paid receipt."), E(.document, 2, "Register Tape", "No sale to {D} that morning."), E(.statement, 2, "Deli Owner", "Never saw {D} in the shop before.")],
        defense: [E(.statement, 1, "Thought It Was Mine", "{DL} says {D.he} thought it was the platter {D.he} had ordered."), E(.document, 1, "Phone Order", "A phone order from {D}'s number for a platter for 1 p.m.")],
        role: "Deli owner",
        exam: [.direct("What do you own?", "\"A neighborhood deli. We do a lot of catering, and customers pick up wrapped platters from a shelf by the door.\""), .direct("What happened at 11:40 a.m. on {DATE}?", "\"{D} came in, picked a wrapped catering platter off the pickup shelf, and walked out. It never went past the register.\""), .direct("What was on that platter?", "\"Another customer's name, taped to the top, along with a receipt showing it was already paid. It was a $110 platter.\""), .direct("What happened at noon?", "\"The customer whose platter it was came in to pick it up and it was gone. We looked all over and could not find it.\""), .direct("How did you find out who took it?", "\"At 12:15 I reviewed our camera and saw {DL} lift the platter at 11:40 and leave. No sale to {DL} appears on the register tape.\""), .direct("Did you know {D}?", "\"No. I had never seen {DL} in the shop before.\""), .cross("Was the defendant's own order ready that day?", "\"I'm told {DL} placed a phone order for 1 p.m. that day. I did not take the call myself.\""), .cross("Was the shelf organized by customer?", "\"Not strictly. Platters go on one shelf in the order they're finished. I never separated them by customer.\""), .cross("Did the defendant ask anyone where the platter was?", "\"The camera shows {DL} walking straight to the shelf. It does not show {DL} speaking to anyone.\""), .cross("Did you call the defendant about the mix-up?", "\"I did not. I had {D.his} number on the order slip, but I reported the loss to the Sheriff's Office instead.\""), .cross("Could the defendant have read the label?", "\"The name was written in marker on a piece of tape. Anyone close would be able to read it.\"")],
        defenseRole: "Deli counter worker",
        defenseExam: [.direct("What do you do at the deli?", "\"I work the counter. I take orders, wrap platters, and put them on the pickup shelf.\""), .direct("Do you remember {D}'s order?", "\"Yes, a phone order for a platter for 1 p.m. I wrote it on a slip and had it ready on a lower shelf.\""), .direct("How are the platters arranged?", "\"All wrapped platters go on the pickup shelf by the door, with labels. The labels are small, and it's busy at lunch.\""), .direct("Was the shelf crowded?", "\"Very. We had several catering orders that morning, and platters were stacked in a row.\""), .direct("Did you see the defendant take the platter?", "\"I saw someone grab one, and I figured it was a customer picking up an order.\""), .direct("What did you do when you learned it was wrong?", "\"I told the owner right away that {D} had an order in too and was probably confused.\""), .cross("Did you say anything to the defendant?", "\"No. I was at the register helping another customer.\""), .cross("Did the platter have a name on it?", "\"Yes, on a piece of tape. It was not big.\""), .cross("Did you call the defendant?", "\"The owner did not ask me to, and I did not call.\""), .cross("Was the defendant's platter ready?", "\"Yes, it was sitting on a different shelf.\""), .cross("Do you think {D} meant to take it?", "\"I can't say. I know {D.he} had an order.\"")],
        theory: ("{D} took a labeled platter without paying.", "{D} took what {D.he} thought was {D.his} own order."),
        allocution: "\"I took what wasn't mine, and I'm sorry for it.\"",
        truths: ("{DL} had ordered nothing and read the name on the label.", "{DL}'s own order was ready on a different shelf."),
        defendant: [.direct("Why did you go to the deli?", "\"I had ordered a platter for a 1 p.m. meeting and wanted to pick it up early. I'd called in the order the day before.\""), .direct("What did you do when you got there?", "\"I went to the pickup shelf and saw a wrapped platter that looked like mine. I grabbed it and left.\""), .direct("Did you read the label?", "\"Not carefully. I assumed it was mine because it was the size I ordered, and the counter was busy.\""), .direct("Why didn't you stop at the register?", "\"I had already paid by phone, so I thought I did not need to. I figured it was just pickup.\""), .direct("When did you realize it was not yours?", "\"At my meeting, when I opened it and there was not the food I ordered. I called the deli but it was too late.\""), .direct("What did you do then?", "\"I drove back and tried to return it, but the deputies were already there. I explained what happened.\""), .cross("You didn't ask anyone at the counter, did you?", "\"No. I did not ask. It was busy and I assumed it was fine.\""), .cross("The platter had another customer's name on it, didn't it?", "\"I'm told it did. I did not read the name.\""), .cross("You walked straight to that platter, didn't you?", "\"I walked to the shelf and took the one that looked right. It was the wrong one.\""), .cross("Your own order was on a different shelf, wasn't it?", "\"That's what I learned later. It was ready, and I did not see it.\""), .cross("Nobody reviewed the shelf before you took it, did they?", "\"As far as I know, no. I did not check with the staff.\"")],
        openings: ("At 11:40 a.m., {D} lifted a wrapped catering platter from the deli's pickup shelf, a platter with another customer's name taped on top and a paid receipt, and walked out without stopping at the register. The deli camera shows it, and the platter was worth $110.", "{D} had ordered a platter by phone for a 1 p.m. meeting and went to pick it up early. A counter worker will tell you how crowded the shelf was and that {D}'s order was ready on a different shelf. {D} grabbed the wrong platter."),
        closings: ("A platter with someone else's name on it, a paid receipt, and a customer who walked out with it. The register shows no sale to {D}. The camera shows exactly what happened.", "{D} had a phone order for a platter that same day, and a counter worker confirms it. The shelf was not separated by customer and the deli never called {D} about the mix-up. A mistaken pickup is not a theft."),
        timeline: [(0, "11:40 a.m.: {D} takes the platter."), (0, "12 p.m.: the other customer arrives."), (0, "12:15 p.m.: the deli reviews the camera."), (1, "The deli reports the platter to the Sheriff's Office.")],
        identified: "The deli camera identifies {D}.",
        notDone: ["The pickup shelf was never separated by customer.", "The deli never called {DL} about the mix-up."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

