        state: [E(.physical, 3, "Counterfeit Bills", "Three counterfeit tens and four more found in {D}'s pocket."), E(.physical, 2, "Marker Test", "A marker test leaves black streaks on each bill."), E(.statement, 3, "Vendor", "Marked the first bill and called security."), E(.document, 2, "Security Report", "Security stopped {D} at 10 a.m. with four more bills.")],
        defense: [E(.statement, 1, "Change", "{DL} says {D.he} got the bills in change from a different stall."), E(.document, 1, "ATM Receipt", "An ATM receipt for $200 the day before.")],
        role: "Produce vendor",
        exam: [.direct("What do you sell at the farmers market?", "\"Vegetables and fruit, mostly tomatoes and peaches. I have a stand near the north entrance, and I work it by myself on Saturdays.\""), .direct("What happened at about 9:25 a.m. on {DATE}?", "\"A customer bought a small bag of peaches and paid with a ten-dollar bill. When I put it in the box, it felt wrong, smooth and a little waxy.\""), .direct("What did you do?", "\"I took out a marker and drew on the bill. It left a black streak, which tells you the paper is not real currency paper.\""), .direct("What did you do next?", "\"I called market security at 9:40. By then, I'd heard from two other vendors that they'd taken suspicious tens from the same customer.\""), .direct("What happened with security?", "\"They stopped {D} at 10 a.m. and found four more tens in {D.his} pocket. The security report lists the bills.\""), .direct("How many counterfeit bills were there?", "\"Three that the stalls had accepted, and four more in {D.his} pocket. All of them marked black under the pen.\""), .cross("Did you see {D} receive the bill from anyone?", "\"No. I only saw {DL} hand it to me. I can't tell you where {DL} got it.\""), .cross("Did the defendant try to run when security came?", "\"No. I wasn't there, but security told me {DL} stayed put and talked with them.\""), .cross("Are there serial numbers on the bills?", "\"Yes, but nobody traced them to a bank. I don't know if any of them match each other.\""), .cross("Did the marker test prove the bill was fake?", "\"It is a quick test, not a lab. A black streak is a strong sign, but it can sometimes be wrong.\""), .cross("Did you give the defendant change?", "\"I gave change for the peaches, yes. I handed back several dollars before I realized the bill was bad.\"")],
        defenseRole: "Market vendor",
        defenseExam: [.direct("What do you sell at the market?", "\"Baked goods and honey. I have a table at the south end, and I've been selling there for years.\""), .direct("Did you see {D} that morning?", "\"Yes, {D} bought honey from me. {D.He} paid with a ten and I gave change.\""), .direct("Did you think the bill was bad?", "\"Not at the time. I put it in my box and did not mark it. I only learned about counterfeits later.\""), .direct("How do vendors usually handle change?", "\"We keep small bills for change. Sometimes the bills pass from one stall to another. A bad bill can travel around the market all morning.\""), .direct("Has this happened at the market before?", "\"Yes. A few times a year someone passes a bad bill. Usually it's a twenty.\""), .direct("What did the defendant do when security came?", "\"{D.He} looked surprised and upset. {D.He} did not run, and {D.he} said the bills came from change.\""), .cross("Did you check the bill the defendant gave you?", "\"No. I just put it in the box.\""), .cross("Did you see the defendant get bills from another stall?", "\"No. I did not see that.\""), .cross("Did you test your own bills afterward?", "\"I checked my box and found one questionable ten. I'm not sure whose it was.\""), .cross("Do you know the defendant?", "\"No. I only know {DF} as a customer.\""), .cross("Did {D} buy anything else?", "\"Not from me. I only sold honey.\"")],
        theory: ("{D} passed counterfeit tens at three stalls.", "{D} got the bills in change."),
