        ages: 18...60,
        victim: true,
        summary: "{D} bought a riding mower from a small engine shop on {DATE} and paid with a $1,150 check. The bank returned it six days later: account closed. The account had been closed six weeks before the sale. The shop owner sent two letters and a text and heard nothing. {D} says {D.he} thought the account was open.",
        state: [E(.document, 3, "Returned Check", "A $1,150 check returned for a closed account."), E(.document, 3, "Bank Letter", "The account closed six weeks before the sale by notice mailed to {D}."), E(.document, 2, "Bill of Sale", "A sale to {D} for $1,150 signed on {DATE}."), E(.digital, 2, "Texts", "Two texts from the shop and no reply.")],
        defense: [E(.statement, 1, "Thought Open", "{DL} says {D.he} thought the account was open."), E(.document, 1, "Direct Deposit Slip", "A deposit slip from the week before the sale.")],
        role: "Mower shop owner",
        exam: [.direct("What do you own?", "\"A small engine repair and sales shop. We sell riding mowers, trimmers and chainsaws, and I handle the sales paperwork myself.\""), .direct("What happened on {DATE}?", "\"{D} came in and bought a riding mower for $1,150. {D.He} paid by check and signed the bill of sale, and I let {DL} take the mower that day.\""), .direct("What happened to the check?", "\"It came back six days later from the bank, stamped account closed. I deposited it on the next business day.\""), .direct("What did you do when it came back?", "\"I sent a letter right away, then a second letter two weeks later, and I texted {D.him} twice. I never got an answer.\""), .direct("What did you learn from the bank?", "\"The account had been closed six weeks before the sale. The bank sent {DL} a closing notice by mail.\""), .direct("Did you ever recover the mower or the money?", "\"No. The mower is still out there and I never got a dime. A riding mower is a big loss for a shop my size.\""), .cross("Did you ask for ID or call the bank before accepting the check?", "\"I took a license number, and I did not call the bank. I should have, but we take checks regularly from customers.\""), .cross("Do you know if {D} received the bank's notice?", "\"I don't know. I have the bank's letter but not proof it was delivered.\""), .cross("Did you reach the defendant by phone?", "\"I texted twice. I did not get a reply, and the number did not seem to take voicemail.\""), .cross("Did the defendant seem to know there was a problem?", "\"When {D.he} bought the mower, {D.he} was friendly and not hurried. Nothing made me think {D.he} knew.\""), .cross("How did the defendant get the mower home?", "\"In a pickup with a ramp. {D.He} loaded it with my help and drove away.\"")],
        defenseRole: "{DL}'s coworker",
        defenseExam: [.direct("How do you know {D}?", "\"We work at the same plant. I've known {D} for about three years and often carpool.\""), .direct("Do you know about the defendant's banking?", "\"Our paychecks are direct deposit. I know {D.he} gets paid on the same schedule and has never mentioned a bank problem.\""), .direct("Did the defendant talk about buying a mower?", "\"Yes, {D.he} talked about it for weeks. {D.He} was excited about a new mower for the yard.\""), .direct("Did the defendant act like someone who knew the account was closed?", "\"No. {D.He} seemed happy, and told us about the deal at the shop.\""), .direct("What did the defendant say when the check bounced?", "\"{D.He} said it must be a mistake and that {D.he} would call the bank. I don't know if {D.he} did.\""), .direct("Does {D} change addresses often?", "\"Yes. {D.He} has moved twice in the last two years. Mail gets lost.\""), .cross("Did you see the bank notice?", "\"No. I never saw any letters from the bank.\""), .cross("Did you see the defendant's account?", "\"No. I don't see anyone's accounts.\""), .cross("Did the defendant offer to pay?", "\"{D.He} said {D.he} would. I don't know if any payment was made.\""), .cross("Did you know the account was closed?", "\"No. I learned later.\""), .cross("Did the defendant mention the shop's texts?", "\"Once. {D.He} said {D.he} had missed a few messages.\"")],
        theory: ("{D} paid with a check from a closed account.", "{D} thought the account was open."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} had received the closing notice and moved the money.", "{DL}'s paycheck still showed deposits in the account."),
        defendant: [.direct("Why did you buy the mower?", "\"I had a big yard to take care of and the old mower finally died. I found a good deal at the shop.\""), .direct("Why did you pay by check?", "\"I had an account at a bank that I'd used for years. I wrote the check without thinking about it.\""), .direct("Did you know the account had been closed?", "\"No. I thought it was open. My paycheck still showed deposits there the week before the sale.\""), .direct("Did you get a letter from the bank?", "\"I'm not sure. I move around, and a lot of my mail goes to an old address.\""), .direct("Why didn't you answer the shop's letters and texts?", "\"I did not see them in time. I've been working a lot, and that is not an excuse. I should have called.\""), .direct("What are you willing to do now?", "\"Pay for the mower. I would not have bought it if I'd known the account was closed.\""), .cross("The bank closed the account six weeks before you wrote the check, didn't it?", "\"So I'm told. I did not know.\""), .cross("You wrote a $1,150 check on that account, didn't you?", "\"Yes. I wrote it and signed it.\""), .cross("You received two letters and two texts and never replied, did you?", "\"I did not reply. I regret that.\""), .cross("Your deposit slip is from the week before the sale, isn't it?", "\"Yes. That deposit made me think the account was active.\""), .cross("You moved your money before the account closed, didn't you?", "\"I did move some money around at one point. I don't want to guess about the timing.\"")],
        openings: ("{D} bought a $1,150 riding mower with a check drawn on an account that had been closed for six weeks. The bank sent a closing notice, the shop sent two letters and two texts, and {D} never answered. You will see the returned check, the bank's letter and the bill of sale.", "{D} thought the account was open because paychecks still showed deposits. A coworker will tell you {D} bragged about the mower and moves often enough to lose mail. The State must prove {D} knew the account was closed."),
        closings: ("A closed account, a signed check, a mower driven home, and silence after the shop wrote and texted. {D} took $1,150 worth of equipment and gave back nothing. That is a worthless check.", "Nobody proved the bank's notice was ever delivered, and the deposit slip is dated the week before the sale. {D} behaved like someone who thought the check was good. The State has not shown {D} knew."),
        timeline: [(-42, "The bank closes the account."), (0, "{D} buys the mower."), (6, "The check is returned."), (14, "The shop sends the second letter.")],
        identified: "The bill of sale and the check name {D}.",
        notDone: ["The bank's closing letter was never shown to have been delivered.", "The deposit slip was never matched to the account balance."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"],
        genders: ["D": .male])

