        state: [E(.physical, 3, "Scratch Card", "A card with an altered silver panel and glue residue."), E(.document, 3, "Winner List", "The winning card number belongs to a different customer."), E(.document, 2, "Credit Slip", "A $750 store credit issued to {D}."), E(.statement, 2, "Customer Service Clerk", "Issued the credit after scanning the card.")],
        defense: [E(.statement, 1, "Found in Lot", "{DL} says the card was found in the parking lot."), E(.document, 1, "Parking Lot Photo", "A photo of a card on the pavement taken that morning.")],
