        exam: [.direct("What did {D} present at your desk?", "\"A scratch card. I scanned it and issued a $750 store credit.\""), .direct("What did you learn about the card?", "\"The winner list showed the winning card number belonged to a different customer.\""), .direct("What was wrong with the defendant's card?", "\"The silver panel had been scratched and re-covered with a silver sticker. It had glue residue.\""), .direct("What happened at your desk?", "\"{D} handed me a scratch card and asked to redeem it. I scanned it, and the system accepted it as a winner.\""), .direct("What did you do?", "\"I issued a $750 store credit on a slip and {D.he} left. The next morning the real winner called.\""), .direct("What did you see on the card?", "\"A silver panel with a rough edge and glue residue. It looked like a sticker had been placed over scratched-off silver.\""), .cross("{D} says the card was found in the parking lot, doesn't {D.he}?", "\"Yes. A person at the desk says {DL} looked sure about the card.\""), .cross("Did the defendant know the card was altered?", "\"I cannot say. I do not know what {D.he} knew.\""), .cross("Did you check the winner list first?", "\"No. I checked it later. I should have checked first.\""), .cross("The card scanned as a valid number, didn't it?", "\"Yes. The number was real, and I did not look closely at the panel.\""), .cross("You cannot say how it was altered, can you?", "\"No. I only know what the lab said afterward.\"")],
        defenseRole: "Customer at the desk",
        defenseExam: [.direct("Did {D} seem sure of the scratch card at the desk?", "\"Very. {D} seemed excited and confident, and I thought {DF} really believed the card had won a prize.\""), .direct("Did you see anything wrong with the scratch card itself?", "\"I did not see anything. It looked fine to me from where I was standing in line behind {D.him}.\""), .direct("Did the clerk check the winner list before issuing the credit?", "\"Later, I think. The clerk scanned the card first and checked the list afterward, once {DF} was gone.\""), .direct("What were you doing at the store?", "\"I was at the desk returning an item when {D.he} came up. I stood a few feet away.\""), .direct("What did you see?", "\"{DF} handed the clerk a card and the clerk scanned it. The clerk handed over a slip.\""), .direct("How did the defendant act?", "\"Casual and quiet. {D.He} did not seem nervous.\""), .cross("Did the defendant leave the store with the $750 credit?", "\"Yes. {D.He} left with the $750 credit in hand and went toward the front doors of the store.\""), .cross("Did the defendant look nervous while at the customer service desk?", "\"No. {DF} looked happy and excited. That is all I saw, and nothing about {DF} struck me as odd.\""), .cross("Did you hear the defendant say where the card had come from?", "\"Not that I recall. {D.He} just handed the card over, and I did not hear any explanation about it.\""), .cross("You did not see the card up close, did you?", "\"No. I saw it in a hand.\""), .cross("You do not know where {D} got it, do you?", "\"No.\"")],
        theory: ("{D} altered a card and collected a prize.", "{D} found the card and redeemed it."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} had bought a sheet of silver stickers the day before.", "{DL} did find a card but did not know it was altered."),
        defendant: [.direct("Did you alter the scratch card?", "\"No. I found the card in the parking lot. I did not know it was altered.\""), .direct("Did you buy silver stickers?", "\"I bought a sheet the day before for a craft project. It had nothing to do with the card.\""), .direct("Where did you get the card?", "\"I found it on the pavement in the parking lot that morning. It looked scratched, and I took it to the desk.\""), .direct("Why did you take it to the desk?", "\"I thought it might be a winner and wanted to redeem it. I did not look at the silver panel.\""), .direct("What did you do with the credit?", "\"I bought tools and paint. I was surprised it worked.\""), .direct("What did you do with the store credit after the desk issued it?", "\"I spent part of it on tools and kept the rest on the card. I did not think the credit was anything but a lucky win.\""), .cross("The silver panel had glue residue, didn't it?", "\"I did not look closely. I do not know how that got there.\""), .cross("The winning card belongs to someone else, doesn't it?", "\"I know that now. I did not know it then.\""), .cross("You collected a $750 credit on a card you found. Why not turn it in?", "\"I wish I had. I got excited.\""), .cross("You bought silver stickers the day before, didn't you?", "\"Yes, for a craft project. It had nothing to do with the card.\""), .cross("The card was altered, wasn't it?", "\"So I have been told. I did not notice.\"")],
        openings: ("{D} presented a scratch card at a hardware store's customer service desk and collected a $750 store credit. The winning card number belongs to another customer, and {D}'s card had a silver panel scratched off and re-covered with a sticker.", "Jurors will hear that {D} found the card in the parking lot, did not know it was altered, and sincerely believed it was a winner."),
        closings: ("A winning card that belongs to someone else, an altered silver panel with glue residue, and a $750 credit collected by {D}. {D} had bought silver stickers the day before.", "A card found in a parking lot and a customer who believed it had won. The State must prove {D} altered it or knew it had been altered."),
        timeline: [(0, "10 a.m.: {D} presents the card."), (0, "10:05 a.m.: the credit is issued."), (2, "The winner calls the store."), (3, "The store reports the card.")],
        identified: "The store's service desk camera identifies {D}.",
        notDone: ["The card's printed batch number was never read.", "The real winner was never interviewed about a lost card."],
