        genders: ["D": .male])

    static let bingoCheatV1 = SmallCases.make(
        key: "story.bingoCheat",
        category: .whiteCollar,
        headlines: ["Volunteer Fire Department 50/50 Winner Pulled From Barrel Turns Out Altered", "Stub Mismatch Shows Winning Ticket Was Not From the Roll"],
        law: "falsePretenses",
        spec: "Obtained $750 from {V}, a volunteer fire department, by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "At a volunteer fire department fundraiser on {DATE}, {D} presented a winning 50/50 ticket and collected the $750 pot. The ticket numbers on the stub did not match the roll sold that night, and the ink was a different color. A camera at the ticket table shows {D} near the barrel before the drawing. {D} says the ticket was bought and carried a printing error.",
        state: [E(.physical, 3, "Winning Ticket", "A ticket with a hand-altered number and a different ink color."), E(.document, 3, "Ticket Roll", "The roll's numbers do not include the winning number."), E(.video, 2, "Ticket Table Camera", "{D} stands at the barrel before the drawing and returns later to claim the prize."), E(.statement, 2, "Fire Department Treasurer", "The prize was paid in cash at 8:45 p.m.")],
        defense: [E(.statement, 1, "Printing Error", "{DL} says the ticket came off the roll with a printing error."), E(.document, 1, "Roll Receipt", "A receipt for the purchase of three tickets at 7:40 p.m.")],
        role: "Fire department treasurer",
        exam: [.direct("What is your role with the fire department?", "\"I'm the treasurer. I handle the money at our fundraisers, and at the 50/50 raffle on {DATE} I paid out the prize.\""), .direct("How does the 50/50 work?", "\"We sell numbered tickets from a roll, keep the stubs in a barrel, and draw a stub at 8:30. Half the pot goes to the winner.\""), .direct("What happened when the winner claimed the prize?", "\"At 8:45 {D} presented a ticket and collected the $750 pot in cash. I paid {DL} and wrote it down.\""), .direct("What was wrong with the ticket?", "\"The number on the winning ticket was not on the roll sold that night. The ink on the number was a different color from the printed ones.\""), .direct("How did you notice?", "\"When I compared the ticket to the roll afterward, the number simply did not exist. It looked hand-altered, like one digit had been overwritten.\""), .direct("What does the ticket table camera show?", "\"{D.He} stands near the barrel before the drawing, then returns after to claim the prize.\""), .cross("Was the drawn stub ever found?", "\"The stub for the winning number was in the barrel, but the number matched a ticket nobody else claimed. I never found the owner.\""), .cross("Did {D} buy tickets that night?", "\"A receipt shows {DL} bought three tickets at 7:40 p.m. So {DL} was a legitimate participant.\""), .cross("Did you examine the printer that made the roll?", "\"No. We bought the roll from a vendor, and nobody checked the printer.\""), .cross("Can tickets come off a roll with a printing blur?", "\"Sometimes the ink smears, yes. I've seen it. But a blur does not change a number to a different one.\""), .cross("Did the defendant protest when you questioned the ticket?", "\"{D.He} said the ticket came off the roll like that. {D.He} stayed calm and did not argue.\"")],
        defenseRole: "Raffle volunteer",
        defenseExam: [.direct("What did you do at the fundraiser?", "\"I volunteered at the raffle table, selling tickets and keeping the barrel in order.\""), .direct("Do you remember {D}?", "\"Yes. {D} bought three tickets from me at about 7:40. I tore them off the roll and handed them over.\""), .direct("Did the roll have any problems?", "\"The printer ran low on ink that night. Some numbers were faint or blotchy, and I remember grumbling about it.\""), .direct("Did you see the defendant near the barrel?", "\"I saw {DF} standing near it before the drawing, along with many other people. It's an open barrel, and people look in.\""), .direct("How was the barrel handled?", "\"It was uncovered. People could reach in or look at the stubs if they wanted. I can't say nobody touched it.\""), .direct("What happened when the winner was called?", "\"{D.He} came up with a ticket and the treasurer paid. At the time I did not see anything unusual.\""), .cross("Did you see the defendant alter a ticket?", "\"No. I did not see anything like that.\""), .cross("Was the winning number on your roll?", "\"I did not check it. I only know the roll I sold from.\""), .cross("Did all the tickets come from your roll?", "\"Mostly. There was another roll at the second table.\""), .cross("Did you see the defendant pull the stub?", "\"No. The stubs were drawn by a guest.\""), .cross("Were any numbers duplicated?", "\"I'm not aware of any.\"")],
        theory: ("{D} altered a ticket and collected the pot.", "{D} held a ticket with a printing error."),
        allocution: "\"I let money decide it, and I can't take it back.\"",
        truths: ("{DL} had a pen matching the ink in a jacket pocket.", "{DL}'s purchased tickets did have a printing blur."),
        defendant: [.direct("Did you buy tickets that night?", "\"Yes. I bought three tickets at 7:40 p.m. I always buy a few at the fire department's events.\""), .direct("What was wrong with your ticket?", "\"The number was blurry, like the printer smeared it. I thought the ticket was fine and kept it.\""), .direct("Why were you near the barrel before the drawing?", "\"I was watching, like everyone else. I wanted to see the stubs go in. I did not touch anything.\""), .direct("Did you alter the number?", "\"No. I did not change a single digit. The ticket looked like that when it came off the roll.\""), .direct("Why did you collect the prize?", "\"My number was called. I walked up and claimed it as anyone would.\""), .direct("What did you do after being questioned?", "\"I answered every question. I gave back the money when the treasurer asked.\""), .cross("The winning number is not on the roll, is it?", "\"That is what I'm told. I don't understand how that happened.\""), .cross("The ink on the number is a different color, isn't it?", "\"It looks different, yes. I think the printer was changing ink that night.\""), .cross("You had a pen in your jacket pocket, didn't you?", "\"I always carry a pen. I did not write on the ticket.\""), .cross("You were by the barrel before the drawing, weren't you?", "\"Yes. I stood there for a few minutes. Many people did.\""), .cross("You collected $750 for a ticket that nobody can match to the roll, didn't you?", "\"Yes. I did not know it was a problem.\"")],
        openings: ("At a volunteer fire department fundraiser, {D} collected the $750 pot with a ticket whose number was not on the roll sold that night. The ink was a different color, and the camera shows {D} at the barrel before the drawing. You will hear from the treasurer who paid out the prize.", "{D} bought three tickets at 7:40 and held a ticket with a blur that came off the roll. A raffle volunteer will tell you the printer ran low on ink that night and the barrel was open to anyone. No one ever found the real owner of the winning number."),
        closings: ("A number that is not on the roll, ink that does not match, and {D} standing at the barrel before the drawing. {D} collected $750. The simplest explanation is that the ticket was altered.", "The printer was never examined, the roll was running out of ink, and the barrel was open to everyone. The winning number's owner was never found. A blurry ticket is not proof of a forged one."),
        timeline: [(0, "7:40 p.m.: {D} buys three tickets."), (0, "8:30 p.m.: the drawing."), (0, "8:45 p.m.: {D} collects the pot."), (1, "The treasurer compares the ticket to the roll.")],
        identified: "The camera and the claim identify {D}.",
        notDone: ["The roll's printer was never examined.", "The winning number's owner was never found."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

    static let craigslistHorseV1 = SmallCases.make(
        key: "story.craigslistHorse",
        category: .whiteCollar,
        headlines: ["Seller Takes $1,200 Deposit for Kayak Package That Does Not Exist", "Marketplace Ad Photos Traced to Another Seller's Listing"],
        law: "falsePretenses",
        spec: "Obtained $1,200 from {V} by false pretenses, on {DATE}.",
        ages: 18...60,
        victim: true,
        summary: "{D} listed a kayak and paddle package for $2,400 online and told {V} on {DATE} that a $1,200 deposit would hold it. {V} paid by money transfer and was told pickup would be Saturday. {D} stopped answering. The photos in the ad were taken from another seller's listing two states away. {D} says the kayaks sold to another buyer first.",
        state: [E(.digital, 3, "Marketplace Ad", "A listing for a kayak package with photos from another seller's ad."), E(.digital, 3, "Payment Record", "A $1,200 transfer from {V} to {D}'s account on {DATE}."), E(.digital, 2, "Messages", "{D} promises Saturday pickup and then goes silent."), E(.statement, 2, "Other Seller", "Confirmed the photos were from the other listing and never sold to {D}.")],
        defense: [E(.statement, 1, "Sold First", "{DL} says the kayaks sold to another buyer first."), E(.document, 1, "Sale Receipt", "A sale receipt for two kayaks to a different buyer.")],
        role: "Buyer",
        exam: [.direct("What were you looking to buy?", "\"A kayak and paddle package. I found a listing online for $2,400 that included two kayaks, paddles and life vests, which seemed like a good price.\""), .direct("How did you communicate with {D}?", "\"Through the marketplace's messages. {D} said a $1,200 deposit would hold the kayaks and the balance was due at pickup.\""), .direct("How did you pay?", "\"By money transfer, $1,200, on {DATE}. {D.He} confirmed the receipt and promised pickup on Saturday.\""), .direct("What happened on Saturday?", "\"I drove to the pickup spot and waited. Nobody came, and {D.he} stopped answering my messages.\""), .direct("What did you find about the ad?", "\"The photos were from another seller's listing two states away. I recognized the same kayaks and the same background when I looked up that seller.\""), .direct("What did you do?", "\"I reported the deposit to the Sheriff's Office about ten days after I paid. I gave them the messages and the payment record.\""), .cross("Did the defendant ever say the kayaks were gone?", "\"No. {D.He} never said anything after the Saturday promise. All I got was silence.\""), .cross("Did you see the kayaks in person before paying?", "\"No. I relied on the photos. That was a mistake.\""), .cross("Did you check the account name before sending money?", "\"The transfer showed {D.his} name. I did not do more checking than that.\""), .cross("Could the defendant have sold the kayaks to someone else?", "\"I don't know. {D.He} never told me. I only know I never got mine.\""), .cross("Did you ask for a refund?", "\"Yes, in a message. I did not get a reply.\"")],
        defenseRole: "Paddling friend",
        defenseExam: [.direct("How do you know {D}?", "\"We paddle together on the lake. I have known {D} for several years, and we go out together most weekends in the warm months.\""), .direct("Did the defendant sell kayaks?", "\"Yes, {DF} buys and sells used boats on the side. I have seen {DF} with several sets in the driveway over the years.\""), .direct("What did the defendant tell you about this deal?", "\"{D.He} told me another buyer showed up with cash and took the kayaks first. {D.He} was upset about how it all turned out.\""), .direct("Did you see a sale?", "\"I saw {DF} hand two kayaks to someone in a driveway one afternoon. I believe a receipt was written, though I did not read it.\""), .direct("How does the defendant handle messages from customers?", "\"Not well. {DF} is disorganized, lets messages pile up, and has been late answering people before. It is a known habit among our paddling friends.\""), .direct("Did the defendant mention a deposit?", "\"Not to me, no. I did not know about any deposit until the Sheriff's Office called me about this case.\""), .cross("Did you see the receipt for the sale?", "\"Only briefly, from several feet away. I could not read the buyer's name or tell you the price.\""), .cross("When was that sale?", "\"Around the same week as the listing, but I cannot give you the exact date. I did not write it down.\""), .cross("Did {D} refund anyone you know of?", "\"I am not aware of any refund. If {D.he} gave one, it was not something I heard about.\""), .cross("Did you see the ad with the photos?", "\"I never saw the ad, so I cannot tell you whether the photos were {DF}'s or somebody else's.\""), .cross("Does the defendant owe other people money?", "\"Not that I know of. {DF} has never mentioned it, and I would not speculate about someone's finances.\"")],
        theory: ("{D} took a deposit for kayaks that were not for sale.", "The kayaks sold to someone else first."),
        allocution: "\"I took advantage of someone who trusted me, and I'm sorry.\"",
        truths: ("{DL} had posted the same ad for three other buyers.", "{DL} did sell kayaks and did not update the ad."),
        defendant: [.direct("Did you own kayaks?", "\"Yes. I sell used kayaks and paddling gear. I had a couple of sets listed at that time.\""), .direct("Why did you take a deposit from {V}?", "\"The listing was real, and {V} wanted to hold the package. I took the deposit to reserve it.\""), .direct("What happened to the kayaks?", "\"Another buyer came in with cash and took them first. I did not update the ad right away.\""), .direct("Why did you stop answering?", "\"I was embarrassed. I had promised the kayaks to {V}, and I did not know how to tell {V} they were gone.\""), .direct("Where did the photos come from?", "\"I used pictures from the internet that looked like my kayaks. I should not have used someone else's photos.\""), .direct("What do you plan to do?", "\"Refund the deposit. I'm sorry I did not do it sooner.\""), .cross("The photos in your ad were from another seller, weren't they?", "\"Yes. I borrowed them. I understand that is misleading.\""), .cross("You took $1,200 and never delivered anything, did you?", "\"That's right. I did not deliver anything, and I did not give the money back.\""), .cross("You promised Saturday pickup after you sold the kayaks, didn't you?", "\"I think I messaged before I sold them, but I'm not sure of the order.\""), .cross("You never told {V} the kayaks had sold, did you?", "\"No. I let the messages go unanswered.\""), .cross("You had posted a similar ad for other buyers, hadn't you?", "\"I'm not going to guess about that.\"")],
        openings: ("{D} listed a kayak package for $2,400, took a $1,200 deposit from {V}, promised Saturday pickup, and went silent. The photos in the ad belonged to another seller two states away. You will see the ad, the transfer and the messages.", "{D} really did sell kayaks, and a friend saw two handed to another buyer. {D} was disorganized and embarrassed, not a con artist. The State must prove {D} never meant to deliver."),
        closings: ("$1,200 sent, a Saturday promise, and a silence that has lasted ever since. The ad's photos were stolen from another seller. {V} never saw a kayak.", "A real seller of used kayaks, a real sale to someone else, and a bad habit of ignoring messages. The other buyers were never asked what {D} told them, and the third-party sale was never documented. The State must prove a plan to defraud."),
        timeline: [(0, "{V} pays the deposit."), (1, "{D} promises Saturday pickup."), (5, "Saturday: no one comes."), (10, "{V} reports the deposit to the Sheriff's Office.")],
        identified: "The payment record is tied to {D}'s account.",
        notDone: ["The other buyers were never asked what {DL} told them.", "The kayak sale to a third party was never documented."],
        mood: .indifferent,
        doctrines: ["burdenOfProof"])

