        exam: [.direct("What condition was the apartment in when you moved out?", "\"Clean. I left it spotless and took date-stamped photos that show no damage.\""), .direct("What did {D} send you two weeks later?", "\"A letter keeping my $1,500 deposit and billing $500 more for repairs, with an invoice for $2,000 from a contractor.\""), .direct("What did you learn about the contractor?", "\"The license number is not in the state database, and the contractor's phone number rings to {D}'s phone.\""), .direct("How was the unit when you left?", "\"Clean, with the walls patched and the carpet vacuumed. I took date-stamped photos of every room.\""), .direct("What did the defendant send you?", "\"A letter two weeks later keeping my $1,500 deposit and billing $500 more for repairs. An invoice for $2,000 was attached.\""), .direct("What did you find about the contractor?", "\"The license number was not in the state database, and the phone number rang to {D.his} phone.\""), .cross("{D} says a friend did the work, doesn't {D.he}?", "\"Yes. A friend did some touch-up painting, I understand.\""), .cross("Did you notice any damage at move-out?", "\"No. The unit was clean and undamaged.\""), .cross("Did the defendant walk through the unit with you?", "\"I do not recall. I took my own photos.\""), .cross("You did not do a walkthrough with the defendant, did you?", "\"No. I left the keys in the mailbox and sent photos.\""), .cross("The unit was repainted before you moved out, wasn't it?", "\"Some walls were freshly painted when I moved in. I did nothing to damage them.\"")],
